type MissionStatus = 'active' | 'completed' | 'cancelled'
type MissionLifecycleState =
  | 'draft'
  | 'validating'
  | 'scheduled'
  | 'dispatching'
  | 'running'
  | 'verifying'
  | 'completed'
  | 'failed'
  | 'cancelled'

