function unwrapCanonicalApiPayload(payload: unknown): unknown {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return payload
  const record = payload as Record<string, unknown>
  if (record.ok === true && Object.prototype.hasOwnProperty.call(record, 'data')) return record.data
  if (record.ok === false && record.error && typeof record.error === 'object' && !Array.isArray(record.error)) {
    const error = record.error as Record<string, unknown>
    if (Object.prototype.hasOwnProperty.call(error, 'detail')) return error.detail
  }
  return payload
}

const shiftTimers = new Map<string, NodeJS.Timeout>()
const activeShifts = new Map<string, Shift>()
const managedBatchTimers = new Map<string, NodeJS.Timeout[]>()
const missionTimers = new Map<string, NodeJS.Timeout>()
const missionLoopTimers = new Map<string, NodeJS.Timeout>()
const missionRunControllers = new Map<string, AbortController>()
const missions = new Map<string, Mission>()
const missionFeed: MissionFeedEvent[] = []
const missionReports = new Map<string, BackendMissionReport>()
const TIMED_MISSION_AGENT_TIMEOUT_SECONDS = 900
const MISSION_CRON_EXPIRY_SWEEP_MS = 30_000
let missionCronExpirySweepTimer: NodeJS.Timeout | null = null
let missionCronExpirySweepInFlight: Promise<void> | null = null
const agentTurnSessions = new Map<string, string>()

function agentTurnSessionScope(agentId: string, sessionKey?: string | null) {
  const cleanSessionKey = typeof sessionKey === 'string' ? sessionKey.trim() : ''
  return cleanSessionKey ? `${agentId}:${cleanSessionKey}` : agentId
}

function agentTurnSessionScopeAgentId(scope: string) {
  return scope.split(':', 1)[0] || scope
}

function agentTurnSessionScopeMatchesAgent(scope: string, agentId?: string) {
  return !agentId || scope === agentId || scope.startsWith(`${agentId}:`)
}

type OpenClawRunStatus = 'running' | 'completed' | 'failed' | 'timeout' | 'aborted' | 'interrupted'

type OpenClawRunRecord = {
  id: string
  command: string
  agentId?: string
  sessionId?: string
  sessionKey?: string
  cwd: string
  timeoutMs: number
  startedAt: string
  endedAt?: string
  elapsedMs?: number
  status: OpenClawRunStatus
  pid?: number
  exitCode?: number
  stdoutPreview?: string
  stderrPreview?: string
  failureKind?: FailureKind
}

const OPENCLAW_RECENT_RUN_LIMIT = 80
const activeOpenClawRuns = new Map<string, OpenClawRunRecord>()
const recentOpenClawRuns: OpenClawRunRecord[] = []

function openClawRunLedgerPayload(record: OpenClawRunRecord) {
  return {
    ...record,
    stdoutPreview: record.stdoutPreview || '',
    stderrPreview: record.stderrPreview || '',
  }
}

async function persistOpenClawRunLedgerSnapshot(record: OpenClawRunRecord) {
  await appendRuntimeRunLedger(openClawRunLedgerPayload(record), { sqlite: false })
}

function persistOpenClawRunLedgerSnapshotSoon(record: OpenClawRunRecord) {
  setTimeout(() => {
    void persistOpenClawRunLedgerSnapshot(record).catch(() => undefined)
  }, 0).unref?.()
}

function interruptedOpenClawRunFromLedger(record: OpenClawRunRecord): OpenClawRunRecord | null {
  if (record.status !== 'running') return null
  if (activeOpenClawRuns.has(record.id)) return null
  const startedMs = Date.parse(record.startedAt)
  if (!Number.isFinite(startedMs)) return null
  if (startedMs >= CONTROL_CENTER_STARTED_AT_MS - 1000) return null
  if (!isRuntimeMonitorEntryVisible(record.startedAt)) return null
  const elapsedMs = Math.max(0, CONTROL_CENTER_STARTED_AT_MS - startedMs)
  const timeoutMs = Number.isFinite(record.timeoutMs) && record.timeoutMs > 0 ? record.timeoutMs : 0
  const timedOut = timeoutMs > 0 && elapsedMs >= timeoutMs
  return {
    ...record,
    status: timedOut ? 'timeout' : 'interrupted',
    endedAt: new Date(CONTROL_CENTER_STARTED_AT_MS).toISOString(),
    elapsedMs,
    exitCode: 1,
    failureKind: timedOut ? 'timeout' : 'interrupted',
    stderrPreview: timedOut
      ? 'Control Center restarted after this runtime call exceeded its wrapper timeout.'
      : 'Control Center restarted before this runtime call emitted a terminal event.',
  }
}

async function readRuntimeMonitorClearedAtMs() {
  try {
    const raw = await fs.readFile(RUNTIME_MONITOR_CLEAR_MARKER_PATH, 'utf-8')
    const parsed = JSON.parse(raw) as { clearedAt?: unknown; clearedAtMs?: unknown }
    const fromIso = typeof parsed.clearedAt === 'string' ? Date.parse(parsed.clearedAt) : NaN
    const fromMs = typeof parsed.clearedAtMs === 'number' ? parsed.clearedAtMs : NaN
    const value = Number.isFinite(fromIso) ? fromIso : fromMs
    return Number.isFinite(value) && value > 0 ? value : 0
  } catch {
    return 0
  }
}

async function writeRuntimeMonitorClearMarker(clearedAt: Date) {
  await fs.mkdir(path.dirname(RUNTIME_MONITOR_CLEAR_MARKER_PATH), { recursive: true })
  const payload = {
    clearedAt: clearedAt.toISOString(),
    clearedAtMs: clearedAt.getTime(),
  }
  await fs.writeFile(RUNTIME_MONITOR_CLEAR_MARKER_PATH, `${JSON.stringify(payload, null, 2)}\n`, 'utf-8')
}

async function hydrateRecentOpenClawRunsFromLedger() {
  runtimeMonitorClearedAtMs = Math.max(runtimeMonitorClearedAtMs, await readRuntimeMonitorClearedAtMs())
  const records = await readRuntimeRunLedgerTail<OpenClawRunRecord>(OPENCLAW_RECENT_RUN_LIMIT * 3)
  if (!records.length) return
  recentOpenClawRuns.length = 0
  const recovered: OpenClawRunRecord[] = []
  const seenIds = new Set<string>()
  for (const record of [...records].reverse()) {
    if (!record?.id || seenIds.has(record.id)) continue
    seenIds.add(record.id)
    if (record.status === 'running') {
      const interrupted = interruptedOpenClawRunFromLedger(record)
      if (!interrupted) continue
      recentOpenClawRuns.push(interrupted)
      recovered.push(interrupted)
      continue
    }
    if (!isRuntimeMonitorEntryVisible(record.endedAt || record.startedAt)) continue
    recentOpenClawRuns.push(record)
  }
  if (recentOpenClawRuns.length > OPENCLAW_RECENT_RUN_LIMIT) recentOpenClawRuns.length = OPENCLAW_RECENT_RUN_LIMIT
  if (recovered.length) {
    await Promise.allSettled(recovered.slice(0, OPENCLAW_RECENT_RUN_LIMIT).map((record) => persistOpenClawRunLedgerSnapshot(record)))
    pushGatewayLog('lifecycle', `recovered ${recovered.length} interrupted runtime run(s) from the ledger after restart`)
  }
}

type ProviderConversationRole = 'user' | 'assistant'
type ProviderConversationMessage = {
  role: ProviderConversationRole
  content: string
  reasoningContent?: string
}

type ProviderConversationState = {
  sessionId: string
  provider: string
  modelId: string
  messages: ProviderConversationMessage[]
  updatedAt: number
}

const providerConversationHistories = new Map<string, ProviderConversationState>()
const MAX_PROVIDER_CONVERSATION_MESSAGES = 24
const MAX_PROVIDER_CONVERSATION_CHARS = 60_000

function providerConversationChars(messages: ProviderConversationMessage[]) {
  return messages.reduce((total, message) => total + message.content.length + (message.reasoningContent?.length || 0), 0)
}

function trimProviderConversationMessages(messages: ProviderConversationMessage[]) {
  let next = messages.filter((message) => message.content.trim() || message.reasoningContent?.trim())
  if (next.length > MAX_PROVIDER_CONVERSATION_MESSAGES) next = next.slice(-MAX_PROVIDER_CONVERSATION_MESSAGES)
  while (next.length > 2 && providerConversationChars(next) > MAX_PROVIDER_CONVERSATION_CHARS) {
    next = next.slice(2)
  }
  return next
}

function providerConversationMessagesForRequest(
  sessionId: string,
  provider: string,
  modelId: string,
  userContent: string,
) {
  const existing = providerConversationHistories.get(sessionId)
  if (
    existing &&
    (existing.provider.trim().toLowerCase() !== provider.trim().toLowerCase() ||
      modelRefKeyFromId(existing.modelId) !== modelRefKeyFromId(modelId))
  ) {
    providerConversationHistories.delete(sessionId)
  }
  const history = providerConversationHistories.get(sessionId)?.messages || []
  return trimProviderConversationMessages([...history, { role: 'user', content: userContent }])
}

function saveProviderConversationTurn(
  sessionId: string,
  provider: string,
  modelId: string,
  requestMessages: ProviderConversationMessage[],
  assistant: { content: string; reasoningContent?: string },
) {
  providerConversationHistories.set(sessionId, {
    sessionId,
    provider,
    modelId,
    messages: trimProviderConversationMessages([
      ...requestMessages,
      {
        role: 'assistant',
        content: assistant.content,
        reasoningContent: assistant.reasoningContent,
      },
    ]),
    updatedAt: Date.now(),
  })
}

function clearAgentTurnSessions(agentId?: string) {
  if (agentId) {
    let sessions = 0
    let histories = 0
    for (const [scope, sessionId] of Array.from(agentTurnSessions.entries())) {
      if (!agentTurnSessionScopeMatchesAgent(scope, agentId)) continue
      agentTurnSessions.delete(scope)
      sessions += 1
      if (providerConversationHistories.delete(sessionId)) histories += 1
    }
    return { sessions, histories }
  }
  const sessions = agentTurnSessions.size
  const histories = providerConversationHistories.size
  agentTurnSessions.clear()
  providerConversationHistories.clear()
  return { sessions, histories }
}

function resetAgentTurnSessionsForModelChange(agentId: string) {
  const reset = clearAgentTurnSessions(agentId)
  if (reset.sessions || reset.histories) {
    pushGatewayLog(
      'lifecycle',
      `model config changed for ${agentId}; reset ${reset.sessions} active session(s) and ${reset.histories} provider history cache(s)`,
    )
  }
  return reset
}

function abortGatewayChatOpenClawRun(run: OpenClawRunRecord, reason = 'runtime session close') {
  if (!run.sessionKey) return false
  const client = gatewayClientState?.client
  if (!client) return false
  void client.request('chat.abort', { sessionKey: run.sessionKey, runId: run.id }, { timeoutMs: 2_000 }).catch(() => undefined)
  finishOpenClawRun(run, 'aborted', { code: 1, failureKind: 'aborted', stderr: reason })
  return true
}

function normalizeGatewaySessionKey(value: string | null | undefined, agentId?: string) {
  const raw = typeof value === 'string' ? value.trim() : ''
  if (!raw) return ''
  if (raw.startsWith('agent:')) return raw
  return agentId ? `agent:${agentId}:${raw}` : raw
}

function runtimeSessionKeyFromScope(scope: string, agentId: string) {
  if (!scope.startsWith(`${agentId}:`)) return ''
  return normalizeGatewaySessionKey(scope.slice(agentId.length + 1), agentId)
}

type GatewayRuntimeSessionAbortResult = {
  sessionKey: string
  runId?: string
  agentId?: string
  sessionId?: string
  ok: boolean
  method: 'sessions.abort' | 'chat.abort' | 'gateway-client'
  detail?: string
}

type RuntimeSessionCloseInput = {
  agentId?: string
  sessionId?: string
  sessionKey?: string
  all?: boolean
}

function runtimeCloseMatchesRun(input: RuntimeSessionCloseInput, run: OpenClawRunRecord) {
  if (input.all) return true
  const targetSessionKey = normalizeGatewaySessionKey(input.sessionKey, input.agentId || run.agentId)
  if (targetSessionKey && run.sessionKey !== targetSessionKey) return false
  if (input.agentId && run.agentId !== input.agentId) return false
  if (input.sessionId && run.sessionId !== input.sessionId) return false
  return true
}

function runtimeCloseMatchesSession(input: RuntimeSessionCloseInput, scope: string, sessionId: string) {
  if (input.all) return true
  const agentId = agentTurnSessionScopeAgentId(scope)
  const scopedSessionKey = runtimeSessionKeyFromScope(scope, agentId)
  const targetSessionKey = normalizeGatewaySessionKey(input.sessionKey, input.agentId || agentId)
  if (targetSessionKey && scopedSessionKey && scopedSessionKey !== targetSessionKey) return false
  if (targetSessionKey && !scopedSessionKey && !input.agentId && !input.sessionId) return false
  if (input.agentId && !agentTurnSessionScopeMatchesAgent(scope, input.agentId)) return false
  if (input.sessionId && sessionId !== input.sessionId) return false
  return true
}

function gatewayAbortCandidatesForRuntimeClose(input: RuntimeSessionCloseInput) {
  const candidates = new Map<string, { sessionKey: string; runId?: string; agentId?: string; sessionId?: string }>()
  const add = (candidate: { sessionKey?: string; runId?: string; agentId?: string; sessionId?: string }) => {
    const sessionKey = normalizeGatewaySessionKey(candidate.sessionKey, candidate.agentId || input.agentId)
    if (!sessionKey) return
    const key = `${sessionKey}\0${candidate.runId || ''}`
    candidates.set(key, { ...candidate, sessionKey })
  }

  add({ sessionKey: input.sessionKey, agentId: input.agentId, sessionId: input.sessionId })
  for (const run of activeOpenClawRuns.values()) {
    if (!runtimeCloseMatchesRun(input, run)) continue
    add({ sessionKey: run.sessionKey, runId: run.id, agentId: run.agentId, sessionId: run.sessionId })
  }
  for (const [scope, sessionId] of agentTurnSessions.entries()) {
    if (!runtimeCloseMatchesSession(input, scope, sessionId)) continue
    const agentId = agentTurnSessionScopeAgentId(scope)
    add({ sessionKey: runtimeSessionKeyFromScope(scope, agentId), agentId, sessionId })
  }
  return Array.from(candidates.values()).slice(0, 25)
}

async function requestGatewaySessionAbort(candidate: { sessionKey: string; runId?: string; agentId?: string; sessionId?: string }): Promise<GatewayRuntimeSessionAbortResult> {
  let state: GatewayClientState
  try {
    state = gatewayClientState?.ready
      ? gatewayClientState
      : await ensureControlCenterGatewayClient(AbortSignal.timeout(5_000))
  } catch (error) {
    return {
      ...candidate,
      ok: false,
      method: 'gateway-client',
      detail: redactSensitiveText(String(error)),
    }
  }

  const params = {
    key: candidate.sessionKey,
    ...(candidate.runId ? { runId: candidate.runId } : {}),
  }
  try {
    const payload = await state.client.request('sessions.abort', params, { timeoutMs: 3_000 })
    if (!isLooseRecord(payload) || payload.ok !== false) {
      return {
        ...candidate,
        ok: true,
        method: 'sessions.abort',
        detail: isLooseRecord(payload) && typeof payload.status === 'string' ? payload.status : undefined,
      }
    }
    throw new Error(typeof payload.error === 'string' ? payload.error : 'sessions.abort returned ok=false')
  } catch (sessionsAbortError) {
    try {
      const payload = await state.client.request('chat.abort', {
        sessionKey: candidate.sessionKey,
        ...(candidate.runId ? { runId: candidate.runId } : {}),
      }, { timeoutMs: 3_000 })
      return {
        ...candidate,
        ok: !isLooseRecord(payload) || payload.ok !== false,
        method: 'chat.abort',
        detail: isLooseRecord(payload) && typeof payload.status === 'string'
          ? payload.status
          : redactSensitiveText(String(sessionsAbortError)),
      }
    } catch (chatAbortError) {
      return {
        ...candidate,
        ok: false,
        method: 'chat.abort',
        detail: redactSensitiveText(String(chatAbortError)),
      }
    }
  }
}

async function abortGatewayRuntimeSessionsForClose(input: RuntimeSessionCloseInput) {
  const candidates = gatewayAbortCandidatesForRuntimeClose(input)
  const results: GatewayRuntimeSessionAbortResult[] = []
  for (const candidate of candidates) {
    results.push(await requestGatewaySessionAbort(candidate))
  }
  const okCount = results.filter((result) => result.ok).length
  if (results.length) {
    pushGatewayLog(
      okCount === results.length ? 'lifecycle' : 'stderr',
      `gateway abort requested for ${okCount}/${results.length} runtime session(s)`,
    )
  }
  return results
}

function terminateOpenClawRunsForSession(input: RuntimeSessionCloseInput) {
  const terminated: Array<{ id: string; pid: number | null; agentId?: string; sessionId?: string }> = []
  for (const run of Array.from(activeOpenClawRuns.values())) {
    if (!runtimeCloseMatchesRun(input, run)) continue
    if (!run.pid) {
      if (abortGatewayChatOpenClawRun(run)) {
        pushGatewayLog('lifecycle', `abort requested for gateway chat runtime call ${run.id}`)
        terminated.push({ id: run.id, pid: null, agentId: run.agentId, sessionId: run.sessionId })
      }
      continue
    }
    try {
      void terminateProcessTree(run.pid, 'runtime session close')
      pushGatewayLog('lifecycle', `close requested for runtime call ${run.id} (pid=${run.pid})`)
      terminated.push({ id: run.id, pid: run.pid, agentId: run.agentId, sessionId: run.sessionId })
    } catch (error) {
      pushGatewayLog('lifecycle', `failed to terminate runtime call ${run.id}: ${String(error)}`)
      terminated.push({ id: run.id, pid: run.pid, agentId: run.agentId, sessionId: run.sessionId })
    }
  }
  return terminated
}

function closeRuntimeSessions(input: RuntimeSessionCloseInput) {
  const closed: Array<{ agentId: string; sessionId: string; scope: string }> = []
  let histories = 0
  for (const [scope, sessionId] of Array.from(agentTurnSessions.entries())) {
    if (!runtimeCloseMatchesSession(input, scope, sessionId)) continue
    agentTurnSessions.delete(scope)
    if (providerConversationHistories.delete(sessionId)) histories += 1
    closed.push({ agentId: agentTurnSessionScopeAgentId(scope), sessionId, scope })
  }

  if (input.sessionId && providerConversationHistories.delete(input.sessionId)) histories += 1
  const terminatedRuns = terminateOpenClawRunsForSession(input)
  if (closed.length || terminatedRuns.length) {
    pushGatewayLog('lifecycle', `closed ${closed.length} runtime session(s); terminated ${terminatedRuns.length} active call(s)`)
  }
  return {
    closedSessions: closed.length,
    clearedHistories: histories,
    closed,
    terminatedRuns,
  }
}

async function terminateAllOpenClawRunsNow(reason = 'control center shutdown') {
  const runs = Array.from(activeOpenClawRuns.values())
  const results: Array<{ id: string; pid: number | null; agentId?: string; sessionId?: string; ok: boolean; detail: string }> = []
  for (const run of runs) {
    const pid = run.pid || null
    if (!pid) {
      const aborted = abortGatewayChatOpenClawRun(run, reason)
      results.push({
        id: run.id,
        pid,
        agentId: run.agentId,
        sessionId: run.sessionId,
        ok: aborted,
        detail: aborted ? 'gateway chat abort requested' : 'no child process or gateway chat client to terminate',
      })
      continue
    }
    const result = await terminateProcessTree(pid || undefined, reason, true)
    if (activeOpenClawRuns.has(run.id)) {
      finishOpenClawRun(run, 'aborted', { code: 1, failureKind: 'aborted', stderr: reason })
    }
    results.push({ id: run.id, pid, agentId: run.agentId, sessionId: run.sessionId, ok: result.ok, detail: result.detail })
  }
  return results
}

function terminateAllOpenClawRuns(reason = 'control center shutdown') {
  void terminateAllOpenClawRunsNow(reason)
}

function sanitizeOpenClawArgsForDisplay(args: string[]) {
  const redactedValueFlags = new Set([
    '--message',
    '--api-key',
    '--auth-token',
    '--token',
    '--password',
    '--secret',
  ])
  const redactedInlineFlags = [/token=/i, /api[-_]?key=/i, /password=/i, /secret=/i]
  const safe: string[] = []
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index]
    if (redactedValueFlags.has(arg)) {
      safe.push(arg, '[redacted]')
      index += 1
      continue
    }
    safe.push(redactedInlineFlags.some((pattern) => pattern.test(arg)) ? '[redacted]' : arg)
  }
  return safe
}

function openClawRunLabel(args: string[]) {
  return `openclaw ${sanitizeOpenClawArgsForDisplay(args).join(' ')}`.trim()
}

function previewRuntimeOutput(text: string, max = 260) {
  const clean = stripAnsi(text || '').replace(/\s+/g, ' ').trim()
  if (!clean) return ''
  return clean.length > max ? `${clean.slice(0, max - 1).trim()}...` : clean
}

function runtimeFailureSummary(text: string, status?: OpenClawRunStatus) {
  const clean = stripAnsi(text || '').replace(/\s+/g, ' ').trim()
  const cronError = summarizeCronProcessedError(clean)
  if (cronError) return cronError.message
  if (/^incomplete turn detected:\s+runId=/iu.test(clean)) {
    return 'The model turn ended without a final assistant reply.'
  }
  if (/(?:\[clawtalk\]\s+)?CoreBridge:\s+Control Center stream unavailable,\s+falling back to embedded agent:/iu.test(clean)) {
    return 'ClawTalk continued through the embedded agent after the live stream closed.'
  }
  if (/tool policy removed \d+ tool\(s\) via tools\.profile/iu.test(clean)) {
    return 'Runtime tool policy was applied.'
  }
  if (/powershell|\.ps1\b/iu.test(clean) && /\bfailed\b/iu.test(clean)) {
    return 'A PowerShell script exited with an error.'
  }
  if (status === 'aborted' || /\b(?:operation was aborted|openclaw aborted|gateway chat run aborted)\b/iu.test(clean)) {
    return 'The runtime request was cancelled before a final reply arrived.'
  }
  if (status === 'interrupted' || /\b(?:control center restarted|observer interrupted|runtime observer lost)\b/iu.test(clean)) {
    return 'The runtime observer restarted before a final reply arrived.'
  }
  if (status === 'timeout' || /\b(?:timed out|timeout)\b/iu.test(clean)) {
    return 'The runtime request exceeded its timeout before a final reply arrived.'
  }
  return ''
}

function previewUserRuntimeOutput(text: string, status?: OpenClawRunStatus, max = 260) {
  const visible = sanitizeUserVisibleRuntimeText(redactSensitiveText(text || ''))
  return previewRuntimeOutput(visible || runtimeFailureSummary(text, status) || redactSensitiveText(text || ''), max)
}

function beginOpenClawRun(args: string[], cwd: string, timeoutMs: number): OpenClawRunRecord {
  const now = new Date().toISOString()
  const record: OpenClawRunRecord = {
    id: randomUUID(),
    command: openClawRunLabel(args),
    agentId: args[0] === 'agent' ? argValue(args, '--agent') || undefined : undefined,
    sessionId: args[0] === 'agent' ? argValue(args, '--session-id') || undefined : undefined,
    cwd,
    timeoutMs,
    startedAt: now,
    status: 'running',
  }
  activeOpenClawRuns.set(record.id, record)
  persistOpenClawRunLedgerSnapshotSoon(record)
  invalidateRuntimeStatusCache()
  if (record.agentId) {
    pushGatewayLog(
      'lifecycle',
      `OpenClaw runtime started: ${record.agentId}${record.sessionId ? ` session=${record.sessionId.slice(0, 8)}` : ''} timeout=${Math.round(timeoutMs / 1000)}s`,
    )
  }
  return record
}

function beginGatewayChatOpenClawRun(params: {
  runId: string
  agentId: string
  sessionId: string
  sessionKey: string
  cwd: string
  timeoutMs: number
}) {
  const record: OpenClawRunRecord = {
    id: params.runId,
    command: `gateway chat.send --agent ${params.agentId} --session-key ${params.sessionKey}`,
    agentId: params.agentId,
    sessionId: params.sessionId,
    sessionKey: params.sessionKey,
    cwd: params.cwd,
    timeoutMs: params.timeoutMs,
    startedAt: new Date().toISOString(),
    status: 'running',
  }
  activeOpenClawRuns.set(record.id, record)
  persistOpenClawRunLedgerSnapshotSoon(record)
  invalidateRuntimeStatusCache()
  pushGatewayLog(
    'lifecycle',
    `OpenClaw gateway chat started: ${record.agentId} session=${record.sessionId?.slice(0, 8) || 'unknown'} timeout=${Math.round(record.timeoutMs / 1000)}s`,
  )
  return record
}

function updateOpenClawRunPid(record: OpenClawRunRecord, pid?: number) {
  if (!pid) return
  const current = activeOpenClawRuns.get(record.id)
  if (current) {
    current.pid = pid
    persistOpenClawRunLedgerSnapshotSoon(current)
    return
  }
  record.pid = pid
  persistOpenClawRunLedgerSnapshotSoon(record)
}

function finishOpenClawRun(
  record: OpenClawRunRecord,
  status: OpenClawRunStatus,
  output: { stdout?: string; stderr?: string; code?: number; failureKind?: FailureKind } = {},
) {
  const current = activeOpenClawRuns.get(record.id) || record
  const endedAt = new Date().toISOString()
  const startedMs = new Date(current.startedAt).getTime()
  const failureKind = output.failureKind || (status === 'completed' ? undefined : classifyFailureKind(`${output.stderr || ''}\n${output.stdout || ''}`, status) || 'unknown')
  const finished: OpenClawRunRecord = {
    ...current,
    status,
    endedAt,
    elapsedMs: Number.isFinite(startedMs) ? Date.now() - startedMs : undefined,
    ...(typeof output.code === 'number' ? { exitCode: output.code } : {}),
    ...(output.stdout ? { stdoutPreview: previewUserRuntimeOutput(output.stdout, status) } : {}),
    ...(output.stderr ? { stderrPreview: previewUserRuntimeOutput(output.stderr, status) } : {}),
    ...(failureKind ? { failureKind } : {}),
  }
  activeOpenClawRuns.delete(record.id)
  recentOpenClawRuns.unshift(finished)
  invalidateRuntimeStatusCache()
  if (recentOpenClawRuns.length > OPENCLAW_RECENT_RUN_LIMIT) recentOpenClawRuns.length = OPENCLAW_RECENT_RUN_LIMIT
  if (finished.agentId) {
    pushGatewayLog(
      'lifecycle',
      `OpenClaw runtime ${status}: ${finished.agentId}${finished.sessionId ? ` session=${finished.sessionId.slice(0, 8)}` : ''} elapsed=${Math.round((finished.elapsedMs || 0) / 1000)}s${failureKind ? ` failure=${failureKind}` : ''}`,
    )
  }
  persistOpenClawRunLedgerSnapshotSoon(finished)
}

function openClawRunSnapshot(record: OpenClawRunRecord): OpenClawRunRecord {
  if (record.status !== 'running') return { ...record }
  const startedMs = new Date(record.startedAt).getTime()
  return {
    ...record,
    elapsedMs: Number.isFinite(startedMs) ? Date.now() - startedMs : undefined,
  }
}

type AgentSessionStoreEntry = Record<string, unknown>
type AgentSessionStore = Record<string, AgentSessionStoreEntry>
type ModelOverrideCleanupResult = {
  changed: boolean
  cleared: Array<{ sessionKey: string; model: string; reason: string }>
}

function sessionStringField(entry: AgentSessionStoreEntry, key: string) {
  const value = entry[key]
  return typeof value === 'string' ? value.trim() : ''
}

function modelRefKeyFromId(modelId: string) {
  const trimmed = modelId.trim()
  if (!trimmed) return ''
  const { provider, model } = splitModelId(trimmed)
  return provider && model ? `${provider}/${model}`.toLowerCase() : trimmed.toLowerCase()
}

function modelRefKeyFromParts(provider: string, model: string) {
  const modelText = model.trim()
  if (!modelText) return ''
  if (modelText.includes('/')) return modelRefKeyFromId(modelText)
  const providerText = provider.trim()
  return providerText ? `${providerText}/${modelText}`.toLowerCase() : modelText.toLowerCase()
}

function addConfiguredModelKey(keys: Set<string>, modelId?: string) {
  const raw = modelId?.trim()
  if (!raw) return
  const fullKey = modelRefKeyFromId(raw)
  if (fullKey) keys.add(fullKey)
  const { model } = splitModelId(raw)
  if (model) keys.add(model.toLowerCase())
}

function configuredModelKeys(model: { primary?: string; fallbacks?: string[] }) {
  const keys = new Set<string>()
  addConfiguredModelKey(keys, model.primary)
  for (const fallback of model.fallbacks || []) addConfiguredModelKey(keys, fallback)
  return keys
}

function addConfiguredModelProvider(providers: Set<string>, modelId?: string) {
  const raw = modelId?.trim()
  if (!raw) return
  const { provider } = splitModelId(raw)
  if (!provider) return
  providers.add(provider.toLowerCase())
}

function configuredAuthProfilePrefixes(model: { primary?: string; fallbacks?: string[] }) {
  const providers = new Set<string>()
  addConfiguredModelProvider(providers, model.primary)
  for (const fallback of model.fallbacks || []) addConfiguredModelProvider(providers, fallback)

  const prefixes = new Set<string>()
  for (const provider of providers) {
    prefixes.add(`${provider}:`)
    if (provider === 'google') {
      prefixes.add('google:')
      prefixes.add('gemini:')
    }
    if (provider === 'google-vertex') {
      prefixes.add('google-vertex:')
    }
    if (provider === 'openai' || provider === 'openai-codex') {
      prefixes.add('openai:')
      prefixes.add('openai-codex:')
    }
    if (provider === 'codex') {
      prefixes.add('codex:')
      prefixes.add('openai-codex:')
    }
  }
  return prefixes
}

function authProfileMatchesAllowedProvider(authProfileId: string, allowedPrefixes: Set<string>) {
  const normalized = authProfileId.trim().toLowerCase()
  if (!normalized) return true
  if (!allowedPrefixes.size) return true
  for (const prefix of allowedPrefixes) {
    if (normalized.startsWith(prefix)) return true
  }
  return false
}

function agentSessionStorePath(agentId: string) {
  return path.join(OPENCLAW_AGENTS_ROOT, agentId, 'sessions', 'sessions.json')
}

async function resolveAgentConfiguredModelStack(agentId: string) {
  const { config, target } = await getAgentById(agentId)
  if (!target) return null
  const defaults = config.agents?.defaults?.model || {}
  const local = await ensureAgentLocalConfig({
    agentId: target.id,
    entry: target,
    defaultsModel: defaults,
    defaultsSandbox: (config.agents?.defaults as { sandbox?: AgentSandboxConfig } | undefined)?.sandbox,
  })
  return normalizeModelWithFallback(local.model, defaults)
}

function clearDisallowedAutoModelOverrideFromEntry(
  entry: AgentSessionStoreEntry,
  sessionKey: string,
  allowedKeys: Set<string>,
  allowedAuthPrefixes: Set<string>,
): ModelOverrideCleanupResult['cleared'][number] | null {
  const source = sessionStringField(entry, 'modelOverrideSource').toLowerCase()
  const authSource = sessionStringField(entry, 'authProfileOverrideSource').toLowerCase()
  const authProfileOverride = sessionStringField(entry, 'authProfileOverride')
  const overrideKey = modelRefKeyFromParts(
    sessionStringField(entry, 'providerOverride'),
    sessionStringField(entry, 'modelOverride'),
  )
  const activeNoticeKey = modelRefKeyFromId(sessionStringField(entry, 'fallbackNoticeActiveModel'))
  const runtimeKey = modelRefKeyFromParts(
    sessionStringField(entry, 'modelProvider'),
    sessionStringField(entry, 'model'),
  )
  const shouldClearOverride = source === 'auto' && Boolean(overrideKey) && !allowedKeys.has(overrideKey)
  const shouldClearNotice = Boolean(activeNoticeKey) && !allowedKeys.has(activeNoticeKey)
  const shouldClearRuntime = Boolean(runtimeKey) && !allowedKeys.has(runtimeKey)
  const shouldClearAuth =
    Boolean(authProfileOverride) &&
    (authSource === 'auto' || entry.authProfileOverrideCompactionCount !== undefined) &&
    !authProfileMatchesAllowedProvider(authProfileOverride, allowedAuthPrefixes)

  if (!shouldClearOverride && !shouldClearNotice && !shouldClearRuntime && !shouldClearAuth) return null

  const clearedModel = overrideKey || activeNoticeKey || runtimeKey || authProfileOverride || 'unknown'
  if (shouldClearOverride) {
    delete entry.providerOverride
    delete entry.modelOverride
    delete entry.modelOverrideSource
  }
  if (shouldClearOverride || shouldClearAuth) {
    delete entry.authProfileOverride
    delete entry.authProfileOverrideSource
    delete entry.authProfileOverrideCompactionCount
  }
  delete entry.fallbackNoticeSelectedModel
  delete entry.fallbackNoticeActiveModel
  delete entry.fallbackNoticeReason

  if (shouldClearRuntime) {
    delete entry.modelProvider
    delete entry.model
    delete entry.contextTokens
    delete entry.systemPromptReport
  }
  entry.updatedAt = Date.now()

  return {
    sessionKey,
    model: clearedModel,
    reason: shouldClearOverride
      ? 'auto override outside configured model stack'
      : shouldClearNotice
        ? 'stale fallback notice outside configured model stack'
        : shouldClearRuntime
          ? 'runtime model outside configured model stack'
          : 'auto auth profile outside configured provider stack',
  }
}

async function clearDisallowedAutoModelOverridesForAgent(
  agentId: string,
  modelStack?: { primary?: string; fallbacks?: string[] },
): Promise<ModelOverrideCleanupResult> {
  if (!isValidAgentId(agentId) || isRetiredAgentId(agentId)) return { changed: false, cleared: [] }
  const configured = modelStack || await resolveAgentConfiguredModelStack(agentId)
  if (!configured) return { changed: false, cleared: [] }
  const allowedKeys = configuredModelKeys(configured)
  if (!allowedKeys.size) return { changed: false, cleared: [] }
  const allowedAuthPrefixes = configuredAuthProfilePrefixes(configured)

  const storePath = agentSessionStorePath(agentId)
  let store: AgentSessionStore
  try {
    const raw = await fs.readFile(storePath, 'utf-8')
    const parsed = JSON.parse(raw.replace(/^\uFEFF/, '')) as unknown
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return { changed: false, cleared: [] }
    store = parsed as AgentSessionStore
  } catch {
    return { changed: false, cleared: [] }
  }

  const cleared: ModelOverrideCleanupResult['cleared'] = []
  for (const [sessionKey, entry] of Object.entries(store)) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) continue
    const result = clearDisallowedAutoModelOverrideFromEntry(entry, sessionKey, allowedKeys, allowedAuthPrefixes)
    if (result) cleared.push(result)
  }

  if (!cleared.length) return { changed: false, cleared }
  await writeTextFileWithLockRetry(storePath, `${JSON.stringify(store, null, 2)}\n`)
  console.warn(`[model-guard] cleared ${cleared.length} disallowed auto model override(s) for ${agentId}`)
  return { changed: true, cleared }
}

async function clearDisallowedAutoModelOverridesForAgentArgs(args: string[]) {
  if (args[0] !== 'agent') return
  const agentId = argValue(args, '--agent')
  if (!isValidAgentId(agentId)) return
  await clearDisallowedAutoModelOverridesForAgent(agentId)
}

// --- Gateway lifecycle management ---
const GATEWAY_HTTP_PORT = Number(process.env.OPENCLAW_GATEWAY_PORT || 18789)
let gatewayProcess: ReturnType<typeof spawn> | null = null
let gatewayRestartTimer: NodeJS.Timeout | null = null
let gatewayRestartCount = 0
let gatewayEnsureInFlight: Promise<void> | null = null
let gatewayProcessOwnedByControlCenter = false
let lastGatewayPortReleaseAt = 0
let shuttingDown = false
let gatewayAutoRestartPaused = false
let gatewayLastStartedAt: string | null = null
let gatewayLastHealthyAt: string | null = null
let gatewayLastExitAt: string | null = null
let gatewayLastExitCode: number | null = null
let gatewayStartupGraceUntilMs = 0
let gatewayListenerPidCache: { checkedAt: number; pid: number | null } | null = null

type GatewayLogEntry = {
  id: number
  timestamp: string
  stream: 'stdout' | 'stderr' | 'lifecycle' | 'gateway' | 'channel'
  message: string
  level?: string
  source?: string
  channel?: string
  direction?: GatewayChannelDirection
}

type GatewayStartupPhase =
  | 'requested'
  | 'config'
  | 'registry'
  | 'spawned'
  | 'http'
  | 'ready'
  | 'prewarm'
  | 'healthy'
  | 'exit'
  | 'failed'
  | 'warning'

type GatewayStartupStatus = 'started' | 'completed' | 'warning' | 'failed'

type GatewayStartupTimelineEvent = {
  id: number
  timestamp: string
  phase: GatewayStartupPhase
  status: GatewayStartupStatus
  message: string
  elapsedMs: number
  durationMs?: number
  pid?: number | null
}

type GatewayChannelDirection = 'inbound' | 'outbound' | 'system'

type GatewayChannelActivity = {
  id: number
  timestamp: string
  channel: string
  direction: GatewayChannelDirection
  message: string
  level?: string
  source?: string
  agentId?: string
}

type GatewayActivitySummary = {
  active: boolean
  lastEventAt: string | null
  sourcePath: string | null
  inboundCount: number
  outboundCount: number
  systemCount: number
  events: GatewayChannelActivity[]
}

const GATEWAY_LOG_LIMIT = 180
const EXTERNAL_GATEWAY_LOG_CACHE_MS = Math.max(
  500,
  Math.min(10_000, Number(process.env.CONTROL_CENTER_GATEWAY_LOG_CACHE_MS || 2_000)),
)
const RUNTIME_STATUS_CACHE_MS = Math.max(
  500,
  Math.min(10_000, Number(process.env.CONTROL_CENTER_RUNTIME_STATUS_CACHE_MS || 1_500)),
)
const RUNTIME_SUMMARY_CACHE_MS = Math.max(
  500,
  Math.min(10_000, Number(process.env.CONTROL_CENTER_RUNTIME_SUMMARY_CACHE_MS || 2_000)),
)
const RUNTIME_STATUS_RESPONSE_TIMEOUT_MS = Math.max(
  1_500,
  Math.min(15_000, Number(process.env.CONTROL_CENTER_RUNTIME_STATUS_RESPONSE_TIMEOUT_MS || 6_000)),
)
const RUNTIME_SUMMARY_RESPONSE_TIMEOUT_MS = Math.max(
  750,
  Math.min(10_000, Number(process.env.CONTROL_CENTER_RUNTIME_SUMMARY_RESPONSE_TIMEOUT_MS || 2_500)),
)
const GATEWAY_STARTUP_HEALTH_GRACE_MS = (() => {
  const configured = Number(process.env.CONTROL_CENTER_GATEWAY_STARTUP_HEALTH_GRACE_MS || 75_000)
  return Number.isFinite(configured) ? Math.max(15_000, Math.min(180_000, configured)) : 75_000
})()
const GATEWAY_STARTUP_HEALTH_CONFIRM_TIMEOUT_MS = (() => {
  const configured = Number(process.env.CONTROL_CENTER_GATEWAY_STARTUP_HEALTH_CONFIRM_TIMEOUT_MS || 45_000)
  return Number.isFinite(configured) ? Math.max(10_000, Math.min(180_000, configured)) : 45_000
})()
const GATEWAY_STARTUP_HEALTH_POLL_MS = (() => {
  const configured = Number(process.env.CONTROL_CENTER_GATEWAY_STARTUP_HEALTH_POLL_MS || 1_500)
  return Number.isFinite(configured) ? Math.max(500, Math.min(10_000, configured)) : 1_500
})()
const GATEWAY_CONFIG_VALIDATE_TIMEOUT_MS = 60_000
const GATEWAY_CONFIG_DOCTOR_TIMEOUT_MS = 120_000
const GATEWAY_STARTUP_TIMELINE_LIMIT = 18
let gatewayLogSeq = 0
let gatewayStartupTimelineSeq = 0
let gatewayStartupTimelineStartedAtMs = 0
const gatewayLogs: GatewayLogEntry[] = []
const gatewayStartupTimeline: GatewayStartupTimelineEvent[] = []
const gatewayStartupPhaseStartedAtMs = new Map<GatewayStartupPhase, number>()
let runtimeMonitorClearedAtMs = 0
let gatewayConfigPreflightInFlight: Promise<boolean> | null = null
let externalGatewayLogCache: { expiresAt: number; entries: GatewayLogEntry[] } | null = null
let externalChannelActivityCache: { expiresAt: number; entries: GatewayLogEntry[] } | null = null
let gatewayLogPathDiscoveryCache: { expiresAt: number; paths: string[] } | null = null
let runtimeStatusPayloadCache: { builtAt: number; payload: Record<string, unknown> } | null = null
let runtimeStatusPayloadInFlight: Promise<Record<string, unknown>> | null = null
let runtimeSummaryPayloadCache: { builtAt: number; payload: Record<string, unknown> } | null = null
let runtimeSummaryPayloadInFlight: Promise<Record<string, unknown>> | null = null

function invalidateRuntimeStatusCache() {
  runtimeStatusPayloadCache = null
  runtimeSummaryPayloadCache = null
}

function sanitizeGatewayStartupMessage(message: string, max = 220) {
  return compactGatewayLogMessage(redactSensitiveText(stripAnsi(message || '')), max)
}

function resetGatewayStartupTimeline(message: string): void {
  gatewayStartupTimeline.length = 0
  gatewayStartupPhaseStartedAtMs.clear()
  gatewayStartupTimelineStartedAtMs = Date.now()
  recordGatewayStartupEvent('requested', 'started', message)
}

function recordGatewayStartupEvent(
  phase: GatewayStartupPhase,
  status: GatewayStartupStatus,
  message: string,
  options: { pid?: number | null; durationMs?: number } = {},
): void {
  const now = Date.now()
  if (!gatewayStartupTimelineStartedAtMs) gatewayStartupTimelineStartedAtMs = now

  let durationMs = options.durationMs
  if (status === 'started') {
    gatewayStartupPhaseStartedAtMs.set(phase, now)
  } else {
    const startedAt = gatewayStartupPhaseStartedAtMs.get(phase)
    if (durationMs === undefined && startedAt) durationMs = Math.max(0, now - startedAt)
    gatewayStartupPhaseStartedAtMs.delete(phase)
  }

  gatewayStartupTimeline.push({
    id: ++gatewayStartupTimelineSeq,
    timestamp: new Date(now).toISOString(),
    phase,
    status,
    message: sanitizeGatewayStartupMessage(message),
    elapsedMs: Math.max(0, now - gatewayStartupTimelineStartedAtMs),
    ...(durationMs !== undefined ? { durationMs } : {}),
    ...(options.pid !== undefined ? { pid: options.pid } : {}),
  })

  if (gatewayStartupTimeline.length > GATEWAY_STARTUP_TIMELINE_LIMIT) {
    gatewayStartupTimeline.splice(0, gatewayStartupTimeline.length - GATEWAY_STARTUP_TIMELINE_LIMIT)
  }
  invalidateRuntimeStatusCache()
}

function isRuntimeMonitorEntryVisible(timestamp: string | null | undefined) {
  if (!runtimeMonitorClearedAtMs) return true
  const entryMs = timestamp ? Date.parse(timestamp) : NaN
  return Number.isFinite(entryMs) && entryMs >= runtimeMonitorClearedAtMs
}

function gatewayProviderLabel(value: string) {
  const match = value.match(/\b(openai|google|anthropic|deepseek|gemini|vertex)\s+embeddings\s+failed\b/i)
  if (!match) return 'Provider'
  const raw = match[1].toLowerCase()
  if (raw === 'openai') return 'OpenAI'
  if (raw === 'gemini') return 'Gemini'
  if (raw === 'vertex') return 'Vertex'
  return raw.charAt(0).toUpperCase() + raw.slice(1)
}

function summarizeEmbeddingProviderFailure(value: string) {
  const code = value.match(/\bembeddings\s+failed:\s*(\d{3})\b/i)?.[1] || 'error'
  const errorCode = value.match(/"code"\s*:\s*"([^"]+)"/i)?.[1]
  const errorType = value.match(/"type"\s*:\s*"([^"]+)"/i)?.[1]
  const suffix = errorCode && errorCode !== 'null'
    ? errorCode
    : errorType && errorType !== 'null'
      ? errorType
      : ''
  return `${gatewayProviderLabel(value)} embeddings returned ${code}${suffix ? ` ${suffix}` : ''}`
}

function isGatewaySessionLivenessDiagnostic(value: string) {
  const text = value.replace(/\s+/g, ' ').trim()
  return /^(?:long-running|stalled|stuck) session:\s+sessionId=/iu.test(text)
    || (/\bsession\.(?:long_running|stalled|stuck)\b/iu.test(text) && /\bqueueDepth=\d+\b/iu.test(text))
    || (/\bclassification=(?:long_running|stalled_agent_run|blocked_tool_call|stale_session_state)\b/iu.test(text) && /\bsession(?:Id|Key)=/u.test(text))
}

function isGatewayInternalDiagnosticMessage(value: string) {
  const text = stripAnsi(value || '').replace(/\s+/g, ' ').trim()
  return isGatewaySessionLivenessDiagnostic(text)
    || /^tool policy removed \d+ tool\(s\) via tools\.profile\b/iu.test(text)
    || /^incomplete turn detected:\s+runId=/iu.test(text)
    || /^\[clawtalk\]\s+CoreBridge:\s+Control Center stream unavailable,\s+falling back to embedded agent:/iu.test(text)
    || /^CoreBridge:\s+Control Center stream unavailable,\s+falling back to embedded agent:/iu.test(text)
    || /^(?:⇄|â‡„)?\s*res\s*(?:✓|âœ“)?\s*chat\.(?:history|message\.get)\b/iu.test(text)
}

function displayDurationMs(ms: number) {
  if (!Number.isFinite(ms) || ms < 0) return ''
  const seconds = Math.round(ms / 1000)
  if (seconds < 90) return `${seconds}s`
  const minutes = Math.floor(seconds / 60)
  const remainder = seconds % 60
  return remainder ? `${minutes}m ${remainder}s` : `${minutes}m`
}

function gatewayLogTokenValue(text: string, key: string) {
  const match = text.match(new RegExp(`\\b${key}=("[^"]*"|\\S+)`, 'iu'))
  if (!match) return ''
  return match[1].replace(/^"|"$/g, '').trim()
}

function summarizeCronProcessedError(value: string): { message: string; level: 'error' } | null {
  const text = stripAnsi(value || '').replace(/\s+/g, ' ').trim()
  if (!/^message processed:\s+channel=cron\b/iu.test(text) || !/\boutcome=error\b/iu.test(text)) return null
  const sessionKey = gatewayLogTokenValue(text, 'sessionKey')
  const agent = sessionKey.match(/^agent:([^:\s]+):cron:/iu)?.[1] || gatewayLogTokenValue(text, 'agent') || 'scheduled agent'
  const durationToken = gatewayLogTokenValue(text, 'duration')
  const duration = Number(durationToken.match(/\d+(?:\.\d+)?/u)?.[0] || NaN)
  const durationText = displayDurationMs(duration)
  const errorText = gatewayLogTokenValue(text, 'error')
  const commandType = /powershell|\.ps1\b/iu.test(errorText)
    ? 'PowerShell script'
    : /python\b|python\s+-/iu.test(errorText)
      ? 'Python helper'
      : 'scheduled command'
  return {
    message: `Cron run failed for ${agent}${durationText ? ` after ${durationText}` : ''}: ${commandType} exited with an error.`,
    level: 'error',
  }
}

function normalizeGatewayLogDisplayMessage(value: string): { message: string; level?: string } {
  const compact = compactGatewayLogMessage(value)
  const withoutTimestamp = compact
    .replace(/^\[[^\]]+\]\s+\[(?:stdout|stderr|lifecycle|gateway|channel)\]\s+/iu, '')
    .replace(/^\d{4}-\d{2}-\d{2}T\S+\s+\[memory\]\s+/iu, 'memory ')
    .replace(/^\d{4}-\d{2}-\d{2}T\S+\s+\[[^\]]+\]\s+/iu, '')
    .replace(/^\[memory\]\s+/iu, 'memory ')
    .trim()

  const fragmentSummary = summarizeGatewayLogFragment(withoutTimestamp)
  if (fragmentSummary) return fragmentSummary

  const validationHeader = withoutTimestamp.match(/^(OpenClaw config validation failed(?:[^:]*)):\s*\{?$/iu)
  if (validationHeader) {
    return { message: `${validationHeader[1]}.`, level: 'warning' }
  }

  const cronError = summarizeCronProcessedError(withoutTimestamp)
  if (cronError) return cronError

  if (isGatewaySessionLivenessDiagnostic(withoutTimestamp)) {
    return { message: withoutTimestamp || compact, level: 'warning' }
  }

  if (/\bmemory\s+embeddings retryable error;\s*retrying in \d+ms\b/i.test(withoutTimestamp)
    || /\bembeddings retryable error;\s*retrying in \d+ms\b/i.test(withoutTimestamp)) {
    return { message: 'OpenClaw memory embeddings retrying after provider error.', level: 'warning' }
  }

  const indexFailure = withoutTimestamp.match(/\bMemory index failed \(([^)]+)\):\s*(?:Error:\s*)?(.+)$/i)
  if (indexFailure && /\bembeddings\s+failed:\s*\d{3}\b/i.test(indexFailure[2])) {
    return {
      message: `OpenClaw memory index failed (${indexFailure[1]}): ${summarizeEmbeddingProviderFailure(indexFailure[2])}.`,
      level: 'warning',
    }
  }

  const syncFailure = withoutTimestamp.match(/\bmemory sync failed \(watch\):\s*(?:Error:\s*)?(.+)$/i)
  if (syncFailure && /\bembeddings\s+failed:\s*\d{3}\b/i.test(syncFailure[1])) {
    return {
      message: `OpenClaw memory sync watch failed: ${summarizeEmbeddingProviderFailure(syncFailure[1])}.`,
      level: 'warning',
    }
  }

  if (/\bembeddings\s+failed:\s*\d{3}\b/i.test(withoutTimestamp)) {
    return { message: `OpenClaw memory embedding provider issue: ${summarizeEmbeddingProviderFailure(withoutTimestamp)}.`, level: 'warning' }
  }

  return { message: withoutTimestamp || compact }
}

function visibleGatewayLogSegments(message: string) {
  const lines = stripAnsi(message)
    .replace(/\r/g, '')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
  const visibleLines = lines.length ? lines : [message.trim()].filter(Boolean)
  const segments: Array<{ line: string; display: { message: string; level?: string } }> = []
  let suppressToolFailureContinuation = false
  for (const line of visibleLines) {
    if (suppressToolFailureContinuation) {
      if (!isGatewayLogRecordStart(line)) continue
      suppressToolFailureContinuation = false
    }
    if (isGatewayMonitorNoise(line)) {
      if (isGatewayToolFailureLine(line)) suppressToolFailureContinuation = true
      continue
    }
    const display = normalizeGatewayLogDisplayMessage(line)
    segments.push({ line, display })
  }
  return segments
}

function formatGatewayProcessOutput(prefix: string, message: string) {
  const segments = visibleGatewayLogSegments(message)
  if (!segments.length) return ''
  return `${segments.map((segment) => `${prefix} ${segment.line}`).join('\n')}\n`
}

function pushGatewayLog(stream: GatewayLogEntry['stream'], message: string, level?: string) {
  for (const { display } of visibleGatewayLogSegments(message)) {
    const channel = gatewayChannelFromMessage(display.message)
    const direction = channel ? gatewayActivityDirection(display.message) : undefined
    const entry = {
      id: ++gatewayLogSeq,
      timestamp: new Date().toISOString(),
      stream: channel ? 'channel' as const : stream,
      message: display.message.length > 600 ? `${display.message.slice(0, 599).trim()}...` : display.message,
      ...(level || display.level ? { level: level || display.level } : {}),
      ...(channel ? { channel, direction } : {}),
    } satisfies GatewayLogEntry
    gatewayLogs.unshift(entry)
    void appendGatewayEventLedger({
      ...entry,
      message: redactSensitiveText(entry.message),
    }, { sqlite: false }).catch(() => undefined)
  }
  if (gatewayLogs.length > GATEWAY_LOG_LIMIT) gatewayLogs.length = GATEWAY_LOG_LIMIT
}

function localDateKey(date = new Date()) {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

function gatewayLogEntryId(source: string, line: string) {
  const digest = createHash('sha1').update(`${source}\n${line}`).digest('hex').slice(0, 7)
  return -Number.parseInt(digest, 16)
}

function normalizedGatewayLogMessageForDedupe(message: string) {
  return stripAnsi(message || '')
    .trim()
    .replace(/^\[[^\]]+\]\s+\[(?:stdout|stderr|lifecycle|gateway|channel)\]\s+/iu, '')
    .replace(/^\d{4}-\d{2}-\d{2}T\S+\s+\[memory\]\s+/iu, 'memory ')
    .replace(/^\d{4}-\d{2}-\d{2}T\S+\s+\[[^\]]+\]\s+/iu, '')
    .replace(/\bretrying in \d+ms\b/giu, 'retrying')
    .replace(/\bOpenClaw memory index failed \([^)]+\):/iu, 'OpenClaw memory index failed:')
    .replace(/\s+/g, ' ')
    .toLowerCase()
}

function dedupeGatewayLogEntries(entries: GatewayLogEntry[], limit = 80) {
  const deduped = new Map<string, GatewayLogEntry>()
  for (const entry of [...entries].sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp))) {
    const timestampMs = Date.parse(entry.timestamp)
    const normalized = normalizedGatewayLogMessageForDedupe(entry.message)
    const noisyMemoryBucketMs = gatewayMemoryLogBucketMs(normalized)
    const bucketMs = noisyMemoryBucketMs || 5000
    const bucket = Number.isFinite(timestampMs) ? Math.floor(timestampMs / bucketMs) : 0
    const key = `${bucketMs}:${bucket}|${normalized}`
    if (!deduped.has(key)) deduped.set(key, entry)
  }
  return Array.from(deduped.values()).slice(0, limit)
}

function gatewayMemoryLogBucketMs(normalizedMessage: string) {
  if (/openclaw memory embeddings retrying after provider error/u.test(normalizedMessage)) return 60_000
  if (/openclaw memory index failed: .*embeddings returned 500/u.test(normalizedMessage)) return 60_000
  if (/openclaw memory sync watch failed: .*embeddings returned 500/u.test(normalizedMessage)) return 60_000
  return 0
}

function configuredGatewayLogCandidatesFromConfig(config: OpenClawConfigFile): string[] {
  const logging = (config as { logging?: { file?: unknown } }).logging
  return typeof logging?.file === 'string' && logging.file.trim() ? [path.resolve(logging.file.trim())] : []
}

async function discoverGatewayFileLogPaths(limit = 5) {
  const now = Date.now()
  if (gatewayLogPathDiscoveryCache && gatewayLogPathDiscoveryCache.expiresAt > now) {
    return gatewayLogPathDiscoveryCache.paths.slice()
  }

  const candidates = new Set<string>([OPENCLAW_GATEWAY_LOG_PATH])
  const config = await readOpenclawConfig().catch(() => null)
  if (config) {
    for (const candidate of configuredGatewayLogCandidatesFromConfig(config)) candidates.add(candidate)
  }

  if (INCLUDE_SHARED_OPENCLAW_TEMP_LOGS) {
    const tempDirs = new Set<string>([path.join(tmpdir(), 'openclaw')])
    if (process.env.TEMP) tempDirs.add(path.join(process.env.TEMP, 'openclaw'))
    if (process.env.TMP) tempDirs.add(path.join(process.env.TMP, 'openclaw'))
    if (process.env.LOCALAPPDATA) tempDirs.add(path.join(process.env.LOCALAPPDATA, 'Temp', 'openclaw'))

    const todayFileName = `openclaw-${localDateKey()}.log`
    for (const dir of tempDirs) {
      candidates.add(path.join(dir, todayFileName))
      const files = await fs.readdir(dir, { withFileTypes: true }).catch(() => [])
      const logFiles = await Promise.all(files
        .filter((entry) => entry.isFile() && /^openclaw-\d{4}-\d{2}-\d{2}\.log$/i.test(entry.name))
        .map(async (entry) => {
          const filePath = path.join(dir, entry.name)
          const stat = await fs.stat(filePath).catch(() => null)
          return stat ? { filePath, mtimeMs: stat.mtimeMs } : null
        }))
      for (const file of logFiles
        .filter((entry): entry is { filePath: string; mtimeMs: number } => Boolean(entry))
        .sort((a, b) => b.mtimeMs - a.mtimeMs)
        .slice(0, limit)) {
        candidates.add(file.filePath)
      }
    }
  }

  const output: string[] = []
  const seen = new Set<string>()
  for (const candidate of candidates) {
    const normalized = process.platform === 'win32' ? candidate.toLowerCase() : candidate
    if (seen.has(normalized)) continue
    seen.add(normalized)
    const stat = await fs.stat(candidate).catch(() => null)
    if (stat?.isFile()) output.push(candidate)
  }
  gatewayLogPathDiscoveryCache = {
    expiresAt: now + GATEWAY_LOG_PATH_DISCOVERY_CACHE_MS,
    paths: output,
  }
  return output
}

type GatewayLogTailSnapshot = {
  statKey: string
  signature: string
  entries: GatewayLogEntry[]
}

const gatewayLogTailSnapshots = new Map<string, GatewayLogTailSnapshot>()

function gatewayLogFileStatKey(stat: { size: number; mtimeMs: number; birthtimeMs: number }) {
  return `${stat.size}:${Math.round(stat.mtimeMs)}:${Math.round(stat.birthtimeMs)}`
}

async function gatewayLogFileSignature(filePath: string, stat: { size: number; mtimeMs: number; birthtimeMs: number }) {
  const length = Math.min(GATEWAY_LOG_FINGERPRINT_BYTES, stat.size)
  const statKey = gatewayLogFileStatKey(stat)
  if (length <= 0) return `${statKey}:empty`
  const handle = await fs.open(filePath, 'r')
  try {
    const buffer = Buffer.alloc(length)
    await handle.read(buffer, 0, length, 0)
    const digest = createHash('sha1').update(buffer).digest('hex').slice(0, 14)
    return `${statKey}:${digest}`
  } finally {
    await handle.close().catch(() => undefined)
  }
}

async function readTailText(filePath: string, maxBytes = GATEWAY_LOG_TAIL_MAX_BYTES) {
  const stat = await fs.stat(filePath).catch(() => null)
  if (!stat?.isFile() || stat.size <= 0) return ''
  const length = Math.min(maxBytes, stat.size)
  const start = Math.max(0, stat.size - length)
  const handle = await fs.open(filePath, 'r')
  try {
    const buffer = Buffer.alloc(length)
    await handle.read(buffer, 0, length, start)
    return buffer.toString('utf-8')
  } finally {
    await handle.close().catch(() => undefined)
  }
}

async function readTailTextWithSignature(filePath: string, maxBytes = GATEWAY_LOG_TAIL_MAX_BYTES) {
  const stat = await fs.stat(filePath).catch(() => null)
  if (!stat?.isFile() || stat.size <= 0) return null
  const statKey = gatewayLogFileStatKey(stat)
  const cached = gatewayLogTailSnapshots.get(filePath)
  if (cached?.statKey === statKey) {
    return { raw: '', statKey, signature: cached.signature, cacheHit: true }
  }
  const signature = await gatewayLogFileSignature(filePath, stat)
  if (cached?.signature === signature) {
    if (cached.statKey !== statKey) {
      gatewayLogTailSnapshots.set(filePath, { ...cached, statKey, signature })
    }
    return { raw: '', statKey, signature, cacheHit: true }
  }
  const raw = await readTailText(filePath, maxBytes)
  return { raw, statKey, signature, cacheHit: false }
}

function compactGatewayLogMessage(value: string, max = 640) {
  const warningSign = String.fromCodePoint(0x26a0)
  const variationSelector = String.fromCodePoint(0xfe0f)
  const hammerAndWrench = String.fromCodePoint(0x1f6e0)
  const emDash = String.fromCodePoint(0x2014)
  const ellipsis = String.fromCodePoint(0x2026)
  const normalized = stripAnsi(value || '')
    .replace(/\r/g, '')
    .replaceAll(`${warningSign}${variationSelector}`, '')
    .replaceAll(warningSign, '')
    .replaceAll(`${hammerAndWrench}${variationSelector}`, '')
    .replaceAll(hammerAndWrench, '')
    .replaceAll(emDash, '-')
    .replaceAll(ellipsis, '...')
  const masked = applyDiagnosticRedactions(normalized)
    .replace(/\n{3,}/g, '\n\n')
    .trim()
  return masked.length > max ? `${masked.slice(0, max - 1).trim()}...` : masked
}

function cleanGatewayLogFragmentValue(value: string) {
  const trimmed = stripAnsi(value || '').trim().replace(/,$/u, '').trim()
  if (!trimmed) return ''
  try {
    const parsed = JSON.parse(trimmed) as unknown
    if (typeof parsed === 'string') return compactGatewayLogMessage(parsed)
    if (typeof parsed === 'number' || typeof parsed === 'boolean') return String(parsed)
  } catch {
    // Log fragments are often JSON fields without their surrounding object.
  }
  return compactGatewayLogMessage(trimmed.replace(/^"|"$/gu, '').replace(/\\"/g, '"'))
}

function summarizeGatewayLogFragment(value: string): { message: string; level?: string } | null {
  const text = stripAnsi(value || '').trim()
  if (!text) return { message: '' }
  if (/^[{}[\],]+$/u.test(text)) return { message: '' }
  if (/^"?(?:issues|details|errors)"?\s*:\s*[[{]?\s*,?$/iu.test(text)) return { message: '' }
  if (/^"?(?:valid|ok)"?\s*:\s*(?:true|false|null)\s*,?$/iu.test(text)) return { message: '' }

  const field = text.match(/^"?(message|path|error|detail|reason)"?\s*:\s*(.+?)\s*,?$/iu)
  if (!field) return null

  const key = field[1].toLowerCase()
  const cleaned = cleanGatewayLogFragmentValue(field[2])
  if (!cleaned) return { message: '' }

  if (key === 'message') {
    const unsupportedKeys = Array.from(cleaned.matchAll(/"([^"]+)"/gu))
      .map((match) => match[1])
      .filter(Boolean)
    if (/invalid config\b/iu.test(cleaned) && unsupportedKeys.length) {
      return {
        message: `Invalid config: remove unsupported keys ${unsupportedKeys.join(', ')}.`,
        level: 'warning',
      }
    }
    return {
      message: cleaned.replace(/^invalid config:\s*/iu, 'Invalid config: '),
      level: /\b(?:invalid|failed|error|rejected)\b/iu.test(cleaned) ? 'warning' : undefined,
    }
  }

  if (key === 'path') {
    const label = /\.json\b/iu.test(cleaned)
      ? 'Config file'
      : /plugins\.entries\./iu.test(cleaned)
        ? 'Config path'
        : 'Path'
    return { message: `${label}: ${cleaned}` }
  }

  return {
    message: `${key[0].toUpperCase()}${key.slice(1)}: ${cleaned}`,
    level: key === 'error' ? 'error' : /\b(?:invalid|failed|error|rejected)\b/iu.test(cleaned) ? 'warning' : undefined,
  }
}

function objectStringField(value: Record<string, unknown>, key: string) {
  const raw = value[key]
  return typeof raw === 'string' ? raw : ''
}

function nestedMetaStringField(value: Record<string, unknown>, key: string) {
  const meta = value._meta
  if (!meta || typeof meta !== 'object' || Array.isArray(meta)) return ''
  const raw = (meta as Record<string, unknown>)[key]
  return typeof raw === 'string' ? raw : ''
}

function normalizeGatewayChannelName(value: string) {
  const cleaned = value.trim().toLowerCase().replace(/^channels?\//u, '')
  if (!/^[a-z0-9][a-z0-9_-]{1,80}$/u.test(cleaned)) return ''
  return cleaned
}

function gatewayChannelFromSubsystem(value: string) {
  const cleaned = value.trim().toLowerCase()
  if (!cleaned) return ''
  const channelSubsystem = cleaned.match(/^channels?\/([a-z0-9_-]+)/u)
  if (channelSubsystem) return normalizeGatewayChannelName(channelSubsystem[1])
  const directSubsystem = cleaned.match(/^(telegram|clawtalk|sms|imessage|whatsapp|signal|discord|slack|matrix|mattermost|msteams|googlechat|feishu|line|irc|twitch|wechat|zalo|zalouser|qqbot|nextcloud-talk|synology-chat|nostr|tlon|yuanbao)(?:\/|$)/u)
  return directSubsystem ? normalizeGatewayChannelName(directSubsystem[1]) : ''
}

function gatewayChannelFromMessage(message: string) {
  const text = stripAnsi(message || '').replace(/\s+/g, ' ').trim()
  const bracket = text.match(/\[(clawtalk|telegram|sms|imessage|whatsapp|signal|discord|slack|matrix|mattermost|msteams|googlechat|feishu|line|irc|twitch|wechat|zalo|zalouser|qqbot|nextcloud-talk|synology-chat|nostr|tlon|yuanbao)\]/iu)
  if (bracket) return normalizeGatewayChannelName(bracket[1])
  const processed = text.match(/^message processed:\s+channel=([a-z0-9_-]+)/iu)
  if (processed) return normalizeGatewayChannelName(processed[1])
  const spoken = text.match(/\b(telegram|clawtalk|sms|imessage|whatsapp|signal|discord|slack|matrix|mattermost|teams|google chat|feishu|line|irc|twitch|wechat|zalo|qqbot|nextcloud talk|synology chat|nostr|tlon|yuanbao)\b/iu)
  if (!spoken) return ''
  const normalized = spoken[1].toLowerCase().replace(/\s+/gu, '-')
  return normalized === 'teams' ? 'msteams' : normalizeGatewayChannelName(normalized)
}

function gatewayChannelFromLogObject(value: Record<string, unknown>, message: string, subsystem: string) {
  for (const key of ['channel', 'channelId', 'provider', 'platform', 'surface', 'pluginId']) {
    const field = objectStringField(value, key)
    const normalized = field ? normalizeGatewayChannelName(field) : ''
    if (normalized) return normalized
  }
  const metaChannel = nestedMetaStringField(value, 'channel') || nestedMetaStringField(value, 'subsystem')
  return gatewayChannelFromSubsystem(subsystem) || gatewayChannelFromSubsystem(metaChannel) || gatewayChannelFromMessage(message)
}

function subsystemFromLogObject(value: Record<string, unknown>) {
  const direct = objectStringField(value, 'subsystem')
  if (direct) return direct
  const prefixed = objectStringField(value, '0')
  if (!prefixed) return ''
  try {
    const parsed = JSON.parse(prefixed) as { subsystem?: unknown }
    return typeof parsed?.subsystem === 'string' ? parsed.subsystem : ''
  } catch {
    return ''
  }
}

function gatewayLogPayloadMessage(value: string) {
  const trimmed = stripAnsi(value || '').trim()
  if (!trimmed) return ''
  try {
    const parsed = JSON.parse(trimmed) as unknown
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return trimmed
    const record = parsed as Record<string, unknown>
    return (
      objectStringField(record, 'message')
      || objectStringField(record, '1')
      || objectStringField(record, 'msg')
      || objectStringField(record, '0')
      || trimmed
    ).replace(/^\{"subsystem":"[^"]+"\}\s*/u, '')
  } catch {
    return trimmed
  }
}

function isGatewayToolFailureLine(value: string) {
  return /^\[tools\]\s+[\w/-]+\s+failed:/iu.test(gatewayLogPayloadMessage(value).replace(/\s+/g, ' ').trim())
}

function isGatewayLogRecordStart(value: string) {
  const text = stripAnsi(value || '').trim()
  return /^\{/u.test(text)
    || /^\[[^\]]+\]\s+\[(?:stdout|stderr|lifecycle|gateway|channel)\]\s+/iu.test(text)
    || /^\d{4}-\d{2}-\d{2}T\S+\s+\[[^\]]+\]\s+/iu.test(text)
    || /^\[(?:plugins?|clawtalk|gateway(?:-err)?|agent\/embedded|agents\/[^\]]+|openclaw(?:\/[^\]]+)?|runtime(?:\/[^\]]+)?|tools)\]\s+/iu.test(text)
}

function isGatewayMonitorNoise(value: string) {
  const message = normalizeGatewayLogDisplayMessage(gatewayLogPayloadMessage(value)).message.replace(/\s+/g, ' ').trim()
  if (!message) return true
  if (isGatewayInternalDiagnosticMessage(message)) return true
  if (/^\[clawtalk\]\s+\[MissionObserver\]\s+(?:No running missions found\.?|Started\b.*|Stopped\.?)$/iu.test(message)) return true
  if (isGatewayToolFailureLine(message)) return true
  if (/^\[tools\]\b/iu.test(message) && /\braw_params=|\bCurrent file contents:/iu.test(message)) return true
  return false
}

function parseGatewayFileLogLine(line: string, source: string, index: number): GatewayLogEntry | null {
  const trimmed = line.trim()
  if (!trimmed) return null
  if (isGatewayMonitorNoise(trimmed)) return null

  const bracket = trimmed.match(/^\[([^\]]+)]\s+\[(stdout|stderr|lifecycle)]\s+(.*)$/i)
  if (bracket) {
    if (isGatewayMonitorNoise(bracket[3])) return null
    const timestamp = !Number.isNaN(new Date(bracket[1]).getTime()) ? new Date(bracket[1]).toISOString() : new Date().toISOString()
    const display = normalizeGatewayLogDisplayMessage(bracket[3])
    const channel = gatewayChannelFromMessage(display.message)
    return {
      id: gatewayLogEntryId(source, `${index}:${trimmed}`),
      timestamp,
      stream: channel ? 'channel' : bracket[2].toLowerCase() as GatewayLogEntry['stream'],
      message: display.message,
      ...(display.level ? { level: display.level } : {}),
      ...(channel ? { channel, direction: gatewayActivityDirection(display.message) } : {}),
      source,
    }
  }

  try {
    const parsed = JSON.parse(trimmed) as unknown
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null
    const record = parsed as Record<string, unknown>
    const rawMessage = (
      objectStringField(record, 'message')
      || objectStringField(record, '1')
      || objectStringField(record, 'msg')
      || trimmed
    ).replace(/^\{"subsystem":"[^"]+"\}\s*/u, '')
    if (isGatewayMonitorNoise(rawMessage)) return null
    const display = normalizeGatewayLogDisplayMessage(rawMessage)
    const message = display.message
    const time = objectStringField(record, 'time') || nestedMetaStringField(record, 'date')
    const timestamp = time && !Number.isNaN(new Date(time).getTime()) ? new Date(time).toISOString() : new Date().toISOString()
    const level = display.level || (objectStringField(record, 'level') || nestedMetaStringField(record, 'logLevelName')).toLowerCase() || undefined
    const subsystem = subsystemFromLogObject(record)
    const channel = gatewayChannelFromLogObject(record, message, subsystem)
    const direction = gatewayActivityDirectionFromRecord(record, message)
    return {
      id: gatewayLogEntryId(source, `${index}:${trimmed}`),
      timestamp,
      stream: channel || /channel/i.test(subsystem) ? 'channel' : 'gateway',
      level,
      channel,
      direction,
      source,
      message,
    }
  } catch {
    if (isGatewayMonitorNoise(trimmed)) return null
    const display = normalizeGatewayLogDisplayMessage(trimmed)
    const channel = gatewayChannelFromMessage(display.message)
    return {
      id: gatewayLogEntryId(source, `${index}:${trimmed}`),
      timestamp: new Date().toISOString(),
      stream: channel ? 'channel' : 'gateway',
      source,
      message: display.message,
      ...(channel ? { channel, direction: gatewayActivityDirection(display.message) } : {}),
      ...(display.level ? { level: display.level } : {}),
    }
  }
}

async function readGatewayFileLogEntries(limit = 120): Promise<GatewayLogEntry[]> {
  const paths = await discoverGatewayFileLogPaths()
  const activePaths = new Set(paths)
  const entries: GatewayLogEntry[] = []
  for (const filePath of paths) {
    const snapshot = await readTailTextWithSignature(filePath).catch(() => null)
    const cached = gatewayLogTailSnapshots.get(filePath)
    if (cached && snapshot?.cacheHit && cached.signature === snapshot.signature) {
      entries.push(...cached.entries)
      continue
    }
    if (!snapshot?.raw.trim()) {
      gatewayLogTailSnapshots.delete(filePath)
      continue
    }

    const parsedEntries: GatewayLogEntry[] = []
    const lines = snapshot.raw.replace(/\r/g, '').split('\n').filter((line) => line.trim())
    lines.slice(-Math.max(limit * 4, limit)).forEach((line, index) => {
      const entry = parseGatewayFileLogLine(line, filePath, index)
      if (entry) parsedEntries.push(entry)
    })
    gatewayLogTailSnapshots.set(filePath, {
      statKey: snapshot.statKey,
      signature: snapshot.signature,
      entries: parsedEntries,
    })
    entries.push(...parsedEntries)
  }
  for (const cachedPath of gatewayLogTailSnapshots.keys()) {
    if (!activePaths.has(cachedPath)) gatewayLogTailSnapshots.delete(cachedPath)
  }

  const byKey = new Map<string, GatewayLogEntry>()
  for (const entry of entries) {
    const key = `${entry.timestamp}|${entry.stream}|${entry.message}`
    if (!byKey.has(key)) byKey.set(key, entry)
  }
  return Array.from(byKey.values())
    .sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp))
    .slice(0, limit)
}

async function readGatewayRpcLogEntries(limit = 120): Promise<GatewayLogEntry[] | null> {
  const client = gatewayClientState?.ready ? gatewayClientState.client : null
  if (!client) return null

  try {
    const payload = await client.request('logs.tail', {
      limit: Math.max(limit * 4, limit),
      maxBytes: Math.min(GATEWAY_LOG_TAIL_MAX_BYTES, 250_000),
    }, { timeoutMs: 2_500 })
    if (!isLooseRecord(payload) || !Array.isArray(payload.lines)) return null
    const source = typeof payload.file === 'string' && payload.file.trim()
      ? payload.file.trim()
      : 'gateway:logs.tail'
    const entries = payload.lines
      .filter((line): line is string => typeof line === 'string' && line.trim().length > 0)
      .slice(-Math.max(limit * 4, limit))
      .map((line, index) => parseGatewayFileLogLine(line, source, index))
      .filter((entry): entry is GatewayLogEntry => Boolean(entry))
      .sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp))
      .slice(0, limit)
    return entries
  } catch (error) {
    const now = Date.now()
    if (now - gatewayRpcLogFailureNotifiedAt > GATEWAY_RPC_LOG_FAILURE_NOTICE_MS) {
      gatewayRpcLogFailureNotifiedAt = now
      pushGatewayLog('gateway', `logs.tail unavailable; using local file tail fallback: ${redactSensitiveText(String(error))}`, 'warning')
    }
    return null
  }
}

function gatewayActivityAgentId(message: string) {
  const match = message.match(/^([a-z0-9][a-z0-9-]{1,80})\s+\/\s+[^/]+?\s+(?:heartbeat|mission|unit)\b/i)
  return match?.[1] || undefined
}

function gatewayActivityDirection(message: string): GatewayChannelDirection {
  const text = stripAnsi(message || '').replace(/\s+/g, ' ').trim()
  if (/\b(?:SMS|message|call|update)\s+received\b|\breceived\s+from\b|\binbound\b|\bincoming\b|\bwebhook\b|\bpolling ingress\b|\bgetUpdates\b|\bCoreBridge:\s+running agent turn\b/i.test(text)) return 'inbound'
  if (/\bSMS\s+(?:reply|sent)\b|\breply (?:sent|delivered|failed)\b|\bSending SMS\b|\bInitiating call\b|\boutbound\b|\bsent to\b|\bsend ok\b|\boutbound send ok\b|\bsendMessage\b|\bmessage sent\b|\bcall initiated\b/i.test(text)) return 'outbound'
  if (/^message processed:\s+channel=(?!cron\b|agent\b|chat\b)[a-z0-9_-]+\b/i.test(text)) return 'inbound'
  return 'system'
}

function gatewayActivityDirectionFromRecord(record: Record<string, unknown>, message: string): GatewayChannelDirection {
  const direct = objectStringField(record, 'direction') || objectStringField(record, 'dir')
  const normalized = direct.toLowerCase()
  if (normalized === 'inbound' || normalized === 'incoming' || normalized === 'receive' || normalized === 'received') return 'inbound'
  if (normalized === 'outbound' || normalized === 'outgoing' || normalized === 'send' || normalized === 'sent') return 'outbound'
  if (normalized === 'system' || normalized === 'status' || normalized === 'lifecycle') return 'system'
  const event = [
    objectStringField(record, 'event'),
    objectStringField(record, 'type'),
    objectStringField(record, 'operation'),
    objectStringField(record, 'messageType'),
    objectStringField(record, 'kind'),
  ].filter(Boolean).join(' ')
  return gatewayActivityDirection(`${event} ${message}`)
}

function objectActivityTextField(record: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const raw = record[key]
    if (typeof raw === 'string' && raw.trim()) return raw.trim()
    if ((typeof raw === 'number' || typeof raw === 'boolean') && String(raw).trim()) return String(raw)
  }
  return ''
}

function clawTalkWsLogCandidates() {
  const candidates = new Set<string>([
    path.join(OPENCLAW_STATE_ROOT, 'plugins', 'clawtalk', 'ws.log'),
    path.join(NATIVE_OPENCLAW_STATE_ROOT, 'plugins', 'clawtalk', 'ws.log'),
  ])
  const configured = process.env.CLAWTALK_WS_LOG_PATH || process.env.OPENCLAW_CLAWTALK_WS_LOG_PATH || ''
  if (configured.trim()) candidates.add(path.resolve(configured.trim()))
  return Array.from(candidates)
}

function channelActivityLabel(channel: string, event: string, direction: GatewayChannelDirection) {
  const text = `${channel} ${event}`.replace(/[._-]+/gu, ' ').replace(/\s+/g, ' ').trim().toLowerCase()
  if (/\bsms\b/u.test(text) && direction === 'inbound') return 'SMS received'
  if (/\bsms\b/u.test(text) && direction === 'outbound') return 'SMS sent'
  if (/\bcall\b/u.test(text) && direction === 'inbound') return 'Call received'
  if (/\bcall\b/u.test(text) && direction === 'outbound') return 'Call placed'
  if (/\btelegram\b/u.test(text) && direction === 'inbound') return 'Telegram message received'
  if (/\btelegram\b/u.test(text) && direction === 'outbound') return 'Telegram message sent'
  return direction === 'inbound' ? 'Message received' : 'Message sent'
}

function parseClawTalkWsLogLine(line: string, source: string, index: number): GatewayLogEntry | null {
  const trimmed = stripAnsi(line || '').trim()
  const match = trimmed.match(/^(\d{4}-\d{2}-\d{2}T\S+)\s+(<<<|>>>|---)\s*(.*)$/u)
  if (!match) return null

  const marker = match[2]
  if (marker === '---') return null

  const rawPayload = match[3].trim()
  let record: Record<string, unknown> | null = null
  try {
    const parsed = JSON.parse(rawPayload) as unknown
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) record = parsed as Record<string, unknown>
  } catch {
    record = null
  }

  const event = record
    ? objectActivityTextField(record, ['event', 'type', 'kind', 'operation', 'messageType'])
    : rawPayload
  const probe = `${event} ${rawPayload}`
  let direction = gatewayActivityDirection(probe)
  if (direction === 'system') {
    if (marker === '>>>' && /\b(?:send|sent|reply|outbound|message|sms|call)\b/iu.test(probe)) direction = 'outbound'
    if (marker === '<<<' && /\b(?:received|incoming|inbound|message|sms|call|webhook)\b/iu.test(probe)) direction = 'inbound'
  }
  if (direction === 'system') return null

  const eventLower = event.toLowerCase()
  if (/\b(?:auth|hello|ping|pong|connected|heartbeat|ready|registered)\b/iu.test(eventLower)
    && !/\b(?:sms|message|call|received|sent|reply|incoming|outbound)\b/iu.test(eventLower)) {
    return null
  }

  const body = record
    ? objectActivityTextField(record, ['body', 'text', 'message', 'content', 'transcript', 'reply'])
    : ''
  const mediaCount = record && Array.isArray(record.media_urls) ? record.media_urls.length : 0
  const label = channelActivityLabel('clawtalk', event, direction)
  const detail = body
    ? compactGatewayLogMessage(body, 360)
    : mediaCount
      ? `${mediaCount} media attachment${mediaCount === 1 ? '' : 's'}`
      : ''
  const timestamp = !Number.isNaN(Date.parse(match[1])) ? new Date(match[1]).toISOString() : new Date().toISOString()

  return {
    id: gatewayLogEntryId(source, `${index}:${trimmed}`),
    timestamp,
    stream: 'channel',
    channel: 'clawtalk',
    direction,
    source,
    message: detail ? `${label}: ${detail}` : label,
  }
}

async function readClawTalkChannelActivityEntries(limit = 80): Promise<GatewayLogEntry[]> {
  const entries: GatewayLogEntry[] = []
  for (const filePath of clawTalkWsLogCandidates()) {
    const stat = await fs.stat(filePath).catch(() => null)
    if (!stat?.isFile() || stat.size <= 0) continue
    const raw = await readTailText(filePath, Math.min(GATEWAY_LOG_TAIL_MAX_BYTES, 360_000)).catch(() => '')
    const lines = raw.replace(/\r/g, '').split('\n').filter((line) => line.trim())
    lines.slice(-Math.max(limit * 3, limit)).forEach((line, index) => {
      const entry = parseClawTalkWsLogLine(line, filePath, index)
      if (entry) entries.push(entry)
    })
  }
  return entries
    .sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp))
    .slice(0, limit)
}

function gatewayActivityLooksLikeChannelMessage(message: string) {
  const text = stripAnsi(message || '').replace(/\s+/g, ' ').trim()
  return /^message processed:\s+channel=(?!cron\b|agent\b|chat\b)[a-z0-9_-]+\b/iu.test(text)
    || /\b(?:SMS|MMS|message|call|update)\s+received\b|\breceived\s+from\b|\binbound\b|\bincoming\b|\bwebhook\b|\bpolling ingress\b|\bgetUpdates\b|\bCoreBridge:\s+running agent turn\b/iu.test(text)
    || /\bSMS\s+(?:reply|sent)\b|\breply (?:sent|delivered|failed)\b|\bSending SMS\b|\bInitiating call\b|\boutbound\b|\bsent to\b|\bsend ok\b|\boutbound send ok\b|\bsendMessage\b|\bmessage sent\b|\bcall initiated\b/iu.test(text)
    || /\b(?:telegram|clawtalk|sms|imessage|whatsapp|signal|discord|slack|matrix|mattermost|msteams|googlechat|line|wechat)\b.*\b(?:received|sent|reply|incoming|outbound|inbound|send|delivered)\b/iu.test(text)
    || /\b(?:received|sent|reply|incoming|outbound|inbound|send|delivered)\b.*\b(?:telegram|clawtalk|sms|message|call|discord|slack|whatsapp)\b/iu.test(text)
}

function isGatewayChannelActivity(entry: GatewayLogEntry) {
  const direction = entry.direction || gatewayActivityDirection(entry.message)
  if (direction !== 'inbound' && direction !== 'outbound') return false
  return Boolean(entry.channel || gatewayChannelFromMessage(entry.message) || entry.stream === 'channel')
    && gatewayActivityLooksLikeChannelMessage(entry.message)
}

function summarizeGatewayActivity(entries: GatewayLogEntry[], activeWindowMs = 10 * 60 * 1000): GatewayActivitySummary {
  const events = entries
    .filter(isGatewayChannelActivity)
    .map((entry): GatewayChannelActivity => ({
      id: entry.id,
      timestamp: entry.timestamp,
      channel: entry.channel || entry.message.match(/\[([a-z0-9_-]+)]/i)?.[1]?.toLowerCase() || 'gateway',
      direction: entry.direction || gatewayActivityDirection(entry.message),
      message: entry.message,
      level: entry.level,
      source: entry.source,
      agentId: gatewayActivityAgentId(entry.message),
    }))
    .sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp))
    .slice(0, 60)

  const lastEventAt = events[0]?.timestamp || null
  const lastMs = lastEventAt ? Date.parse(lastEventAt) : NaN
  return {
    active: Number.isFinite(lastMs) ? Date.now() - lastMs <= activeWindowMs : false,
    lastEventAt,
    sourcePath: events[0]?.source || entries[0]?.source || null,
    inboundCount: events.filter((event) => event.direction === 'inbound').length,
    outboundCount: events.filter((event) => event.direction === 'outbound').length,
    systemCount: events.filter((event) => event.direction === 'system').length,
    events,
  }
}

function runtimeLoadedPluginIdsFromGatewayLogs(entries: GatewayLogEntry[]) {
  const ids = new Set<string>()
  for (const entry of entries) {
    const match = entry.message.match(/\bhttp server listening\s+\(\d+\s+plugins?:\s*([^;)]+)/i)
    if (!match) continue
    for (const id of match[1].split(',')) {
      const normalized = id.trim().toLowerCase()
      if (PLUGIN_ID_PATTERN.test(normalized)) ids.add(normalized)
    }
    if (ids.size) break
  }
  return ids
}

function spawnText(
  command: string,
  args: string[],
  options: { timeoutMs?: number; windowsHide?: boolean } = {},
): Promise<{ stdout: string; stderr: string; code: number | null; timedOut: boolean }> {
  return new Promise((resolve) => {
    const child = spawn(command, args, {
      shell: false,
      ...(process.platform === 'win32' ? { windowsHide: options.windowsHide ?? true } : {}),
    })
    let stdout = ''
    let stderr = ''
    let settled = false
    const timeout = options.timeoutMs
      ? setTimeout(() => {
          if (settled) return
          settled = true
          void terminateProcessTree(child.pid, `${command} helper timeout`, true)
          resolve({ stdout, stderr, code: null, timedOut: true })
        }, options.timeoutMs)
      : null

    child.stdout.on('data', (chunk) => {
      stdout += chunk.toString()
    })
    child.stderr.on('data', (chunk) => {
      stderr += chunk.toString()
    })
    child.on('error', (error) => {
      if (settled) return
      settled = true
      if (timeout) clearTimeout(timeout)
      resolve({ stdout, stderr: stderr || String(error), code: 1, timedOut: false })
    })
    child.on('close', (code) => {
      if (settled) return
      settled = true
      if (timeout) clearTimeout(timeout)
      resolve({ stdout, stderr, code, timedOut: false })
    })
  })
}

async function gatewayListenerPidForPort(port: number) {
  const now = Date.now()
  if (gatewayListenerPidCache && now - gatewayListenerPidCache.checkedAt < 7_500) return gatewayListenerPidCache.pid
  let pid: number | null = null
  if (process.platform === 'win32') {
    const result = await spawnText('powershell.exe', [
      '-NoProfile',
      '-NonInteractive',
      '-Command',
      `(Get-NetTCPConnection -LocalPort ${port} -State Listen -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty OwningProcess)`,
    ], {
      windowsHide: true,
      timeoutMs: 2500,
    })
    const parsed = Number((result.stdout || '').trim().split(/\s+/)[0])
    if (Number.isFinite(parsed) && parsed > 0) pid = parsed
  } else {
    const result = await spawnText('sh', ['-c', `command -v lsof >/dev/null 2>&1 && lsof -tiTCP:${port} -sTCP:LISTEN | head -n 1 || true`], {
      timeoutMs: 2500,
    })
    const parsed = Number((result.stdout || '').trim().split(/\s+/)[0])
    if (Number.isFinite(parsed) && parsed > 0) pid = parsed
  }
  gatewayListenerPidCache = { checkedAt: now, pid }
  return pid
}

function openClawCommandOutput(result: OpenClawResult) {
  return redactSensitiveText(stripAnsi(`${result.stdout || ''}\n${result.stderr || ''}`)).trim()
}

function compactOpenClawCommandOutput(result: OpenClawResult, fallback: string) {
  const output = openClawCommandOutput(result)
  return compactGatewayLogMessage(output || fallback, 900)
}

function openClawValidateResultIsValid(result: OpenClawResult) {
  if (result.code !== 0) return false
  const text = (result.stdout || '').trim()
  if (!text) return true
  try {
    const parsed = JSON.parse(text) as { valid?: unknown; ok?: unknown }
    return parsed.valid === true || parsed.ok === true
  } catch {
    return /\b(valid|ok)\b/i.test(text) && !/\binvalid\b/i.test(text)
  }
}

function isInvalidOpenClawConfigText(value: string) {
  return /\bInvalid config\b/i.test(value)
    || /\bconfig schema validation failed\b/i.test(value)
    || /\bconfig reload skipped \(invalid config\)/i.test(value)
    || /\bagents\.list\.\d+:\s*Invalid input\b/i.test(value)
}

async function promoteValidatedOpenClawConfigLastGood(reason: string) {
  try {
    const raw = await readTextFileWithLockRetry(OPENCLAW_CONFIG_PATH)
    await writeTextFileWithLockRetry(`${OPENCLAW_CONFIG_PATH}.last-good`, raw.endsWith('\n') ? raw : `${raw}\n`)
    pushGatewayLog('lifecycle', `validated OpenClaw config promoted to last-good (${reason})`)
  } catch (error) {
    console.warn(`[gateway] failed to promote validated config backup (${reason}):`, error)
  }
}

async function validateOpenClawConfigForGateway(reason: string) {
  const result = await runOpenClaw(['config', 'validate', '--json'], GATEWAY_CONFIG_VALIDATE_TIMEOUT_MS)
  const valid = openClawValidateResultIsValid(result)
  const detail = compactOpenClawCommandOutput(result, valid ? 'OpenClaw config valid.' : `openclaw config validate exited ${result.code}`)
  if (valid) {
    await promoteValidatedOpenClawConfigLastGood(reason)
  } else {
    pushGatewayLog('lifecycle', `OpenClaw config validation failed (${reason}): ${detail}`)
  }
  return { valid, detail, result }
}

function pauseGatewayAutoRestartForInvalidConfig(detail: string) {
  gatewayAutoRestartPaused = true
  if (gatewayRestartTimer) {
    clearTimeout(gatewayRestartTimer)
    gatewayRestartTimer = null
  }
  const message = `Gateway auto-restart paused: OpenClaw config is still invalid after repair. ${detail}`
  console.warn(`[gateway] ${message}`)
  pushGatewayLog('lifecycle', message)
}

function pauseGatewayAutoRestartForRuntimeUnavailable(detail: string) {
  gatewayAutoRestartPaused = true
  if (gatewayRestartTimer) {
    clearTimeout(gatewayRestartTimer)
    gatewayRestartTimer = null
  }
  const message = `Gateway auto-restart paused: OpenClaw runtime is unavailable. ${detail}`
  console.warn(`[gateway] ${message}`)
  pushGatewayLog('lifecycle', message)
}

async function repairOpenClawConfigForGateway(reason: string) {
  pushGatewayLog('lifecycle', `running OpenClaw doctor repair for config (${reason})`)
  const result = await runOpenClaw(
    ['doctor', '--fix', '--non-interactive', '--yes', '--no-workspace-suggestions'],
    GATEWAY_CONFIG_DOCTOR_TIMEOUT_MS,
  )
  openclawConfigCache = null
  availableModelsCache = null
  const detail = compactOpenClawCommandOutput(result, `openclaw doctor --fix exited ${result.code}`)
  if (result.code === 0) {
    pushGatewayLog('lifecycle', `OpenClaw doctor repair completed (${reason})`)
  } else {
    pushGatewayLog('lifecycle', `OpenClaw doctor repair failed (${reason}): ${detail}`)
  }
  return { ok: result.code === 0, detail, result }
}

async function prepareOpenClawConfigForGatewayStartup(reason: string) {
  if (gatewayConfigPreflightInFlight) return gatewayConfigPreflightInFlight
  gatewayConfigPreflightInFlight = (async () => {
    try {
      if (!isOpenClawRuntimeAvailable()) {
        const detail = openClawRuntimeUnavailableMessage()
        pushGatewayLog('lifecycle', `OpenClaw config validation skipped (${reason}): ${detail}`)
        pauseGatewayAutoRestartForRuntimeUnavailable(detail)
        return false
      }
      openclawConfigCache = null
      const config = await readOpenclawConfig()
      await writeOpenclawConfig(config)
      let validation = await validateOpenClawConfigForGateway(reason)
      if (validation.valid) return true

      const repair = await repairOpenClawConfigForGateway(reason)
      openclawConfigCache = null
      const repairedConfig = await readOpenclawConfig().catch(() => null)
      if (repairedConfig) await writeOpenclawConfig(repairedConfig)
      validation = await validateOpenClawConfigForGateway(`${reason}; after doctor repair`)
      if (validation.valid) {
        gatewayAutoRestartPaused = false
        gatewayRestartCount = 0
        pushGatewayLog('lifecycle', 'OpenClaw config repaired and validated; gateway startup may continue')
        return true
      }

      pauseGatewayAutoRestartForInvalidConfig(validation.detail || repair.detail)
      return false
    } catch (error) {
      const detail = compactGatewayLogMessage(redactSensitiveText(stripAnsi(String(error))), 900)
      pauseGatewayAutoRestartForInvalidConfig(detail)
      return false
    }
  })().finally(() => {
    gatewayConfigPreflightInFlight = null
  })
  return gatewayConfigPreflightInFlight
}

function spawnGateway(): Promise<{ pid: number }> {
  return new Promise((resolve, reject) => {
    if (!isOpenClawRuntimeAvailable()) {
      reject(new Error(openClawRuntimeUnavailableMessage()))
      return
    }
    const spec = openClawSpawnSpec(['gateway', 'run', '--port', String(GATEWAY_HTTP_PORT), '--allow-unconfigured'])
    const env = openClawProcessEnv({
      CONTROL_CENTER_AGENT_TURN_STREAM_URL: `http://127.0.0.1:${PORT}/api/openclaw/agent-turn/stream`,
      CLAWTALK_CONTROL_CENTER_AGENT_TURN_STREAM_URL: `http://127.0.0.1:${PORT}/api/openclaw/agent-turn/stream`,
      CLAWTALK_CONTROL_CENTER_CONSOLE_FINAL_URL: `http://127.0.0.1:${PORT}/api/openclaw/clawtalk-console/final`,
    })
    const child = spawn(spec.command, spec.args, {
      cwd: openClawRuntimeCwd(),
      env,
      shell: spec.shell,
      stdio: 'pipe',
      ...(process.platform === 'win32' ? { windowsHide: true } : {}),
    })
    let settled = false
    let stdout = ''
    let stderr = ''
    let sawInvalidConfig = false
    let sawHttpListening = false
    let sawReady = false
    let sawAgentRuntimePrewarm = false
    let sawProviderAuthPrewarm = false
    let readyFallbackTimer: NodeJS.Timeout | null = null
    const settle = (callback: () => void) => {
      if (settled) return
      settled = true
      if (readyFallbackTimer) {
        clearTimeout(readyFallbackTimer)
        readyFallbackTimer = null
      }
      callback()
    }
    gatewayLastStartedAt = new Date().toISOString()
    gatewayLastExitAt = null
    gatewayLastExitCode = null
    pushGatewayLog(
      'lifecycle',
      `starting OpenClaw gateway on port ${GATEWAY_HTTP_PORT} (pid=${child.pid ?? 'n/a'}, config=${OPENCLAW_CONFIG_PATH}, state=${OPENCLAW_STATE_ROOT})`,
    )
    child.stdout.on('data', (chunk) => {
      const text = chunk.toString()
      stdout = appendBoundedRuntimeOutput(stdout, text)
      if (isInvalidOpenClawConfigText(text)) sawInvalidConfig = true
      const visibleOutput = formatGatewayProcessOutput('[gateway]', text)
      if (visibleOutput) process.stdout.write(visibleOutput)
      pushGatewayLog('stdout', text)
      const lowerText = text.toLowerCase()
      if (!sawHttpListening && lowerText.includes('http server listening')) {
        sawHttpListening = true
        recordGatewayStartupEvent('http', 'completed', 'Gateway HTTP server is listening', { pid: child.pid ?? null })
      }
      if (!sawReady && lowerText.includes('ready')) {
        sawReady = true
        recordGatewayStartupEvent('ready', 'completed', 'Gateway reported ready', { pid: child.pid ?? null })
      }
      if (!sawAgentRuntimePrewarm && lowerText.includes('agent runtime plugins pre-warmed')) {
        sawAgentRuntimePrewarm = true
        recordGatewayStartupEvent('prewarm', 'completed', 'Agent runtime plugins pre-warmed', { pid: child.pid ?? null })
      }
      if (!sawProviderAuthPrewarm && lowerText.includes('provider auth state pre-warmed')) {
        sawProviderAuthPrewarm = true
        recordGatewayStartupEvent('prewarm', 'completed', 'Provider auth state pre-warmed', { pid: child.pid ?? null })
      }
      if (lowerText.includes('ready') || lowerText.includes('http server listening')) {
        settle(() => resolve({ pid: child.pid ?? 0 }))
      }
    })
    child.stderr.on('data', (chunk) => {
      const text = chunk.toString()
      stderr = appendBoundedRuntimeOutput(stderr, text)
      if (isInvalidOpenClawConfigText(text)) sawInvalidConfig = true
      const visibleOutput = formatGatewayProcessOutput('[gateway-err]', text)
      if (visibleOutput) process.stderr.write(visibleOutput)
      pushGatewayLog('stderr', text)
    })
    child.on('error', (err) => {
      pushGatewayLog('lifecycle', `gateway process error: ${err.message}`)
      recordGatewayStartupEvent('failed', 'failed', `Gateway process error: ${err.message}`, { pid: child.pid ?? null })
      settle(() => reject(err))
    })
    child.on('close', (code) => {
      console.log(`[gateway] process exited (code=${code})`)
      gatewayLastExitAt = new Date().toISOString()
      gatewayLastExitCode = code ?? null
      pushGatewayLog('lifecycle', `process exited (code=${code ?? 'unknown'})`)
      recordGatewayStartupEvent(
        'exit',
        code === 0 || shuttingDown ? 'completed' : 'failed',
        `Gateway process exited with code ${code ?? 'unknown'}`,
        { pid: child.pid ?? null },
      )
      if (gatewayProcess === child) {
        gatewayProcess = null
        gatewayProcessOwnedByControlCenter = false
        gatewayStartupGraceUntilMs = 0
      }
      scheduleOpenClawSessionLockSweep('gateway process exit')
      const detail = compactGatewayLogMessage(redactSensitiveText(stripAnsi(`${stderr}\n${stdout}`)).trim(), 1200)
      settle(() => reject(new Error(`Gateway exited prematurely with code ${code}${detail ? `: ${detail}` : ''}`)))
      if (!shuttingDown && !gatewayAutoRestartPaused) {
        if (sawInvalidConfig) {
          pushGatewayLog('lifecycle', 'gateway exited after invalid config; startup repair will handle retry')
          return
        }
        void isGatewayHealthy().then((healthy) => {
          if (healthy) {
            gatewayRestartCount = 0
            return
          }
          scheduleGatewayRestart()
        })
      }
    })
    gatewayProcess = child
    gatewayProcessOwnedByControlCenter = true
    // Resolve after a grace period even without the "ready" line
    readyFallbackTimer = setTimeout(() => {
      settle(() => resolve({ pid: child.pid ?? 0 }))
    }, 10000)
    readyFallbackTimer.unref?.()
  })
}

function scheduleGatewayRestart(): void {
  if (shuttingDown || gatewayAutoRestartPaused) return
  if (gatewayRestartTimer || gatewayEnsureInFlight) return
  const backoffMs = Math.min(1000 * Math.pow(2, gatewayRestartCount), 30000)
  gatewayRestartCount += 1
  console.log(`[gateway] scheduling restart in ${backoffMs}ms (attempt #${gatewayRestartCount})`)
  pushGatewayLog('lifecycle', `restart scheduled in ${backoffMs}ms (attempt #${gatewayRestartCount})`)
  if (gatewayRestartTimer) clearTimeout(gatewayRestartTimer)
  gatewayRestartTimer = setTimeout(() => {
    gatewayRestartTimer = null
    void ensureGatewayRunning()
  }, backoffMs)
}

type GatewayHealthPayload = {
  ok?: boolean
  status?: string
  plugins?: {
    loaded?: unknown[]
    errors?: unknown[]
  }
  [key: string]: unknown
}

type GatewayReadinessEventLoop = {
  degraded: boolean
  reasons: string[]
  intervalMs?: number
  delayP99Ms?: number
  delayMaxMs?: number
  utilization?: number
  cpuCoreRatio?: number
}

type GatewayReadinessPayload = {
  ready?: boolean
  ok?: boolean
  status?: string
  failing?: unknown[]
  uptimeMs?: unknown
  eventLoop?: unknown
  [key: string]: unknown
}

type GatewayReadinessSummary = {
  reachable: boolean
  ready: boolean
  degraded: boolean
  checkedAt: string | null
  httpStatus?: number
  status?: string
  failing: string[]
  uptimeMs: number | null
  eventLoop: GatewayReadinessEventLoop | null
  error?: string
}

async function fetchGatewayHealthPayload(): Promise<{ healthy: boolean; payload: GatewayHealthPayload | null }> {
  try {
    const res = await fetch(`http://127.0.0.1:${GATEWAY_HTTP_PORT}/health`, {
      signal: AbortSignal.timeout(3000),
    })
    if (!res.ok) return { healthy: false, payload: null }
    const text = await res.text()
    try {
      const body = JSON.parse(text) as GatewayHealthPayload
      const healthy = body.ok === true || /^ok$/i.test(String(body.status || ''))
      if (healthy) gatewayLastHealthyAt = new Date().toISOString()
      return { healthy, payload: body }
    } catch {
      const healthy = /\bok\b/i.test(text)
      if (healthy) gatewayLastHealthyAt = new Date().toISOString()
      return { healthy, payload: null }
    }
  } catch {
    // not reachable
  }
  return { healthy: false, payload: null }
}

function numberFromRecord(record: Record<string, unknown>, key: string): number | undefined {
  const value = record[key]
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined
}

function gatewayReadinessEventLoop(payload: GatewayReadinessPayload | null): GatewayReadinessEventLoop | null {
  const eventLoop = isLooseRecord(payload?.eventLoop) ? payload.eventLoop as Record<string, unknown> : null
  if (!eventLoop) return null
  const reasons = Array.isArray(eventLoop.reasons)
    ? eventLoop.reasons.map((reason) => sanitizeGatewayStartupMessage(String(reason), 120)).filter(Boolean).slice(0, 6)
    : []
  return {
    degraded: eventLoop.degraded === true,
    reasons,
    ...(numberFromRecord(eventLoop, 'intervalMs') !== undefined ? { intervalMs: numberFromRecord(eventLoop, 'intervalMs') } : {}),
    ...(numberFromRecord(eventLoop, 'delayP99Ms') !== undefined ? { delayP99Ms: numberFromRecord(eventLoop, 'delayP99Ms') } : {}),
    ...(numberFromRecord(eventLoop, 'delayMaxMs') !== undefined ? { delayMaxMs: numberFromRecord(eventLoop, 'delayMaxMs') } : {}),
    ...(numberFromRecord(eventLoop, 'utilization') !== undefined ? { utilization: numberFromRecord(eventLoop, 'utilization') } : {}),
    ...(numberFromRecord(eventLoop, 'cpuCoreRatio') !== undefined ? { cpuCoreRatio: numberFromRecord(eventLoop, 'cpuCoreRatio') } : {}),
  }
}

function gatewayReadinessFailures(payload: GatewayReadinessPayload | null): string[] {
  const failing = Array.isArray(payload?.failing) ? payload.failing : []
  return failing.map((entry) => sanitizeGatewayStartupMessage(
    typeof entry === 'string' ? entry : JSON.stringify(entry),
    160,
  )).filter(Boolean).slice(0, 8)
}

function gatewayReadinessUnavailable(error?: string): GatewayReadinessSummary {
  return {
    reachable: false,
    ready: false,
    degraded: false,
    checkedAt: null,
    failing: [],
    uptimeMs: null,
    eventLoop: null,
    ...(error ? { error: sanitizeGatewayStartupMessage(error, 180) } : {}),
  }
}

async function fetchGatewayReadinessPayload(): Promise<GatewayReadinessSummary> {
  const checkedAt = new Date().toISOString()
  try {
    const res = await fetch(`http://127.0.0.1:${GATEWAY_HTTP_PORT}/readyz`, {
      signal: AbortSignal.timeout(3000),
    })
    const text = await res.text()
    let payload: GatewayReadinessPayload | null = null
    try {
      payload = JSON.parse(text) as GatewayReadinessPayload
    } catch {
      payload = null
    }
    const status = typeof payload?.status === 'string' ? payload.status : undefined
    const eventLoop = gatewayReadinessEventLoop(payload)
    const failing = gatewayReadinessFailures(payload)
    const uptimeMs = typeof payload?.uptimeMs === 'number' && Number.isFinite(payload.uptimeMs) ? payload.uptimeMs : null
    const bodyReady = payload?.ready === true || payload?.ok === true || /^(ready|ok)$/iu.test(String(status || ''))
    const ready = res.ok && bodyReady
    return {
      reachable: true,
      ready,
      degraded: Boolean(eventLoop?.degraded) || failing.length > 0,
      checkedAt,
      httpStatus: res.status,
      ...(status ? { status } : {}),
      failing,
      uptimeMs,
      eventLoop,
    }
  } catch (error) {
    return gatewayReadinessUnavailable(String(error))
  }
}

async function isGatewayHealthy(): Promise<boolean> {
  const health = await fetchGatewayHealthPayload()
  return health.healthy
}

function gatewayStartupGraceRemainingMs(now = Date.now()): number {
  return Math.max(0, gatewayStartupGraceUntilMs - now)
}

function markGatewayStartupGrace(): void {
  gatewayStartupGraceUntilMs = Math.max(gatewayStartupGraceUntilMs, Date.now() + GATEWAY_STARTUP_HEALTH_GRACE_MS)
}

async function waitForGatewayStartupHealth(timeoutMs = GATEWAY_STARTUP_HEALTH_CONFIRM_TIMEOUT_MS): Promise<boolean> {
  const deadline = Date.now() + timeoutMs
  while (Date.now() <= deadline) {
    if (await isGatewayHealthy()) return true
    if (gatewayProcess?.pid && !isPidAlive(gatewayProcess.pid)) return false
    await delayMs(GATEWAY_STARTUP_HEALTH_POLL_MS)
  }
  return false
}

// Periodic health check + auto-restart
let gatewayHealthCheckInterval: NodeJS.Timeout | null = null

function startGatewayHealthMonitor(): void {
  if (gatewayHealthCheckInterval) return
  gatewayHealthCheckInterval = setInterval(async () => {
    if (shuttingDown) return
    if (gatewayAutoRestartPaused) return
    if (gatewayEnsureInFlight || gatewayStartupGraceRemainingMs() > 0) return
    const healthy = await isGatewayHealthy()
    if (!healthy && !gatewayProcess) {
      console.log('[gateway] health check failed — attempting restart')
      scheduleGatewayRestart()
    } else if (healthy && gatewayRestartCount > 0) {
      // Reset restart backoff on sustained health
      gatewayRestartCount = 0
    }
  }, 15000)
}

function stopGatewayHealthMonitor(): void {
  if (gatewayHealthCheckInterval) {
    clearInterval(gatewayHealthCheckInterval)
    gatewayHealthCheckInterval = null
  }
}

async function ensureGatewayRunning(): Promise<void> {
  if (gatewayEnsureInFlight) return gatewayEnsureInFlight
  gatewayEnsureInFlight = ensureGatewayRunningInner().finally(() => {
    gatewayEnsureInFlight = null
  })
  return gatewayEnsureInFlight
}

async function ensureGatewayRunningInner(): Promise<void> {
  gatewayAutoRestartPaused = false
  if (await isGatewayHealthy()) {
    gatewayStartupGraceUntilMs = 0
    return
  }

  const repairedClawTalkManifests = await repairClawTalkPluginManifestContracts().catch((error) => {
    console.warn('[plugins/clawtalk] startup repair failed:', error)
    return [] as string[]
  })
  const repairedTelegramRuntimes = await repairTelegramAgentRoutingRuntime().catch((error) => {
    console.warn('[plugins/telegram] startup agent-routing repair failed:', error)
    return [] as string[]
  })
  if (repairedClawTalkManifests.length) {
    console.info(`[plugins/clawtalk] repaired package contracts/runtime in ${repairedClawTalkManifests.length} install(s)`)
    await refreshOpenClawPluginRegistry('clawtalk-startup-repair').catch((error) => {
      console.warn('[plugins/clawtalk] registry refresh after startup repair failed:', error)
    })
  }
  if (repairedTelegramRuntimes.length) {
    console.info(`[plugins/telegram] repaired agent-routing runtime in ${repairedTelegramRuntimes.length} install(s)`)
  }
  const healthy = await isGatewayHealthy()
  if (healthy) {
    const repairedRuntimeLabels = [
      repairedClawTalkManifests.length ? 'ClawTalk' : '',
      repairedTelegramRuntimes.length ? 'Telegram' : '',
    ].filter(Boolean)
    if (repairedRuntimeLabels.length) {
      if (!gatewayProcessOwnedByControlCenter || !gatewayProcess) {
        const detail = `external gateway is healthy; restart it to load repaired ${repairedRuntimeLabels.join(' and ')} runtime`
        console.info(`[gateway] ${detail}`)
        pushGatewayLog('lifecycle', detail)
        gatewayRestartCount = 0
        gatewayStartupGraceUntilMs = 0
        return
      }
      console.info(`[gateway] restarting owned healthy gateway to load repaired ${repairedRuntimeLabels.join(' and ')} runtime`)
      pushGatewayLog('lifecycle', `restarting owned gateway to load repaired ${repairedRuntimeLabels.join(' and ')} runtime`)
      await terminateProcessTree(gatewayProcess.pid, 'gateway repaired runtime restart', true).catch(() => ({ ok: false, detail: 'terminate failed' }))
      gatewayProcess = null
      gatewayProcessOwnedByControlCenter = false
      await delayMs(750)
    } else {
      console.log(`[gateway] already healthy on port ${GATEWAY_HTTP_PORT}`)
      gatewayRestartCount = 0
      gatewayStartupGraceUntilMs = 0
      return
    }
  }

  const portBusy = await checkTcpPort('127.0.0.1', GATEWAY_HTTP_PORT, 700)
  if (portBusy) {
    const now = Date.now()
    if (now - lastGatewayPortReleaseAt < 5000) {
      console.warn(`[gateway] port ${GATEWAY_HTTP_PORT} is busy but unhealthy; waiting before another recovery attempt`)
      return
    }
    lastGatewayPortReleaseAt = now
    console.warn(`[gateway] port ${GATEWAY_HTTP_PORT} accepts TCP but did not answer /health; releasing stale listener`)
    const released = await tryReleaseGatewayPort()
    console.warn(`[gateway] stale listener release ${released.released ? 'ok' : 'failed'}: ${released.detail}`)
    if (!released.released && (await checkTcpPort('127.0.0.1', GATEWAY_HTTP_PORT, 700))) {
      return
    }
  }

  console.log(`[gateway] starting OpenClaw gateway on port ${GATEWAY_HTTP_PORT}...`)
  markGatewayStartupGrace()
  resetGatewayStartupTimeline(`Gateway startup requested on port ${GATEWAY_HTTP_PORT}`)
  pushGatewayLog('lifecycle', `starting requested on port ${GATEWAY_HTTP_PORT}`)
  try {
    await sweepOpenClawSessionLocks('gateway startup', { minIntervalMs: 0, minAgeMs: 0 })
    await ensureGatewayStartupPluginDefaults()
    recordGatewayStartupEvent('config', 'started', 'Validating OpenClaw config')
    const configReady = await prepareOpenClawConfigForGatewayStartup('gateway startup')
    if (!configReady) {
      gatewayStartupGraceUntilMs = 0
      recordGatewayStartupEvent('config', 'failed', 'OpenClaw config validation blocked Gateway startup')
      return
    }
    recordGatewayStartupEvent('config', 'completed', 'OpenClaw config is valid')
    recordGatewayStartupEvent('registry', 'started', 'Refreshing plugin registry before startup')
    await refreshOpenClawPluginRegistry('gateway-startup').then((result) => {
      if (result.code === 0) {
        recordGatewayStartupEvent('registry', 'completed', 'Plugin registry refresh completed')
      } else {
        recordGatewayStartupEvent('registry', 'warning', `Plugin registry refresh exited ${result.code}`)
      }
    }).catch((error) => {
      console.warn('[plugins] registry refresh before gateway startup failed:', error)
      recordGatewayStartupEvent('registry', 'warning', `Plugin registry refresh failed: ${String(error)}`)
    })
    recordGatewayStartupEvent('spawned', 'started', 'Spawning Gateway process')
    const { pid } = await spawnGateway()
    recordGatewayStartupEvent('spawned', 'completed', `Gateway process spawned with pid ${pid}`, { pid })
    console.log(`[gateway] started with pid ${pid}`)
    pushGatewayLog('lifecycle', `started with pid ${pid}`)
    if (await waitForGatewayStartupHealth()) {
      gatewayStartupGraceUntilMs = 0
      recordGatewayStartupEvent('healthy', 'completed', 'Gateway health confirmed', { pid })
      console.log(`[gateway] healthy on http://127.0.0.1:${GATEWAY_HTTP_PORT}`)
      gatewayRestartCount = 0
      pushGatewayLog('lifecycle', `healthy on http://127.0.0.1:${GATEWAY_HTTP_PORT}`)
      return
    }
    const detail = `health check did not confirm within ${GATEWAY_STARTUP_HEALTH_CONFIRM_TIMEOUT_MS}ms, but process is running`
    console.warn(`[gateway] ${detail}`)
    pushGatewayLog('lifecycle', detail)
    recordGatewayStartupEvent('warning', 'warning', detail, { pid })
  } catch (err) {
    console.error('[gateway] failed to start:', err)
    pushGatewayLog('lifecycle', `failed to start: ${String(err)}`)
    recordGatewayStartupEvent('failed', 'failed', `Gateway startup failed: ${String(err)}`)
    if (isInvalidOpenClawConfigText(String(err))) {
      const repaired = await prepareOpenClawConfigForGatewayStartup('gateway invalid-config recovery')
      if (repaired && !shuttingDown) {
        pushGatewayLog('lifecycle', 'retrying gateway startup after config repair')
        setTimeout(() => {
          void ensureGatewayRunning()
        }, 500).unref?.()
      }
    }
    if (!gatewayProcess) gatewayStartupGraceUntilMs = 0
  }
}

function stopGateway(): void {
  if (!gatewayProcess) return
  console.log('[gateway] stopping...')
  pushGatewayLog('lifecycle', 'stopping gateway process')
  try {
    void terminateProcessTree(gatewayProcess.pid, 'gateway stop')
  } catch {
    // already dead
  }
  const exitTimer = setTimeout(() => {
    if (gatewayProcess) {
      try {
        void terminateProcessTree(gatewayProcess.pid, 'gateway stop escalation', true)
      } catch {
        // already dead
      }
    }
  }, 5000)
  gatewayProcess.on('close', () => {
    clearTimeout(exitTimer)
    console.log('[gateway] stopped')
    pushGatewayLog('lifecycle', 'gateway stopped')
    gatewayProcess = null
    gatewayProcessOwnedByControlCenter = false
  })
}

async function stopGatewayRuntime(reason = 'manual stop'): Promise<{ stopped: boolean; detail: string; port: number; pid: number | null }> {
  gatewayAutoRestartPaused = true
  gatewayStartupGraceUntilMs = 0
  if (gatewayRestartTimer) {
    clearTimeout(gatewayRestartTimer)
    gatewayRestartTimer = null
  }
  stopGatewayHealthMonitor()

  const pid = gatewayProcess?.pid || await gatewayListenerPidForPort(GATEWAY_HTTP_PORT)
  if (gatewayProcess?.pid) {
    try {
      await terminateProcessTree(gatewayProcess.pid, 'manual gateway stop')
    } catch {
      // Process may already be gone; the port release path below is authoritative.
    }
  }

  await new Promise((resolve) => setTimeout(resolve, 500))
  const release = await tryReleaseGatewayPort()
  gatewayProcess = null
  gatewayProcessOwnedByControlCenter = false
  gatewayRestartCount = 0
  gatewayLastExitAt = new Date().toISOString()
  gatewayLastExitCode = null
  gatewayListenerPidCache = null

  const stillBusy = await checkTcpPort('127.0.0.1', GATEWAY_HTTP_PORT, 700)
  const stopped = !stillBusy
  await sweepOpenClawSessionLocks('gateway stop', { minIntervalMs: 0, minAgeMs: 0 })
  pushGatewayLog('lifecycle', `${reason}: gateway ${stopped ? 'stopped' : 'still listening'} on port ${GATEWAY_HTTP_PORT}${pid ? ` pid=${pid}` : ''}`)
  return {
    stopped,
    port: GATEWAY_HTTP_PORT,
    pid: pid || null,
    detail: release.detail,
  }
}

function gatewayStatusSnapshot(healthy: boolean, listenerPid: number | null = null) {
  const managedPid = gatewayProcess?.pid && isPidAlive(gatewayProcess.pid) ? gatewayProcess.pid : null
  const pid = managedPid || listenerPid
  const processRunning = healthy || Boolean(pid && isPidAlive(pid))
  const startupGraceRemainingMs = gatewayStartupGraceRemainingMs()
  const startupTimeline = gatewayStartupTimeline.slice()
  const latestStartupEvent = startupTimeline.length ? startupTimeline[startupTimeline.length - 1] : null
  const startedMs = gatewayLastStartedAt ? new Date(gatewayLastStartedAt).getTime() : NaN
  const state = healthy
    ? 'healthy'
    : gatewayRestartTimer
      ? 'restarting'
      : gatewayEnsureInFlight
        ? 'starting'
        : processRunning
          ? 'starting'
          : startupGraceRemainingMs > 0
            ? 'starting'
            : 'offline'
  return {
    state,
    healthy,
    processRunning,
    pid,
    ownedByControlCenter: Boolean(managedPid && gatewayProcessOwnedByControlCenter),
    port: GATEWAY_HTTP_PORT,
    restartCount: gatewayRestartCount,
    restartScheduled: Boolean(gatewayRestartTimer),
    ensureInFlight: Boolean(gatewayEnsureInFlight),
    startupGraceRemainingMs,
    startup: {
      graceRemainingMs: startupGraceRemainingMs,
      startedAt: startupTimeline[0]?.timestamp || gatewayLastStartedAt,
      lastPhase: latestStartupEvent?.phase || null,
      lastStatus: latestStartupEvent?.status || null,
      timeline: startupTimeline,
    },
    autoRestartPaused: gatewayAutoRestartPaused,
    lastStartedAt: gatewayLastStartedAt,
    lastHealthyAt: gatewayLastHealthyAt,
    lastExitAt: gatewayLastExitAt,
    lastExitCode: gatewayLastExitCode,
    uptimeMs: Number.isFinite(startedMs) && (healthy || processRunning) ? Date.now() - startedMs : 0,
    logs: gatewayLogs.filter((entry) => isRuntimeMonitorEntryVisible(entry.timestamp)).slice(0, 80),
  }
}

async function agentSessionFileSnapshot(agentId: string, sessionId: string) {
  const sessionFile = path.join(OPENCLAW_AGENTS_ROOT, agentId, 'sessions', `${sessionId}.jsonl`)
  const stat = await fs.stat(sessionFile).catch(() => null)
  return {
    sessionFile,
    sessionFileExists: Boolean(stat),
    lastTouchedAt: stat ? new Date(stat.mtimeMs).toISOString() : null,
  }
}

async function openAgentSessionSnapshots(gatewayActivity?: GatewayActivitySummary) {
  const sessionEntries = Array.from(agentTurnSessions.entries())
  const activeRunsBySession = new Map<string, OpenClawRunRecord>()
  for (const run of activeOpenClawRuns.values()) {
    if (run.agentId && run.sessionId) activeRunsBySession.set(`${run.agentId}\0${run.sessionId}`, run)
  }
  const lockReport = await inspectOpenClawSessionLocks({ all: true }).catch((error) => ({
    scanned: 0,
    locks: [] as OpenClawSessionLockInspection[],
    errors: [String(error)],
  }))
  const locksBySession = new Map<string, OpenClawSessionLockInspection>()
  for (const lock of lockReport.locks) {
    locksBySession.set(`${lock.agentId}\0${lock.sessionId}`, lock)
  }
  const gatewayEventsByAgent = new Map<string, GatewayChannelActivity[]>()
  for (const event of gatewayActivity?.events || []) {
    if (!event.agentId) continue
    const events = gatewayEventsByAgent.get(event.agentId)
    if (events) events.push(event)
    else gatewayEventsByAgent.set(event.agentId, [event])
  }
  const seenSessionKeys = new Set<string>()
  const snapshots = await Promise.all(sessionEntries.map(async ([scope, sessionId]) => {
    const agentId = agentTurnSessionScopeAgentId(scope)
    const sessionKey = `${agentId}\0${sessionId}`
    const gatewaySessionKey = activeRunsBySession.get(sessionKey)?.sessionKey || runtimeSessionKeyFromScope(scope, agentId)
    seenSessionKeys.add(sessionKey)
    const history = providerConversationHistories.get(sessionId)
    const activeRun = activeRunsBySession.get(sessionKey)
    const activityEvents = gatewayEventsByAgent.get(agentId) || []
    const inferredActivityEvents = activityEvents.length
      ? activityEvents
      : sessionEntries.length === 1
        ? gatewayActivity?.events || []
        : []
    const lastGatewayEventAt = inferredActivityEvents[0]?.timestamp || null
    const lastGatewayEventMs = lastGatewayEventAt ? Date.parse(lastGatewayEventAt) : NaN
    const gatewayActive = Number.isFinite(lastGatewayEventMs) ? Date.now() - lastGatewayEventMs <= 10 * 60 * 1000 : false
    return {
      agentId,
      sessionScope: scope,
      sessionKey: gatewaySessionKey || null,
      sessionId,
      active: Boolean(activeRun) || gatewayActive,
      activeRunId: activeRun?.id || null,
      provider: history?.provider || null,
      modelId: history?.modelId || null,
      conversationMessages: history?.messages.length || 0,
      updatedAt: history?.updatedAt ? new Date(history.updatedAt).toISOString() : null,
      gatewayActive,
      gatewayLastEventAt: lastGatewayEventAt,
      gatewayEventCount: inferredActivityEvents.length,
      gatewayInboundCount: inferredActivityEvents.filter((event) => event.direction === 'inbound').length,
      gatewayOutboundCount: inferredActivityEvents.filter((event) => event.direction === 'outbound').length,
      ...(locksBySession.has(sessionKey) ? { sessionLock: openClawSessionLockStatus(locksBySession.get(sessionKey)!) } : {}),
      ...(await agentSessionFileSnapshot(agentId, sessionId)),
    }
  }))
  const lockOnlySessions = await Promise.all(Array.from(locksBySession.values())
    .filter((lock) => !seenSessionKeys.has(`${lock.agentId}\0${lock.sessionId}`))
    .map(async (lock) => ({
      agentId: lock.agentId,
      sessionScope: lock.agentId,
      sessionKey: null,
      sessionId: lock.sessionId,
      active: false,
      activeRunId: null,
      provider: null,
      modelId: null,
      conversationMessages: 0,
      updatedAt: null,
      gatewayActive: false,
      gatewayLastEventAt: null,
      gatewayEventCount: 0,
      gatewayInboundCount: 0,
      gatewayOutboundCount: 0,
      sessionLock: openClawSessionLockStatus(lock),
      ...(await agentSessionFileSnapshot(lock.agentId, lock.sessionId)),
    })))
  return [...snapshots, ...lockOnlySessions]
}

async function readExternalGatewayLogEntries(limit = 80): Promise<GatewayLogEntry[]> {
  const now = Date.now()
  if (externalGatewayLogCache && externalGatewayLogCache.expiresAt > now) {
    return externalGatewayLogCache.entries.slice(0, limit)
  }
  const rpcEntries = await readGatewayRpcLogEntries(limit)
  const entries = rpcEntries?.length ? rpcEntries : await readGatewayFileLogEntries(limit)
  externalGatewayLogCache = {
    expiresAt: now + EXTERNAL_GATEWAY_LOG_CACHE_MS,
    entries,
  }
  return entries
}

async function readExternalChannelActivityEntries(limit = 80): Promise<GatewayLogEntry[]> {
  const now = Date.now()
  if (externalChannelActivityCache && externalChannelActivityCache.expiresAt > now) {
    return externalChannelActivityCache.entries.slice(0, limit)
  }
  const entries = await readClawTalkChannelActivityEntries(limit)
  externalChannelActivityCache = {
    expiresAt: now + EXTERNAL_GATEWAY_LOG_CACHE_MS,
    entries,
  }
  return entries
}

function normalizeGatewayLedgerEntry(value: unknown, index: number): GatewayLogEntry | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const record = value as Record<string, unknown>
  const timestamp = typeof record.timestamp === 'string' && !Number.isNaN(Date.parse(record.timestamp))
    ? new Date(record.timestamp).toISOString()
    : ''
  const message = typeof record.message === 'string' ? record.message.trim() : ''
  const stream = typeof record.stream === 'string' ? record.stream.trim().toLowerCase() : ''
  if (!timestamp || !message) return null
  if (stream !== 'stdout' && stream !== 'stderr' && stream !== 'lifecycle' && stream !== 'gateway' && stream !== 'channel') {
    return null
  }
  const id = typeof record.id === 'number' && Number.isFinite(record.id)
    ? record.id
    : gatewayLogEntryId('ledger', `${index}:${timestamp}:${stream}:${message}`)
  const level = typeof record.level === 'string' && record.level.trim() ? record.level.trim() : undefined
  const source = typeof record.source === 'string' && record.source.trim() ? record.source.trim() : undefined
  const channel = typeof record.channel === 'string' && record.channel.trim() ? record.channel.trim() : undefined
  const direction = record.direction === 'inbound' || record.direction === 'outbound' || record.direction === 'system'
    ? record.direction
    : undefined
  return {
    id,
    timestamp,
    stream,
    message: redactSensitiveText(message),
    ...(level ? { level } : {}),
    ...(source ? { source } : {}),
    ...(channel ? { channel } : {}),
    ...(direction ? { direction } : {}),
  }
}

async function readGatewayLedgerLogEntries(limit = 120, options: { sqlite?: boolean } = {}): Promise<GatewayLogEntry[]> {
  const records = await readGatewayEventLedgerTail<unknown>(limit, options).catch(() => [])
  return records
    .map((record, index) => normalizeGatewayLedgerEntry(record, index))
    .filter((entry): entry is GatewayLogEntry => Boolean(entry))
    .sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp))
    .slice(0, limit)
}

function gatewayLogEntriesSinceCurrentStart(entries: GatewayLogEntry[]) {
  const startedAtMs = gatewayLastStartedAt ? Date.parse(gatewayLastStartedAt) : NaN
  const startCutoffMs = Number.isFinite(startedAtMs) ? startedAtMs - 5000 : CONTROL_CENTER_STARTED_AT_MS - 5000
  const cutoffMs = Math.max(startCutoffMs, runtimeMonitorClearedAtMs)
  return entries.filter((entry) => {
    const entryMs = Date.parse(entry.timestamp)
    return Number.isFinite(entryMs) && entryMs >= cutoffMs
  })
}

let controlCenterShutdownInFlight: Promise<{
  sessions: ReturnType<typeof clearAgentTurnSessions>
  terminatedRuns: Awaited<ReturnType<typeof terminateAllOpenClawRunsNow>>
  gateway: Awaited<ReturnType<typeof stopGatewayRuntime>> | null
  sessionLockCleanup: { scanned: number; removed: number; errors: number } | null
}> | null = null
let signalShutdownInFlight = false
let controlServerClosing = false

function clearShutdownPinnedTimers(): void {
  if (availableModelsRefreshTimer) {
    clearTimeout(availableModelsRefreshTimer)
    availableModelsRefreshTimer = null
  }
  if (gatewayRestartTimer) {
    clearTimeout(gatewayRestartTimer)
    gatewayRestartTimer = null
  }
  if (pluginGatewayRestartTimer) {
    clearTimeout(pluginGatewayRestartTimer)
    pluginGatewayRestartTimer = null
  }
  for (const timer of shiftTimers.values()) clearTimeout(timer)
  shiftTimers.clear()
  for (const timers of managedBatchTimers.values()) {
    for (const timer of timers) clearInterval(timer)
  }
  managedBatchTimers.clear()
  for (const timer of missionTimers.values()) clearTimeout(timer)
  missionTimers.clear()
  for (const timer of missionLoopTimers.values()) clearTimeout(timer)
  missionLoopTimers.clear()
}

async function closeControlServerForShutdown(reason: string): Promise<void> {
  if (!controlServer || controlServerClosing) return
  controlServerClosing = true
  const server = controlServer as Server & {
    closeAllConnections?: () => void
    closeIdleConnections?: () => void
  }

  await new Promise<void>((resolve) => {
    let settled = false
    const finish = (error?: Error & { code?: string }) => {
      if (settled) return
      settled = true
      clearTimeout(forceCloseTimer)
      if (error && error.code !== 'ERR_SERVER_NOT_RUNNING') {
        console.warn(`[control-center] ${reason}: HTTP server close warning:`, error)
      }
      resolve()
    }
    const forceCloseTimer = setTimeout(() => {
      server.closeIdleConnections?.()
      server.closeAllConnections?.()
      finish()
    }, 1500)
    forceCloseTimer.unref?.()

    try {
      server.close(finish)
    } catch (error) {
      finish(error instanceof Error ? error : new Error(String(error)))
    }
  })
}

async function shutdownControlCenterRuntime(reason = 'control center shutdown') {
  if (controlCenterShutdownInFlight) return controlCenterShutdownInFlight
  controlCenterShutdownInFlight = (async () => {
    shuttingDown = true
    gatewayAutoRestartPaused = true
    clearShutdownPinnedTimers()
    stopGatewayHealthMonitor()
    stopMissionCronExpirySweep()
    await persistAllMissionRecords(`${reason}:snapshot-before-shutdown`)
    const sessions = clearAgentTurnSessions()
    const terminatedRuns = await terminateAllOpenClawRunsNow(reason)
    const gateway = await stopGatewayRuntime(reason).catch((error) => {
      pushGatewayLog('lifecycle', `${reason}: gateway shutdown warning: ${String(error)}`)
      return null
    })
    const lockCleanup = await sweepOpenClawSessionLocks(reason, { minIntervalMs: 0, minAgeMs: 0 }).catch((error) => {
      pushGatewayLog('lifecycle', `${reason}: session lock cleanup warning: ${String(error)}`)
      return null
    })
    browserProbeCache.clear()
    closeRuntimeLedger()
    return {
      sessions,
      terminatedRuns,
      gateway,
      sessionLockCleanup: lockCleanup
        ? { scanned: lockCleanup.scanned, removed: lockCleanup.removed.length, errors: lockCleanup.errors.length }
        : null,
    }
  })().finally(() => {
    controlCenterShutdownInFlight = null
  })
  return controlCenterShutdownInFlight
}

function handleControlCenterShutdown(signalName: 'SIGTERM' | 'SIGINT' | 'SIGHUP' | 'process exit') {
  if (shuttingDown && signalName !== 'process exit') {
    if (!signalShutdownInFlight) return
    console.warn(`[control-center] ${signalName} received while shutdown is still in progress; forcing exit.`)
    process.exit(1)
  }
  if (signalName !== 'process exit') console.log(`[control-center] received ${signalName}`)
  if (signalName !== 'process exit') {
    signalShutdownInFlight = true
    const forceExitTimer = setTimeout(() => {
      console.warn(`[control-center] ${signalName} shutdown timed out; forcing exit.`)
      process.exit(1)
    }, 10000)
    forceExitTimer.unref?.()

    void (async () => {
      await closeControlServerForShutdown(`${signalName} shutdown`)
      await shutdownControlCenterRuntime(`${signalName} shutdown`)
    })()
      .catch((error) => {
        console.warn(`[control-center] ${signalName} shutdown cleanup failed:`, error)
        process.exitCode = 1
      })
      .finally(() => {
        clearTimeout(forceExitTimer)
        process.exit(typeof process.exitCode === 'number' ? process.exitCode : 0)
      })
    return
  }
  shuttingDown = true
  clearShutdownPinnedTimers()
  terminateAllOpenClawRuns(`${signalName} shutdown`)
  stopGateway()
  stopGatewayHealthMonitor()
  stopMissionCronExpirySweep()
  closeRuntimeLedger()
}

process.on('SIGTERM', () => handleControlCenterShutdown('SIGTERM'))
process.on('SIGINT', () => handleControlCenterShutdown('SIGINT'))
process.on('SIGHUP', () => handleControlCenterShutdown('SIGHUP'))
process.on('exit', () => {
  handleControlCenterShutdown('process exit')
})

function isMarkdownResourceFile(file: string) {
  return /^[^\\/]+\.md$/i.test(file)
}

function contentTypeFromExt(filePath: string) {
  const ext = path.extname(filePath).toLowerCase()
  if (ext === '.html') return 'text/html; charset=utf-8'
  if (ext === '.htm') return 'text/html; charset=utf-8'
  if (ext === '.css') return 'text/css; charset=utf-8'
  if (ext === '.js' || ext === '.jsx' || ext === '.ts' || ext === '.tsx' || ext === '.mjs' || ext === '.cjs') return 'text/javascript; charset=utf-8'
  if (ext === '.json' || ext === '.map') return 'application/json; charset=utf-8'
  if (ext === '.jsonl') return 'application/x-ndjson; charset=utf-8'
  if (ext === '.txt') return 'text/plain; charset=utf-8'
  if (ext === '.md' || ext === '.markdown') return 'text/markdown; charset=utf-8'
  if (ext === '.csv') return 'text/csv; charset=utf-8'
  if (ext === '.tsv') return 'text/tab-separated-values; charset=utf-8'
  if (ext === '.log') return 'text/plain; charset=utf-8'
  if (ext === '.xml') return 'application/xml; charset=utf-8'
  if (ext === '.yaml' || ext === '.yml') return 'application/yaml; charset=utf-8'
  if (ext === '.py' || ext === '.ipynb' || ext === '.java' || ext === '.go' || ext === '.rs' || ext === '.c' || ext === '.cc' || ext === '.cpp' || ext === '.h' || ext === '.hpp' || ext === '.cs' || ext === '.php' || ext === '.rb' || ext === '.sh' || ext === '.bash' || ext === '.zsh' || ext === '.ps1' || ext === '.sql' || ext === '.toml' || ext === '.ini' || ext === '.env') return 'text/plain; charset=utf-8'
  if (ext === '.pdf') return 'application/pdf'
  if (ext === '.doc') return 'application/msword'
  if (ext === '.docx') return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  if (ext === '.rtf') return 'application/rtf'
  if (ext === '.ppt') return 'application/vnd.ms-powerpoint'
  if (ext === '.pptx') return 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
  if (ext === '.xls') return 'application/vnd.ms-excel'
  if (ext === '.xlsx') return 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  if (ext === '.mp3') return 'audio/mpeg'
  if (ext === '.wav') return 'audio/wav'
  if (ext === '.m4a') return 'audio/mp4'
  if (ext === '.aac') return 'audio/aac'
  if (ext === '.ogg' || ext === '.oga') return 'audio/ogg'
  if (ext === '.flac') return 'audio/flac'
  if (ext === '.opus') return 'audio/opus'
  if (ext === '.ico') return 'image/x-icon'
  if (ext === '.png') return 'image/png'
  if (ext === '.jpg' || ext === '.jpeg') return 'image/jpeg'
  if (ext === '.webp') return 'image/webp'
  if (ext === '.gif') return 'image/gif'
  if (ext === '.svg') return 'image/svg+xml'
  if (ext === '.woff') return 'font/woff'
  if (ext === '.woff2') return 'font/woff2'
  if (ext === '.ttf') return 'font/ttf'
  return 'application/octet-stream'
}

type CommandConsoleUploadAttachment = {
  id: string
  name: string
  path: string
  mimeType: string
  size: number
  kind: 'image' | 'file'
}

function normalizeMimeType(value: string | undefined) {
  return (value || '').split(';', 1)[0].trim().toLowerCase()
}

function commandConsoleUploadFileName(rawName: string | undefined, mimeType: string) {
  const cleanName = path.basename((rawName || 'attachment').trim() || 'attachment')
    .replace(/[\r\n]/g, ' ')
    .slice(0, 180)
  const extFromName = path.extname(cleanName).toLowerCase()
  const ext = COMMAND_CONSOLE_UPLOAD_EXTENSIONS.has(extFromName)
    ? extFromName
    : COMMAND_CONSOLE_UPLOAD_MIME_EXTENSIONS[mimeType] || ''
  if (!ext) {
    throw new Error('Choose a supported image, audio, PDF, Office document, spreadsheet, presentation, text, code, or data file.')
  }
  const stem = path.basename(cleanName, extFromName || ext)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 72) || 'attachment'
  return `${stem}${ext}`
}

async function persistCommandConsoleUpload(bytes: Buffer, sourceName: string | undefined, rawMimeType: string | undefined): Promise<CommandConsoleUploadAttachment> {
  const mimeType = normalizeMimeType(rawMimeType) || 'application/octet-stream'
  if (!Buffer.isBuffer(bytes) || bytes.length === 0) throw new Error('Choose a file to upload.')
  if (bytes.length > COMMAND_CONSOLE_UPLOAD_LIMIT_BYTES) throw new Error('Choose a file smaller than 25 MB.')
  const safeName = commandConsoleUploadFileName(sourceName, mimeType)
  const ext = path.extname(safeName).toLowerCase()
  const resolvedMimeType = mimeType === 'application/octet-stream' ? normalizeMimeType(contentTypeFromExt(safeName)) : mimeType
  const kind = COMMAND_CONSOLE_IMAGE_ATTACHMENT_MIME_TYPES.has(resolvedMimeType) ? 'image' : 'file'
  const digest = createHash('sha256').update(bytes).digest('hex').slice(0, 16)
  const uploadId = randomUUID()
  const uploadPath = path.join(COMMAND_CONSOLE_UPLOADS_DIR, `${Date.now().toString(36)}-${digest}-${safeName}`)
  const resolvedUploadDir = path.resolve(COMMAND_CONSOLE_UPLOADS_DIR)
  const resolvedUploadPath = path.resolve(uploadPath)
  if (!isPathUnder(resolvedUploadDir, resolvedUploadPath)) throw new Error('Upload path resolved outside the upload directory.')
  await fs.mkdir(resolvedUploadDir, { recursive: true })
  await fs.writeFile(resolvedUploadPath, bytes)
  return {
    id: uploadId,
    name: safeName,
    path: resolvedUploadPath,
    mimeType: resolvedMimeType || COMMAND_CONSOLE_UPLOAD_MIME_EXTENSIONS[ext] || 'application/octet-stream',
    size: bytes.length,
    kind,
  }
}

function normalizeCommandConsoleAttachment(value: unknown): CommandConsoleUploadAttachment | null {
  if (!isLooseRecord(value)) return null
  const id = typeof value.id === 'string' ? value.id.trim() : ''
  const name = typeof value.name === 'string' ? value.name.trim() : ''
  const filePath = typeof value.path === 'string' ? value.path.trim() : ''
  const mimeType = normalizeMimeType(typeof value.mimeType === 'string' ? value.mimeType : '')
  const size = typeof value.size === 'number' && Number.isFinite(value.size) ? Math.max(0, Math.floor(value.size)) : 0
  const kind = value.kind === 'image' ? 'image' : 'file'
  if (!id || !name || !filePath || !mimeType || size <= 0) return null
  const resolvedUploadDir = path.resolve(COMMAND_CONSOLE_UPLOADS_DIR)
  const resolvedPath = path.resolve(filePath)
  if (!isPathUnder(resolvedUploadDir, resolvedPath)) return null
  return { id, name, path: resolvedPath, mimeType, size, kind }
}

async function gatewayChatAttachmentsFromTurnAttachments(attachments: unknown[] | undefined) {
  const normalized = (attachments || []).map(normalizeCommandConsoleAttachment).filter((entry): entry is CommandConsoleUploadAttachment => Boolean(entry))
  const gatewayAttachments: Record<string, unknown>[] = []
  for (const attachment of normalized) {
    const bytes = await fs.readFile(attachment.path)
    const inlineLimit = attachment.kind === 'image'
      ? COMMAND_CONSOLE_GATEWAY_IMAGE_LIMIT_BYTES
      : COMMAND_CONSOLE_GATEWAY_ATTACHMENT_LIMIT_BYTES
    if (bytes.length > inlineLimit) continue
    gatewayAttachments.push({
      type: attachment.kind === 'image' ? 'image' : 'file',
      mimeType: attachment.mimeType,
      fileName: attachment.name,
      content: bytes.toString('base64'),
      name: attachment.name,
    })
  }
  return gatewayAttachments
}

function clampStat(value: number | undefined) {
  if (!Number.isFinite(value)) return 50
  return Math.min(99, Math.max(1, Math.round(value as number)))
}

function isAgentBehaviorProfile(value: unknown): value is AgentBehaviorProfile {
  return typeof value === 'string' && (AGENT_BEHAVIOR_PROFILES as readonly string[]).includes(value)
}

function sanitizeProfile(profile: PartialAgentProfileInput): AgentProfile {
  return {
    skills: normalizeAgentSkillList(profile.skills, 50),
    abilities: Array.isArray(profile.abilities) ? profile.abilities.filter(Boolean).slice(0, 20) : [],
    tools: Array.isArray(profile.tools) ? profile.tools.filter(Boolean).slice(0, 20) : [],
    behaviorProfile: isAgentBehaviorProfile(profile.behaviorProfile) ? profile.behaviorProfile : 'hybrid',
    className: (profile.className || '').trim().slice(0, 60),
    role: (profile.role || '').trim().slice(0, 60),
    motto: (profile.motto || '').trim().slice(0, 140),
    bio: (profile.bio || '').trim().slice(0, 800),
    avatar: profile.avatar?.trim().slice(0, 500),
    level: Math.min(99, Math.max(1, Math.round(profile.level || 1))),
    stats: {
      execution: clampStat(profile.stats?.execution),
      reliability: clampStat(profile.stats?.reliability),
      speed: clampStat(profile.stats?.speed),
      analysis: clampStat(profile.stats?.analysis),
      communication: clampStat(profile.stats?.communication),
    },
  }
}

function recruitCapabilitiesFromProfile(profile: AgentProfile): AgentLocalConfig['mds']['capabilities'] {
  const abilities = new Set(profile.abilities)
  const tools = new Set(profile.tools)
  const hasAbilities = profile.abilities.length > 0
  return {
    codeGeneration: abilities.has('codeGeneration') || (!hasAbilities && (tools.has('shell') || tools.has('filesystem'))),
    planning: abilities.has('planning') || (!hasAbilities && tools.has('planner')),
    research: abilities.has('research') || (!hasAbilities && (tools.has('web_search') || tools.has('web_fetch'))),
    orchestration: abilities.has('orchestration') || (!hasAbilities && profile.behaviorProfile === 'architect'),
    memoryManagement: abilities.has('memoryManagement') || (!hasAbilities && tools.has('memory')),
  }
}

function recruitAttributesFromProfile(profile: AgentProfile): AgentLocalConfig['attributes'] {
  const stats = profile.stats
  return {
    intelligence: clampStat(stats.analysis),
    speed: clampStat(stats.speed),
    precision: clampStat(stats.reliability),
    creativity: clampStat(Math.round((stats.analysis + stats.communication) / 2)),
    stability: clampStat(stats.reliability),
    compute: clampStat(stats.execution),
    parallelism: clampStat(stats.communication),
  }
}

function recruitRuntimeDefaults(): AgentLocalConfig['runtime'] {
  return {
    thinkingDefault: 'off',
    timeoutSeconds: 90,
    parallelPreferred: true,
  }
}

function recruitHeartbeatDefaults(): AgentLocalConfig['heartbeat'] {
  return {
    tickIntervalMs: 4200,
    maxExecutionTimeMs: null,
    continuous: false,
    idleTimeoutMs: 45000,
    recoveryMode: true,
  }
}

function recruitSoulDefaults(behaviorProfile: AgentBehaviorProfile): AgentLocalConfig['soul'] {
  if (behaviorProfile === 'architect') {
    return { personality: 'analytical', autonomyLevel: 78, riskTolerance: 34, reflectionDepth: 88, goalOrientation: 86, persistence: 78, alignmentMode: 'strict' }
  }
  if (behaviorProfile === 'auditor') {
    return { personality: 'conservative', autonomyLevel: 70, riskTolerance: 22, reflectionDepth: 92, goalOrientation: 80, persistence: 86, alignmentMode: 'strict' }
  }
  if (behaviorProfile === 'researcher') {
    return { personality: 'analytical', autonomyLevel: 76, riskTolerance: 38, reflectionDepth: 90, goalOrientation: 78, persistence: 76, alignmentMode: 'exploratory' }
  }
  if (behaviorProfile === 'hybrid') {
    return { personality: 'creative', autonomyLevel: 80, riskTolerance: 48, reflectionDepth: 76, goalOrientation: 82, persistence: 80, alignmentMode: 'balanced' }
  }
  return { personality: 'aggressive', autonomyLevel: 82, riskTolerance: 56, reflectionDepth: 58, goalOrientation: 88, persistence: 84, alignmentMode: 'balanced' }
}

function recruitMdsDefaults(profile: AgentProfile): AgentLocalConfig['mds'] {
  const capabilities = recruitCapabilitiesFromProfile(profile)
  const toolAccess = profile.tools.length ? profile.tools : ['filesystem', 'message', 'planner', 'memory']
  return {
    maxContextTokens: 32000,
    delegationAllowed: true,
    subAgentSpawnLimit: capabilities.orchestration ? 4 : 2,
    toolAccess,
    capabilities,
  }
}

type AgentMdsPatch = Partial<Omit<AgentLocalConfig['mds'], 'capabilities' | 'skillLibrary'>> & {
  capabilities?: Partial<AgentLocalConfig['mds']['capabilities']>
  skillLibrary?: Partial<AgentSkillLibraryState>
}

function normalizeAgentMdsState(base: AgentLocalConfig['mds'], patch?: AgentMdsPatch): AgentLocalConfig['mds'] {
  const capabilities = patch?.capabilities
  const toolAccess = patch?.toolAccess
  const scalarPatch: Partial<Omit<AgentLocalConfig['mds'], 'capabilities' | 'skillLibrary' | 'toolAccess'>> = {
    ...(patch?.maxContextTokens !== undefined ? { maxContextTokens: patch.maxContextTokens } : {}),
    ...(patch?.delegationAllowed !== undefined ? { delegationAllowed: patch.delegationAllowed } : {}),
    ...(patch?.subAgentSpawnLimit !== undefined ? { subAgentSpawnLimit: patch.subAgentSpawnLimit } : {}),
  }
  const skillLibraryPatch = patch?.skillLibrary
  const existingSkillLibrary = base.skillLibrary
  const skillLibrary = skillLibraryPatch || existingSkillLibrary

  return {
    ...base,
    ...scalarPatch,
    capabilities: {
      ...base.capabilities,
      ...(capabilities || {}),
    },
    toolAccess: toolAccess?.length ? toolAccess : base.toolAccess,
    ...(skillLibrary
      ? {
          skillLibrary: {
            knownSkills: skillLibraryPatch?.knownSkills || existingSkillLibrary?.knownSkills || [],
            preferredSkills: skillLibraryPatch?.preferredSkills || existingSkillLibrary?.preferredSkills || [],
            ...(skillLibraryPatch?.lastSyncedAt || existingSkillLibrary?.lastSyncedAt
              ? { lastSyncedAt: skillLibraryPatch?.lastSyncedAt || existingSkillLibrary?.lastSyncedAt }
              : {}),
          },
        }
      : {}),
  }
}

function isLegacyGenericRecruitRuntime(value?: Partial<AgentLocalConfig['runtime']>) {
  if (!value) return false
  return value.thinkingDefault === 'medium'
    && value.timeoutSeconds === 900
    && (value.parallelPreferred === undefined || value.parallelPreferred === true)
}

function isLegacyGenericRecruitHeartbeat(value?: Partial<AgentLocalConfig['heartbeat']>) {
  if (!value) return false
  return value.tickIntervalMs === 3000
    && value.maxExecutionTimeMs === 900000
    && value.continuous === true
    && value.idleTimeoutMs === 180000
    && value.recoveryMode === true
}

function isLegacyGenericRecruitSoul(value?: Partial<AgentLocalConfig['soul']>) {
  if (!value) return false
  return value.personality === 'analytical'
    && value.autonomyLevel === 72
    && value.riskTolerance === 48
    && value.reflectionDepth === 62
    && value.goalOrientation === 84
    && value.persistence === 88
    && value.alignmentMode === 'balanced'
}

function isLegacyGenericRecruitAttributes(value?: Partial<AgentLocalConfig['attributes']>) {
  if (!value) return false
  return value.intelligence === 80
    && value.speed === 80
    && value.precision === 80
    && value.creativity === 80
    && value.stability === 80
    && value.compute === 80
    && value.parallelism === 4
}

function isLegacyGenericRecruitMds(value: AgentMdsPatch | undefined, inferred: AgentLocalConfig['mds']) {
  if (!value) return false
  const caps: Partial<AgentLocalConfig['mds']['capabilities']> = value.capabilities || {}
  const allCapabilitiesOn =
    caps.codeGeneration === true
    && caps.planning === true
    && caps.research === true
    && caps.orchestration === true
    && caps.memoryManagement === true
  const lacksToolAccess = !Array.isArray(value.toolAccess) || value.toolAccess.length === 0
  const conflictsWithProfile = Object.entries(inferred.capabilities).some(([, enabled]) => enabled !== true) || inferred.toolAccess.length > 0
  return Boolean(
    allCapabilitiesOn
      && lacksToolAccess
      && conflictsWithProfile
      && (value.maxContextTokens ?? 0) >= 128000
      && (value.subAgentSpawnLimit ?? 0) >= 8,
  )
}

function normalizeStringList(values?: string[]) {
  const output = Array.from(new Set((values || []).map((value) => value?.trim()).filter(Boolean)))
  return output.length ? output : undefined
}

function normalizeAgentSkillList(values?: string[], limit = 100) {
  return Array.from(
    new Set((values || []).map((value) => String(value || '').trim()).filter(Boolean)),
  ).slice(0, limit)
}

function skillSelectionKey(value: string) {
  return value.trim().toLowerCase()
}

function resolveOpenClawAgentSkillFilter(local: AgentLocalConfig) {
  const selected = normalizeAgentSkillList(local.profile?.skills, 100)
  if (!selected.length) return [] as string[]

  const selectedKeys = new Set(selected.map(skillSelectionKey))
  const output = new Set<string>(selected)
  for (const skill of local.mds?.skillLibrary?.knownSkills || []) {
    const id = skill.id?.trim()
    const name = skill.name?.trim()
    if (
      (id && selectedKeys.has(skillSelectionKey(id))) ||
      (name && selectedKeys.has(skillSelectionKey(name)))
    ) {
      if (name) output.add(name)
      if (id) output.add(id)
    }
  }
  return Array.from(output).slice(0, 100)
}

function normalizeToolProfile(profile?: string) {
  const value = profile?.trim().toLowerCase()
  if (!value) return undefined
  const canonical = LEGACY_TOOL_PROFILE_ALIASES[value] || value
  return OPENCLAW_TOOL_PROFILES.has(canonical) ? canonical : undefined
}

function normalizeSandboxConfig(input?: AgentSandboxConfig): AgentSandboxConfig {
  const mode = input?.mode && ['off', 'all', 'non-main'].includes(input.mode) ? input.mode : undefined
  const scope = input?.scope && ['session', 'agent', 'shared'].includes(input.scope) ? input.scope : undefined
  const workspaceAccess =
    input?.workspaceAccess && ['rw', 'ro', 'none'].includes(input.workspaceAccess) ? input.workspaceAccess : undefined
  const workspaceRoot = resolveWorkspacePath(input?.workspaceRoot)
  return {
    ...(mode ? { mode } : {}),
    ...(scope ? { scope } : {}),
    ...(workspaceRoot ? { workspaceRoot: path.resolve(workspaceRoot) } : {}),
    ...(workspaceAccess ? { workspaceAccess } : {}),
    ...(input?.docker ? { docker: input.docker } : {}),
    ...(input?.browser ? { browser: input.browser } : {}),
    ...(input?.prune ? { prune: input.prune } : {}),
  }
}

let dockerAvailabilityCache: { checkedAt: number; available: boolean } | null = null

function isDockerCliAvailable() {
  const now = Date.now()
  if (dockerAvailabilityCache && now - dockerAvailabilityCache.checkedAt < 30_000) {
    return dockerAvailabilityCache.available
  }

  const result = spawnSync('docker', ['--version'], {
    cwd: WORKSPACE_ROOT,
    env: process.env,
    shell: false,
    stdio: 'ignore',
    timeout: 2500,
    ...(process.platform === 'win32' ? { windowsHide: true } : {}),
  })
  const available = !result.error && result.status === 0
  dockerAvailabilityCache = { checkedAt: now, available }
  return available
}

function sandboxRequiresDocker(sandbox?: AgentSandboxConfig) {
  return Boolean(sandbox?.mode && sandbox.mode !== 'off')
}

function dockerUnavailableSandboxMessage(agentId: string) {
  return `Agent ${agentId} requested sandboxed execution, but Docker is not available on this machine. Sandbox mode was switched off for embedded OpenClaw runtime execution.`
}

function normalizeAgentToolsConfig(input?: AgentToolsConfig): AgentToolsConfig {
  const byProvider = Object.fromEntries(
    Object.entries(input?.byProvider || {})
      .map(([provider, policy]) => {
        const key = provider.trim()
        if (!key) return null
        const normalized: ProviderToolPolicy = {
          ...(normalizeToolProfile(policy.profile) ? { profile: normalizeToolProfile(policy.profile) } : {}),
          ...(normalizeStringList(policy.allow) ? { allow: normalizeStringList(policy.allow) } : {}),
          ...(normalizeStringList(policy.deny) ? { deny: normalizeStringList(policy.deny) } : {}),
        }
        return Object.keys(normalized).length ? [key, normalized] : null
      })
      .filter((entry): entry is [string, ProviderToolPolicy] => Boolean(entry)),
  )

  return {
    ...(normalizeToolProfile(input?.profile) ? { profile: normalizeToolProfile(input?.profile) } : {}),
    ...(normalizeStringList(input?.alsoAllow) ? { alsoAllow: normalizeStringList(input?.alsoAllow) } : {}),
    ...(normalizeStringList(input?.allow) ? { allow: normalizeStringList(input?.allow) } : {}),
    ...(normalizeStringList(input?.deny) ? { deny: normalizeStringList(input?.deny) } : {}),
    ...(Object.keys(byProvider).length ? { byProvider } : {}),
    ...(input?.sandbox?.tools
      ? {
          sandbox: {
            tools: {
              ...(normalizeStringList(input.sandbox.tools.allow) ? { allow: normalizeStringList(input.sandbox.tools.allow) } : {}),
              ...(normalizeStringList(input.sandbox.tools.deny) ? { deny: normalizeStringList(input.sandbox.tools.deny) } : {}),
            },
          },
        }
      : {}),
    ...(typeof input?.elevated?.enabled === 'boolean' ? { elevated: { enabled: input.elevated.enabled } } : {}),
  }
}

function applyExecutionWorkspaceToLocalConfig(local: AgentLocalConfig, workspacePath: string) {
  const workspace = normalizeExecutionWorkspacePath(path.resolve(workspacePath || defaultAgentWorkspace(local.agent.id)))
  local.routing.workspace = workspace
  local.identity.avatar = configSafeAgentAvatar(local.identity.avatar, workspace)
  local.memory = {
    ...(local.memory || { retentionDays: 180 }),
    journalDir: path.join(workspace, 'memory'),
    retentionDays: local.memory?.retentionDays ?? 180,
  }
  local.sandbox = normalizeSandboxConfig({
    ...local.sandbox,
    workspaceRoot: workspace,
  })
  return workspace
}

type AgentRuntimeFlagMode = 'default' | 'gateway' | 'local'

function withAgentRuntimeFlags(args: string[], options: { mode?: AgentRuntimeFlagMode } = {}) {
  if (!args.length || args[0] !== 'agent') return args
  const mode = options.mode || 'default'
  if (mode === 'gateway') return args.filter((arg) => arg !== '--local')
  if (mode !== 'local' && !FORCE_LOCAL_AGENT_RUNTIME) return args
  if (args.includes('--local')) return args
  return ['agent', '--local', ...args.slice(1)]
}

function openClawJsonHasReply(value: unknown): boolean {
  if (!value || typeof value !== 'object') return false
  const record = value as {
    payloads?: Array<{ text?: unknown; isError?: unknown }>
    result?: { payloads?: Array<{ text?: unknown; isError?: unknown }> }
    payload?: { text?: unknown }
    text?: unknown
    message?: unknown
    content?: unknown
    summary?: unknown
    status?: unknown
    ok?: unknown
  }
  if (record.ok === false || record.status === 'error') return false
  const payloads = [...(record.payloads || []), ...(record.result?.payloads || [])]
  if (payloads.some((payload) => !payload.isError && typeof payload.text === 'string' && payload.text.trim())) return true
  return [record.payload?.text, record.text, record.message, record.content, record.summary].some(
    (entry) => typeof entry === 'string' && entry.trim().length > 0,
  )
}

function stdoutHasOpenClawReply(stdout: string) {
  const trimmed = stdout.trim()
  if (!trimmed) return false
  try {
    if (openClawJsonHasReply(JSON.parse(trimmed))) return true
  } catch {
    // Try JSON-lines or a final JSON object mixed with logs.
  }
  for (const line of trimmed.split(/\r?\n/).map((entry) => entry.trim()).filter(Boolean).reverse()) {
    try {
      if (openClawJsonHasReply(JSON.parse(line.replace(/,$/, '')))) return true
    } catch {
      // keep scanning
    }
  }
  return false
}

function resolveOpenClawTimeoutResult(stdout: string, stderr: string, timeoutMs: number) {
  const trimmedOut = stdout.trim()
  const trimmedErr = stderr.trim()
  const timeoutMessage = `openclaw child process exceeded wrapper timeout after ${timeoutMs}ms`
  if (stdoutHasOpenClawReply(trimmedOut)) {
    return {
      stdout: trimmedOut,
      stderr: [trimmedErr, timeoutMessage].filter(Boolean).join('\n'),
      code: 0,
    }
  }
  return {
    stdout: trimmedOut,
    stderr: [trimmedErr, `Error: openclaw timed out after ${timeoutMs}ms`].filter(Boolean).join('\n'),
    code: 124,
  }
}

function argValue(args: string[], flag: string) {
  const index = args.indexOf(flag)
  const value = index >= 0 ? args[index + 1] : ''
  return typeof value === 'string' ? value.trim() : ''
}

function isSafeSessionId(value: string) {
  return /^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,127}$/.test(value) && !value.includes('..')
}

function isPidAlive(pid: number) {
  if (!Number.isInteger(pid) || pid <= 0) return false
  try {
    process.kill(pid, 0)
    return true
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM'
  }
}

type OpenClawSessionLockStaleReason =
  | 'missing-pid'
  | 'dead-pid'
  | 'invalid-createdAt'
  | 'too-old'
  | 'hold-exceeded'
  | 'non-openclaw-owner'

type OpenClawSessionLockInspection = {
  agentId: string
  sessionId: string
  lockPath: string
  pid: number | null
  ownerAlive: boolean | null
  ageMs: number | null
  mtimeAgeMs: number
  staleReasons: OpenClawSessionLockStaleReason[]
  removed: boolean
}

type OpenClawSessionLockStatus = {
  lockPath: string
  pid: number | null
  ownerAlive: boolean | null
  ageMs: number | null
  mtimeAgeMs: number
  staleReasons: OpenClawSessionLockStaleReason[]
  stale: boolean
  removable: boolean
}

type OpenClawSessionLockCleanupResult = {
  scanned: number
  removed: OpenClawSessionLockInspection[]
  skipped?: boolean
  errors: string[]
}

let openClawSessionLockSweepInFlight: Promise<OpenClawSessionLockCleanupResult> | null = null
let openClawSessionLockLastSweepAt = 0

function isValidLockNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0
}

function positiveLockNumber(value: unknown) {
  return isValidLockNumber(value) ? value : null
}

function resolveOpenClawSessionWriteLockStaleMs() {
  const raw = process.env.OPENCLAW_SESSION_WRITE_LOCK_STALE_MS?.trim()
  if (raw && /^\d+$/.test(raw)) {
    const parsed = Number(raw)
    if (Number.isSafeInteger(parsed) && parsed > 0) return parsed
  }
  return OPENCLAW_SESSION_WRITE_LOCK_STALE_MS
}

function isOpenClawSessionOwnerCommandLine(commandLine: string) {
  const normalized = commandLine.replace(/\\/g, '/').toLowerCase()
  if (/(^|[\s"'])(openclaw(?:\.mjs|\.cmd|\.bat|\.exe)?|openclaw-gateway(?:\.mjs|\.cmd|\.exe)?)(?=$|[\s"'])/.test(normalized)) {
    return true
  }
  if (normalized.includes('/openclaw.mjs') || normalized.includes('/openclaw.cmd')) return true
  const hasRuntimeCommand = /(^|[\s"'])(agent|gateway)(?=$|[\s"'])/.test(normalized)
  if (!hasRuntimeCommand) return false
  return normalized.includes('/vendor/openclaw/')
    || normalized.includes('/resources/openclaw/')
    || normalized.includes('/openclaw/dist/')
    || normalized.includes('/openclaw/src/')
    || normalized.includes('/openclaw/openclaw.mjs')
}

async function readProcessCommandLine(pid: number) {
  if (!Number.isInteger(pid) || pid <= 0) return null
  const result = process.platform === 'win32'
    ? await spawnText('powershell.exe', [
        '-NoProfile',
        '-NonInteractive',
        '-Command',
        `$p = Get-CimInstance Win32_Process -Filter "ProcessId = ${pid}" -ErrorAction SilentlyContinue; if ($p) { $p.CommandLine }`,
      ], {
        windowsHide: true,
        timeoutMs: 2500,
      })
    : await spawnText('ps', ['-p', String(pid), '-o', 'args='], {
        timeoutMs: 2500,
      })
  const output = stripAnsi(`${result.stdout || ''}\n${result.stderr || ''}`).trim()
  if (result.timedOut || result.code !== 0 || !output) return null
  return output
}

function sessionLockShouldWaitForOrphanPayloadGrace(inspection: OpenClawSessionLockInspection) {
  return inspection.staleReasons.length > 0
    && inspection.staleReasons.every((reason) => reason === 'missing-pid' || reason === 'invalid-createdAt' || reason === 'too-old')
}

function shouldRemoveOpenClawSessionLock(inspection: OpenClawSessionLockInspection, minAgeMs: number) {
  if (!inspection.staleReasons.length) return false
  if (inspection.mtimeAgeMs < minAgeMs) return false
  if (inspection.staleReasons.every((reason) => OPENCLAW_SESSION_LOCK_REPORT_ONLY_REASONS.has(reason))) return false
  if (sessionLockShouldWaitForOrphanPayloadGrace(inspection) && inspection.mtimeAgeMs < OPENCLAW_SESSION_LOCK_ORPHAN_GRACE_MS) return false
  return true
}

async function inspectOpenClawSessionLock(
  params: {
    agentId: string
    lockPath: string
    sessionId: string
    stat: Awaited<ReturnType<typeof fs.stat>>
    staleMs: number
    ownerCommandLines: Map<number, Promise<string | null>>
  },
): Promise<OpenClawSessionLockInspection> {
  const nowMs = Date.now()
  const raw = await fs.readFile(params.lockPath, 'utf-8').catch(() => '')
  let payload: Record<string, unknown> | null = null
  try {
    const parsed = raw.trim() ? JSON.parse(raw) as unknown : null
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) payload = parsed as Record<string, unknown>
  } catch {
    payload = null
  }

  const pid = payload ? positiveLockNumber(payload.pid) : null
  const createdAt = typeof payload?.createdAt === 'string' ? payload.createdAt : ''
  const createdAtMs = createdAt ? Date.parse(createdAt) : NaN
  const ageMs = Number.isFinite(createdAtMs) ? Math.max(0, nowMs - createdAtMs) : null
  const mtimeAgeMs = Math.max(0, nowMs - Number(params.stat.mtimeMs))
  const maxHoldMs = payload ? positiveLockNumber(payload.maxHoldMs) : null
  const staleReasons: OpenClawSessionLockStaleReason[] = []
  let ownerAlive: boolean | null = null

  if (pid === null || pid <= 0) {
    ownerAlive = null
    staleReasons.push('missing-pid')
  } else if (!isPidAlive(pid)) {
    ownerAlive = false
    staleReasons.push('dead-pid')
  } else {
    ownerAlive = true
    let commandLinePromise = params.ownerCommandLines.get(pid)
    if (!commandLinePromise) {
      commandLinePromise = readProcessCommandLine(pid)
      params.ownerCommandLines.set(pid, commandLinePromise)
    }
    const commandLine = await commandLinePromise
    if (commandLine?.trim() && !isOpenClawSessionOwnerCommandLine(commandLine)) {
      staleReasons.push('non-openclaw-owner')
    }
  }

  if (ageMs === null) {
    staleReasons.push('invalid-createdAt')
  } else {
    if (ageMs > params.staleMs) staleReasons.push('too-old')
    if (typeof maxHoldMs === 'number' && maxHoldMs > 0 && ageMs > maxHoldMs) staleReasons.push('hold-exceeded')
  }

  return {
    agentId: params.agentId,
    sessionId: params.sessionId,
    lockPath: params.lockPath,
    pid: pid && pid > 0 ? pid : null,
    ownerAlive,
    ageMs,
    mtimeAgeMs,
    staleReasons,
    removed: false,
  }
}

async function listOpenClawAgentIdsForLockCleanup(agentId?: string) {
  if (agentId) return isValidAgentId(agentId) ? [agentId] : []
  const entries = await fs.readdir(OPENCLAW_AGENTS_ROOT, { withFileTypes: true }).catch(() => [])
  return entries
    .filter((entry) => entry.isDirectory() && isValidAgentId(entry.name))
    .map((entry) => entry.name)
}

function openClawSessionLockSummary(locks: OpenClawSessionLockInspection[]) {
  const preview = locks
    .slice(0, 4)
    .map((lock) => `${lock.agentId}/${lock.sessionId.slice(0, 8)} (${lock.staleReasons.join(', ') || 'stale'})`)
    .join('; ')
  return locks.length > 4 ? `${preview}; +${locks.length - 4} more` : preview
}

function openClawSessionLockStatus(inspection: OpenClawSessionLockInspection): OpenClawSessionLockStatus {
  return {
    lockPath: inspection.lockPath,
    pid: inspection.pid,
    ownerAlive: inspection.ownerAlive,
    ageMs: inspection.ageMs,
    mtimeAgeMs: inspection.mtimeAgeMs,
    staleReasons: inspection.staleReasons,
    stale: inspection.staleReasons.length > 0,
    removable: shouldRemoveOpenClawSessionLock(inspection, 0),
  }
}

async function inspectOpenClawSessionLocks(
  options: {
    agentId?: string
    sessionId?: string
    all?: boolean
  } = {},
): Promise<{ scanned: number; locks: OpenClawSessionLockInspection[]; errors: string[] }> {
  const result: { scanned: number; locks: OpenClawSessionLockInspection[]; errors: string[] } = { scanned: 0, locks: [], errors: [] }
  const staleMs = resolveOpenClawSessionWriteLockStaleMs()
  const ownerCommandLines = new Map<number, Promise<string | null>>()
  const agentIds = await listOpenClawAgentIdsForLockCleanup(options.all ? undefined : options.agentId)
  const sessionIdFilter = options.sessionId && isSafeSessionId(options.sessionId) ? options.sessionId : ''

  for (const agentId of agentIds) {
    const sessionDir = path.join(OPENCLAW_AGENTS_ROOT, agentId, 'sessions')
    let lockNames: string[] = []
    try {
      if (sessionIdFilter) {
        lockNames = [`${sessionIdFilter}.jsonl.lock`]
      } else {
        const entries = await fs.readdir(sessionDir, { withFileTypes: true }).catch(() => [])
        lockNames = entries
          .filter((entry) => entry.isFile() && entry.name.endsWith('.jsonl.lock'))
          .map((entry) => entry.name)
      }

      for (const name of lockNames) {
        const lockSessionId = name.replace(/\.jsonl\.lock$/u, '')
        if (!isSafeSessionId(lockSessionId)) continue
        const lockPath = path.join(sessionDir, name)
        const stat = await fs.stat(lockPath).catch(() => null)
        if (!stat) continue
        const inspection = await inspectOpenClawSessionLock({
          agentId,
          sessionId: lockSessionId,
          lockPath,
          stat,
          staleMs,
          ownerCommandLines,
        })
        result.scanned += 1
        result.locks.push(inspection)
      }
    } catch (error) {
      result.errors.push(`${agentId}: ${String(error)}`)
    }
  }

  return result
}

async function cleanupOpenClawSessionLocks(
  options: {
    agentId?: string
    sessionId?: string
    all?: boolean
    minAgeMs?: number
    reason?: string
    quiet?: boolean
  } = {},
): Promise<OpenClawSessionLockCleanupResult> {
  const result: OpenClawSessionLockCleanupResult = { scanned: 0, removed: [], errors: [] }
  const minAgeMs = options.minAgeMs ?? OPENCLAW_STALE_LOCK_MIN_AGE_MS
  const staleMs = resolveOpenClawSessionWriteLockStaleMs()
  const ownerCommandLines = new Map<number, Promise<string | null>>()
  const agentIds = await listOpenClawAgentIdsForLockCleanup(options.all ? undefined : options.agentId)
  const sessionIdFilter = options.sessionId && isSafeSessionId(options.sessionId) ? options.sessionId : ''

  for (const agentId of agentIds) {
    const sessionDir = path.join(OPENCLAW_AGENTS_ROOT, agentId, 'sessions')
    let lockNames: string[] = []
    try {
      if (sessionIdFilter) {
        lockNames = [`${sessionIdFilter}.jsonl.lock`]
      } else {
        const entries = await fs.readdir(sessionDir, { withFileTypes: true }).catch(() => [])
        lockNames = entries
          .filter((entry) => entry.isFile() && entry.name.endsWith('.jsonl.lock'))
          .map((entry) => entry.name)
      }

      for (const name of lockNames) {
        const lockSessionId = name.replace(/\.jsonl\.lock$/u, '')
        if (!isSafeSessionId(lockSessionId)) continue
        const lockPath = path.join(sessionDir, name)
        const stat = await fs.stat(lockPath).catch(() => null)
        if (!stat) continue
        const inspection = await inspectOpenClawSessionLock({
          agentId,
          sessionId: lockSessionId,
          lockPath,
          stat,
          staleMs,
          ownerCommandLines,
        })
        result.scanned += 1
        if (!shouldRemoveOpenClawSessionLock(inspection, minAgeMs)) continue
        await fs.rm(lockPath, { force: true })
        inspection.removed = true
        result.removed.push(inspection)
      }
    } catch (error) {
      result.errors.push(`${agentId}: ${String(error)}`)
    }
  }

  if (result.removed.length && !options.quiet) {
    const reason = options.reason || 'runtime maintenance'
    pushGatewayLog('lifecycle', `session lock cleanup (${reason}) reclaimed ${result.removed.length} orphaned lock file(s): ${openClawSessionLockSummary(result.removed)}`)
  }
  if (result.errors.length && !options.quiet) {
    pushGatewayLog('lifecycle', `session lock cleanup skipped ${result.errors.length} agent folder(s): ${result.errors.slice(0, 3).join('; ')}`)
  }
  return result
}

async function sweepOpenClawSessionLocks(
  reason: string,
  options: { minIntervalMs?: number; minAgeMs?: number; quiet?: boolean } = {},
) {
  const minIntervalMs = options.minIntervalMs ?? OPENCLAW_SESSION_LOCK_SWEEP_INTERVAL_MS
  const now = Date.now()
  if (openClawSessionLockSweepInFlight) return openClawSessionLockSweepInFlight
  if (minIntervalMs > 0 && openClawSessionLockLastSweepAt && now - openClawSessionLockLastSweepAt < minIntervalMs) {
    return { scanned: 0, removed: [], errors: [], skipped: true } satisfies OpenClawSessionLockCleanupResult
  }
  openClawSessionLockLastSweepAt = now
  openClawSessionLockSweepInFlight = cleanupOpenClawSessionLocks({
    all: true,
    minAgeMs: options.minAgeMs ?? 0,
    reason,
    quiet: options.quiet,
  }).finally(() => {
    openClawSessionLockSweepInFlight = null
  })
  return openClawSessionLockSweepInFlight
}

function scheduleOpenClawSessionLockSweep(reason: string, delayMs = 1500) {
  const timeout = setTimeout(() => {
    void sweepOpenClawSessionLocks(reason, { minIntervalMs: 0, minAgeMs: 0 })
  }, delayMs)
  timeout.unref?.()
}

async function cleanupStaleOpenClawSessionLocksForArgs(
  args: string[],
  options: { minAgeMs?: number; onlyCurrentSession?: boolean } = {},
) {
  if (args[0] !== 'agent') return
  const agentId = argValue(args, '--agent')
  if (!isValidAgentId(agentId)) return
  const sessionId = argValue(args, '--session-id')
  await cleanupOpenClawSessionLocks({
    agentId,
    sessionId: options.onlyCurrentSession ? sessionId : undefined,
    minAgeMs: options.minAgeMs,
    reason: options.onlyCurrentSession ? 'agent run finished' : 'agent run preflight',
  })
}

function scheduleStaleOpenClawSessionLockCleanup(args: string[], delayMs = 1500) {
  const timeout = setTimeout(() => {
    void cleanupStaleOpenClawSessionLocksForArgs(args, { minAgeMs: 0, onlyCurrentSession: true })
  }, delayMs)
  timeout.unref?.()
}

type AgentRuntimePreflightCheck = {
  id: string
  label: string
  ok: boolean
  severity: 'info' | 'warning' | 'error'
  message: string
  detail?: string
}

function commandCheck(command: string, args: string[], label: string): AgentRuntimePreflightCheck {
  const spec = shelllessSpawnSpecForCommand(command, args)
  const result = spawnSync(spec.command, spec.args, {
    cwd: WORKSPACE_ROOT,
    env: openClawProcessEnv(),
    encoding: 'utf8',
    shell: spec.shell,
    timeout: 5000,
    ...(process.platform === 'win32' ? { windowsHide: true } : {}),
  })
  const output = stripAnsi(`${result.stdout || ''}\n${result.stderr || ''}\n${result.error ? String(result.error) : ''}`).trim()
  if (result.status === 0 && !result.error) {
    return {
      id: label.toLowerCase(),
      label,
      ok: true,
      severity: 'info',
      message: `${label} available${output ? ` (${output.split(/\r?\n/)[0]})` : ''}.`,
    }
  }
  return {
    id: label.toLowerCase(),
    label,
    ok: false,
    severity: 'error',
    message: `${label} is not available to the agent runtime process.`,
    detail: output || `${command} ${args.join(' ')} failed`,
  }
}

function selectedModelIdsForAgent(config: OpenClawConfigFile, agentId: string) {
  const entry = (config.agents?.list || []).find((agent) => agent.id === agentId)
  const selection = normalizeModelWithFallback(entry?.model, config.agents?.defaults?.model)
  return uniqueStrings(selection.primary, selection.fallbacks)
}

function selectedModelsUseProvider(config: OpenClawConfigFile, agentId: string, providerId: string) {
  const provider = providerId.trim().toLowerCase()
  return selectedModelIdsForAgent(config, agentId).some((modelId) =>
    splitModelId(canonicalAgentModelId(modelId)).provider.toLowerCase() === provider,
  )
}

async function pluginRuntimeCheck(pluginId: string, label: string): Promise<AgentRuntimePreflightCheck> {
  const controls = await listPluginControls({ forceRefresh: true }).catch((error) => {
    throw new Error(`Plugin list failed: ${String(error)}`)
  })
  const plugin = controls.plugins.find((entry) => entry.id === pluginId)
  if (pluginId === 'codex' && isCodexPluginAvailableForRuntime(plugin)) {
    return {
      id: `plugin:${pluginId}`,
      label,
      ok: true,
      severity: 'info',
      message: `${label} available.`,
    }
  }
  if (plugin && (plugin.enabled || plugin.runtimeLoaded || plugin.status.toLowerCase() === 'loaded')) {
    return {
      id: `plugin:${pluginId}`,
      label,
      ok: true,
      severity: 'info',
      message: `${label} available.`,
    }
  }
  return {
    id: `plugin:${pluginId}`,
    label,
    ok: false,
    severity: 'error',
    message: `${label} is required but is not installed or enabled.`,
    detail: plugin ? JSON.stringify({ status: plugin.status, enabled: plugin.enabled, origin: plugin.origin }) : 'Plugin not listed.',
  }
}

async function buildAgentRuntimePreflightChecks(agentId: string, config: OpenClawConfigFile): Promise<AgentRuntimePreflightCheck[]> {
  const checks: AgentRuntimePreflightCheck[] = [
    commandCheck(process.platform === 'win32' ? 'node.exe' : 'node', ['--version'], 'Node.js'),
    commandCheck(process.platform === 'win32' ? 'npm.cmd' : 'npm', ['--version'], 'npm'),
  ]

  if (selectedModelsUseProvider(config, agentId, 'deepseek')) {
    const status = providerAuthStatus('deepseek')
    checks.push({
      id: 'auth:deepseek',
      label: 'DeepSeek auth',
      ok: Boolean(status.configured),
      severity: status.configured ? 'info' : 'error',
      message: status.configured
        ? 'DeepSeek API key is configured.'
        : 'DeepSeek API key is missing. Add it in provider settings or set DEEPSEEK_API_KEY.',
      detail: status.configured ? undefined : `Checked env keys: ${(status.envKeys || []).join(', ') || 'DEEPSEEK_API_KEY'}`,
    })
  }

  const codexRuntimeRequired = openClawConfigNeedsCodexPlugin(config)
  const codexPluginEnabled = isCodexPluginExplicitlyEnabled(config)
  if (codexRuntimeRequired && !codexPluginEnabled) {
    checks.push({
      id: 'plugin:codex',
      label: 'Codex plugin',
      ok: false,
      severity: 'error',
      message: 'Codex runtime is selected, but the Codex plugin is disabled.',
      detail: 'Enable the Codex plugin explicitly or switch the OpenAI provider/model runtime to OpenClaw.',
    })
  } else if (codexPluginEnabled) {
    checks.push(await pluginRuntimeCheck('codex', 'Codex plugin'))
  }

  return checks
}

function runtimePreflightFailureMessage(agentId: string, checks: AgentRuntimePreflightCheck[]) {
  const failures = checks.filter((check) => !check.ok && check.severity === 'error')
  if (!failures.length) return ''
  return [
    `Agent runtime health preflight failed for ${agentId}.`,
    ...failures.map((check) => `${check.label}: ${check.message}${check.detail ? ` ${check.detail}` : ''}`),
  ].join(' ')
}

async function ensureAgentRuntimeHealthPreflight(agentId: string, config?: OpenClawConfigFile) {
  const activeConfig = config || await readOpenclawConfig()
  const checks = await buildAgentRuntimePreflightChecks(agentId, activeConfig)
  const failure = runtimePreflightFailureMessage(agentId, checks)
  if (failure) {
    const error = new Error(failure)
    ;(error as Error & { checks?: AgentRuntimePreflightCheck[] }).checks = checks
    throw error
  }
  return checks
}

async function runOpenClaw(
  args: string[],
  timeoutMs = 120000,
  options?: { cwd?: string; envOverrides?: Record<string, string>; signal?: AbortSignal },
): Promise<OpenClawResult> {
  const runCwd = options?.cwd || WORKSPACE_ROOT
  if (!isOpenClawRuntimeAvailable()) {
    const runRecord = beginOpenClawRun(args, runCwd, timeoutMs)
    const stderr = openClawRuntimeUnavailableMessage()
    finishOpenClawRun(runRecord, 'failed', { stdout: '', stderr, code: 1, failureKind: 'runtime_unavailable' })
    return { stdout: '', stderr, code: 1, controlCenterRunId: runRecord.id, failureKind: 'runtime_unavailable', elapsedMs: 0 }
  }

  if (args[0] === 'agent') {
    await ensureOpenclawAgentRunConfigDefaults()
    await clearDisallowedAutoModelOverridesForAgentArgs(args)
    await cleanupStaleOpenClawSessionLocksForArgs(args)
  }

  return new Promise((resolve, reject) => {
    if (options?.signal?.aborted) {
      reject(new Error('openclaw aborted before start'))
      return
    }
    const runRecord = beginOpenClawRun(args, runCwd, timeoutMs)
    const startedAt = Date.now()
    const spawnEnv = openClawProcessEnv(options?.envOverrides || {})
    const spec = openClawSpawnSpec(args)
    const child = spawn(spec.command, spec.args, {
      cwd: runCwd,
      env: spawnEnv,
      shell: spec.shell,
      ...(process.platform === 'win32' ? { windowsHide: true } : {}),
    })
    updateOpenClawRunPid(runRecord, child.pid)
    let stdout = ''
    let stderr = ''
    let settled = false
    const shouldResolveOnJsonReply = args[0] === 'agent' && args.includes('--json')

    const timeout = setTimeout(() => {
      if (settled) return
      settled = true
      void terminateProcessTree(child.pid, 'openclaw timeout', true)
      scheduleStaleOpenClawSessionLockCleanup(args)
      cleanup()
      finishOpenClawRun(runRecord, 'timeout', { stdout, stderr, code: 1, failureKind: 'timeout' })
      // Give Node a short chance to flush stdout/stderr from a child that did
      // produce a JSON reply but kept handles open past the wrapper timeout.
      setTimeout(() => resolve({
        ...resolveOpenClawTimeoutResult(stdout, stderr, timeoutMs),
        controlCenterRunId: runRecord.id,
        failureKind: 'timeout',
        elapsedMs: Date.now() - startedAt,
        timedOut: true,
      }), 750)
    }, timeoutMs)
    const abort = () => {
      if (settled) return
      settled = true
      void terminateProcessTree(child.pid, 'openclaw aborted', true)
      scheduleStaleOpenClawSessionLockCleanup(args)
      clearTimeout(timeout)
      finishOpenClawRun(runRecord, 'aborted', { stdout, stderr, code: 1, failureKind: 'aborted' })
      reject(new Error('openclaw aborted'))
    }
    options?.signal?.addEventListener('abort', abort, { once: true })
    const cleanup = () => {
      clearTimeout(timeout)
      options?.signal?.removeEventListener('abort', abort)
    }

    child.stdout.on('data', (chunk) => {
      stdout = appendBoundedRuntimeOutput(stdout, chunk)
      if (!shouldResolveOnJsonReply || settled || !stdoutHasOpenClawReply(stdout)) return
      settled = true
      cleanup()
      void terminateProcessTree(child.pid, 'openclaw json reply complete')
      scheduleStaleOpenClawSessionLockCleanup(args)
      finishOpenClawRun(runRecord, 'completed', { stdout, stderr, code: 0 })
      resolve({ stdout: stdout.trim(), stderr: stderr.trim(), code: 0, controlCenterRunId: runRecord.id, elapsedMs: Date.now() - startedAt })
    })
    child.stderr.on('data', (chunk) => {
      stderr = appendBoundedRuntimeOutput(stderr, chunk)
    })
    child.on('error', (err) => {
      if (settled) return
      settled = true
      cleanup()
      const failureKind = classifyFailureKind(`${stderr}\n${String(err)}`, 'failed') || 'process_error'
      finishOpenClawRun(runRecord, 'failed', { stdout, stderr: stderr || String(err), code: 1, failureKind })
      reject(err)
    })
    child.on('close', (code) => {
      if (settled) return
      settled = true
      cleanup()
      void cleanupStaleOpenClawSessionLocksForArgs(args, { minAgeMs: 0, onlyCurrentSession: true })
      const exitCode = code ?? 1
      const status = exitCode === 0 ? 'completed' : 'failed'
      const failureKind = status === 'completed' ? undefined : classifyFailureKind(`${stderr}\n${stdout}`, status) || 'unknown'
      finishOpenClawRun(runRecord, status, { stdout, stderr, code: exitCode, failureKind })
      resolve({ stdout: stdout.trim(), stderr: stderr.trim(), code: exitCode, controlCenterRunId: runRecord.id, failureKind, elapsedMs: Date.now() - startedAt })
    })
  })
}

const RATE_LIMIT_REGEX = /\b(rate limit|too many requests|quota|429)\b/i

function isRateLimitText(text: string) {
  return RATE_LIMIT_REGEX.test(text || '')
}

async function runOpenClawWithRetry(
  args: string[],
  timeoutMs = 120000,
  options?: { cwd?: string; envOverrides?: Record<string, string>; signal?: AbortSignal },
): Promise<OpenClawResult> {
  const first = await runOpenClaw(args, timeoutMs, options).catch(openClawErrorResult)
  const combined = `${first.stdout || ''}\n${first.stderr || ''}`
  if (args[0] !== 'agent' || !isRateLimitText(combined)) return first

  await new Promise((resolve) => setTimeout(resolve, 2200))
  return runOpenClaw(args, timeoutMs, options).catch(openClawErrorResult)
}

async function refreshOpenClawPluginRegistry(reason: string): Promise<OpenClawResult> {
  const args = ['plugins', 'registry', '--refresh']
  const result = await runOpenClaw(args, 120_000)
  const warning = pluginCliWarningFromOutput(result, 'openclaw plugins registry --refresh')
  if (result.code !== 0) {
    console.warn(`[plugins] registry refresh failed (${reason}): ${warning || stripAnsi(`${result.stdout}\n${result.stderr}`).trim() || `exit ${result.code}`}`)
  } else if (warning) {
    console.warn(`[plugins] registry refresh warning (${reason}): ${warning}`)
  }
  return result
}

type PluginRegistryRefreshRequest = {
  scheduled: boolean
  detail: string
}

const PLUGIN_REGISTRY_REFRESH_DEBOUNCE_MS = 500
let pluginRegistryRefreshTimer: NodeJS.Timeout | null = null
let pluginRegistryRefreshInFlight: Promise<void> | null = null
let pluginRegistryRefreshRunAgain = false
let pluginRegistryRefreshReasons = new Set<string>()

async function runQueuedPluginRegistryRefresh(): Promise<void> {
  if (pluginRegistryRefreshInFlight) {
    pluginRegistryRefreshRunAgain = true
    await pluginRegistryRefreshInFlight
    return
  }

  pluginRegistryRefreshInFlight = (async () => {
    do {
      pluginRegistryRefreshRunAgain = false
      const reasons = [...pluginRegistryRefreshReasons].join(', ') || 'plugin-change'
      pluginRegistryRefreshReasons = new Set()
      const result = await refreshOpenClawPluginRegistry(reasons)
      if (result.code === 0) {
        await refreshPluginListCache().catch((error) => {
          console.warn('[plugins] plugin list refresh after registry refresh failed:', error)
        })
      }
    } while (pluginRegistryRefreshRunAgain)
  })().finally(() => {
    pluginRegistryRefreshInFlight = null
  })

  await pluginRegistryRefreshInFlight
}

function schedulePluginRegistryRefresh(reason: string): PluginRegistryRefreshRequest {
  pluginRegistryRefreshReasons.add(reason)
  if (pluginRegistryRefreshTimer) clearTimeout(pluginRegistryRefreshTimer)
  pluginRegistryRefreshTimer = setTimeout(() => {
    pluginRegistryRefreshTimer = null
    void runQueuedPluginRegistryRefresh().catch((error) => {
      console.warn('[plugins] queued registry refresh failed:', error)
    })
  }, PLUGIN_REGISTRY_REFRESH_DEBOUNCE_MS)
  pluginRegistryRefreshTimer.unref?.()

  return {
    scheduled: true,
    detail: `plugin registry refresh queued in ${PLUGIN_REGISTRY_REFRESH_DEBOUNCE_MS}ms`,
  }
}

type PluginSetupTerminalCommand = 'plugins' | 'model' | 'full' | 'doctor' | 'registry'
type PluginSetupTerminalStatus = 'running' | 'completed' | 'failed' | 'stopped'
type PluginSetupTerminalEvent = 'data' | 'status'
type PluginSetupTerminalClient = (event: PluginSetupTerminalEvent, payload: unknown) => void
type PluginSetupTerminalSession = {
  id: string
  command: PluginSetupTerminalCommand
  commandLine: string
  title: string
  pluginId?: string
  createdAt: string
  updatedAt: string
  status: PluginSetupTerminalStatus
  exitCode?: number
  pid?: number
  output: string
  process: PtyProcess
  dataDisposable?: PtyDisposable
  exitDisposable?: PtyDisposable
  clients: Set<PluginSetupTerminalClient>
}

const PLUGIN_SETUP_TERMINAL_COMMANDS: Record<PluginSetupTerminalCommand, { label: string; args: string[] }> = {
  plugins: { label: 'Plugin fields', args: ['configure', '--section', 'plugins'] },
  model: { label: 'Model/auth', args: ['configure', '--section', 'model'] },
  full: { label: 'Full configure', args: ['configure'] },
  doctor: { label: 'Plugin doctor', args: ['plugins', 'doctor'] },
  registry: { label: 'Registry refresh', args: ['plugins', 'registry', '--refresh'] },
}
const PLUGIN_SETUP_TERMINAL_MAX_BUFFER_CHARS = 250_000
const PLUGIN_SETUP_TERMINAL_RETAIN_MS = 10 * 60 * 1000
const pluginSetupTerminalSessions = new Map<string, PluginSetupTerminalSession>()
let cachedPtyModule: PtyModule | null = null
let warnedPlainTerminalFallback = false

function createPlainProcessTerminalModule(reason: unknown): PtyModule {
  if (!warnedPlainTerminalFallback) {
    warnedPlainTerminalFallback = true
    console.warn(`[plugins/setup-terminal] PTY runtime unavailable; using plain process fallback: ${String(reason)}`)
  }
  return {
    spawn(command, args, options) {
      const child = spawn(command, args, {
        cwd: options.cwd,
        env: options.env,
        shell: false,
        stdio: 'pipe',
        ...(process.platform === 'win32' ? { windowsHide: true } : {}),
      })
      return {
        pid: child.pid ?? 0,
        write(data: string) {
          child.stdin?.write(data)
        },
        resize() {
          // Plain process fallback has no PTY viewport to resize.
        },
        kill() {
          child.kill()
        },
        onData(callback: (data: string) => void) {
          const onStdout = (chunk: Buffer) => callback(chunk.toString())
          const onStderr = (chunk: Buffer) => callback(chunk.toString())
          child.stdout?.on('data', onStdout)
          child.stderr?.on('data', onStderr)
          return {
            dispose: () => {
              child.stdout?.off('data', onStdout)
              child.stderr?.off('data', onStderr)
            },
          }
        },
        onExit(callback: (event: { exitCode: number; signal?: number }) => void) {
          const onClose = (code: number | null, signal: NodeJS.Signals | null) => {
            callback({ exitCode: code ?? (signal ? 1 : 0), signal: signal ? 1 : undefined })
          }
          child.once('close', onClose)
          return {
            dispose: () => {
              child.off('close', onClose)
            },
          }
        },
      }
    },
  }
}

function loadPtyModule(): PtyModule {
  if (cachedPtyModule) return cachedPtyModule
  try {
    cachedPtyModule = optionalRequire('node-pty') as PtyModule
    return cachedPtyModule
  } catch (error) {
    cachedPtyModule = createPlainProcessTerminalModule(error)
    return cachedPtyModule
  }
}

function compactTerminalOutput(current: string, chunk: string) {
  const next = `${current}${chunk}`
  if (next.length <= PLUGIN_SETUP_TERMINAL_MAX_BUFFER_CHARS) return next
  return next.slice(next.length - PLUGIN_SETUP_TERMINAL_MAX_BUFFER_CHARS)
}

function terminalSpawnEnv(): Record<string, string> {
  const env = openClawProcessEnv({
    TERM: 'xterm-256color',
    COLORTERM: 'truecolor',
    FORCE_COLOR: '1',
  })
  return Object.fromEntries(
    Object.entries(env).filter((entry): entry is [string, string] => typeof entry[1] === 'string'),
  )
}

function terminalCommandLine(args: string[]) {
  return ['openclaw', ...args].join(' ')
}

function pluginSetupTerminalSnapshot(session: PluginSetupTerminalSession) {
  return {
    id: session.id,
    command: session.command,
    commandLine: session.commandLine,
    title: session.title,
    pluginId: session.pluginId,
    createdAt: session.createdAt,
    updatedAt: session.updatedAt,
    status: session.status,
    exitCode: session.exitCode,
    pid: session.pid,
  }
}

function emitPluginSetupTerminal(session: PluginSetupTerminalSession, event: PluginSetupTerminalEvent, payload: unknown) {
  for (const client of session.clients) client(event, payload)
}

function schedulePluginSetupTerminalCleanup(sessionId: string) {
  const timeout = setTimeout(() => {
    const session = pluginSetupTerminalSessions.get(sessionId)
    if (!session || session.status === 'running') return
    session.dataDisposable?.dispose()
    session.exitDisposable?.dispose()
    pluginSetupTerminalSessions.delete(sessionId)
  }, PLUGIN_SETUP_TERMINAL_RETAIN_MS)
  timeout.unref?.()
}

function startPluginSetupTerminalSession(params: {
  command: PluginSetupTerminalCommand
  pluginId?: string
  cols?: number
  rows?: number
}): PluginSetupTerminalSession {
  const commandInfo = PLUGIN_SETUP_TERMINAL_COMMANDS[params.command]
  const args = commandInfo.args
  const spec = openClawSpawnSpec(args)
  const pty = loadPtyModule()
  const now = new Date().toISOString()
  const processHandle = pty.spawn(spec.command, [...spec.args], {
    name: 'xterm-256color',
    cols: Math.max(40, Math.min(180, Math.floor(params.cols || 96))),
    rows: Math.max(10, Math.min(60, Math.floor(params.rows || 20))),
    cwd: WORKSPACE_ROOT,
    env: terminalSpawnEnv(),
    useConpty: process.platform === 'win32',
  })
  const session: PluginSetupTerminalSession = {
    id: randomUUID(),
    command: params.command,
    commandLine: terminalCommandLine(args),
    title: params.pluginId ? `${commandInfo.label}: ${params.pluginId}` : commandInfo.label,
    pluginId: params.pluginId,
    createdAt: now,
    updatedAt: now,
    status: 'running',
    pid: processHandle.pid,
    output: '',
    process: processHandle,
    clients: new Set(),
  }
  session.dataDisposable = processHandle.onData((data) => {
    session.updatedAt = new Date().toISOString()
    session.output = compactTerminalOutput(session.output, data)
    emitPluginSetupTerminal(session, 'data', { data })
  })
  session.exitDisposable = processHandle.onExit((event) => {
    session.updatedAt = new Date().toISOString()
    session.exitCode = event.exitCode
    session.status = event.exitCode === 0 ? 'completed' : 'failed'
    emitPluginSetupTerminal(session, 'status', { session: pluginSetupTerminalSnapshot(session) })
    schedulePluginSetupTerminalCleanup(session.id)
  })
  pluginSetupTerminalSessions.set(session.id, session)
  return session
}

function stopPluginSetupTerminalSession(session: PluginSetupTerminalSession) {
  if (session.status === 'running') {
    session.status = 'stopped'
    session.updatedAt = new Date().toISOString()
    try {
      session.process.kill()
    } catch {
      // Process may already be gone.
    }
  }
  emitPluginSetupTerminal(session, 'status', { session: pluginSetupTerminalSnapshot(session) })
  schedulePluginSetupTerminalCleanup(session.id)
}

type StreamingProviderKind =
  | 'openai-compatible'
  | 'openai-responses'
  | 'openai-codex-responses'
  | 'anthropic-messages'
  | 'gemini-generate-content'
  | 'gemini-vertex-generate-content'

type StreamingProviderConfig = {
  kind: StreamingProviderKind
  envKeys: string[]
  endpoint?: string
  docs: string
}

type StreamEmitter = (event: string, data: Record<string, unknown>) => void

const SSE_DELTA_CHUNK_CHARS = 16_000
const SSE_FINAL_TEXT_LIMIT = 24_000

const STREAMING_PROVIDER_CONFIG: Record<string, StreamingProviderConfig> = {
  deepseek: {
    kind: 'openai-compatible',
    envKeys: ['DEEPSEEK_API_KEY'],
    endpoint: 'https://api.deepseek.com/chat/completions',
    docs: 'https://api-docs.deepseek.com/api/create-chat-completion',
  },
  openai: {
    kind: 'openai-responses',
    envKeys: ['OPENAI_API_KEY'],
    endpoint: 'https://api.openai.com/v1/responses',
    docs: 'https://developers.openai.com/api/docs/guides/streaming-responses',
  },
  'openai-codex': {
    kind: 'openai-codex-responses',
    envKeys: [],
    endpoint: 'https://api.openai.com/v1/responses',
    docs: 'https://developers.openai.com/api/docs/guides/streaming-responses',
  },
  anthropic: {
    kind: 'anthropic-messages',
    envKeys: ['ANTHROPIC_API_KEY'],
    endpoint: 'https://api.anthropic.com/v1/messages',
    docs: 'https://platform.claude.com/docs/en/build-with-claude/streaming',
  },
  google: {
    kind: 'gemini-generate-content',
    envKeys: ['GEMINI_API_KEY', 'GOOGLE_API_KEY'],
    docs: 'https://ai.google.dev/api/generate-content',
  },
  'google-vertex': {
    kind: 'gemini-vertex-generate-content',
    envKeys: GOOGLE_VERTEX_ACCESS_TOKEN_KEYS,
    docs: 'https://cloud.google.com/vertex-ai/generative-ai/docs/model-reference/gemini',
  },
}

function splitModelId(modelId: string) {
  const [provider = '', ...modelParts] = modelId.split('/')
  return {
    provider: provider.trim(),
    model: (modelParts.join('/') || modelId).trim(),
  }
}

function streamingCapabilityForModel(modelId: string) {
  const canonicalModelId = canonicalAgentModelId(modelId)
  if (isOpenAiCodexSubscriptionModel(canonicalModelId)) {
    const codexAuth = AUTH_PROVIDER_CATALOG['openai-codex']
    const oauthConfigured = isOAuthCredentialUsable(localAuthStore.providers['openai-codex']?.oauth)
    const openAiApiConfigured = isProviderConfigured('openai')
    return {
      supported: true,
      provider: oauthConfigured ? 'openai-codex' : 'openai',
      transport: oauthConfigured ? 'openai-codex-responses' : 'openai-responses',
      requires: oauthConfigured || openAiApiConfigured ? [] as string[] : ['OpenAI Codex OAuth or OPENAI_API_KEY'],
      docs: codexAuth?.docs,
    }
  }

  const { provider } = splitModelId(canonicalModelId)
  const config = STREAMING_PROVIDER_CONFIG[provider]
  return {
    supported: Boolean(config),
    provider,
    transport: config?.kind || 'buffered-openclaw',
    requires: config?.envKeys || [],
    docs: config?.docs,
  }
}

function resolveEnvValue(env: Record<string, string>, keys: string[]) {
  for (const key of keys) {
    const value = env[key]?.trim() || process.env[key]?.trim()
    if (value) return value
  }
  return ''
}

type GoogleVertexGcloudStatus = {
  supported: true
  installed: boolean
  authenticated: boolean
  configured: boolean
  projectId?: string
  location: string
  account?: string
  missing: string[]
  installUrl: string
  commands: string[]
  source?: 'probe' | 'cache' | 'fast'
}

let googleVertexGcloudStatusCache: { value: GoogleVertexGcloudStatus; expiresAt: number } | null = null
let googleVertexAccessTokenCache: { value: string; expiresAt: number } | null = null
let googleVertexGcloudCommandCache: string | null = null

function googleCloudSdkRootCandidates() {
  const localAppData = resolveEnvValue({}, ['LOCALAPPDATA', 'LocalAppData'])
  const appData = resolveEnvValue({}, ['APPDATA', 'AppData'])
  const programFiles = resolveEnvValue({}, ['ProgramFiles', 'PROGRAMFILES'])
  const programFilesX86 = process.env['ProgramFiles(x86)']?.trim() || process.env.PROGRAMFILES_X86?.trim() || ''
  return uniqueStrings(
    resolveEnvValue({}, ['CLOUDSDK_ROOT_DIR', 'GCLOUD_SDK_ROOT', 'GOOGLE_CLOUD_SDK_HOME']),
    localAppData ? path.join(localAppData, 'Google', 'Cloud SDK', 'google-cloud-sdk') : '',
    localAppData ? path.join(localAppData, 'Programs', 'Google', 'Cloud SDK', 'google-cloud-sdk') : '',
    appData ? path.join(appData, 'gcloud', 'google-cloud-sdk') : '',
    programFiles ? path.join(programFiles, 'Google', 'Cloud SDK', 'google-cloud-sdk') : '',
    programFilesX86 ? path.join(programFilesX86, 'Google', 'Cloud SDK', 'google-cloud-sdk') : '',
  )
}

function googleCloudSdkBinForRoot(root: string) {
  return path.basename(root).toLowerCase() === 'bin' ? root : path.join(root, 'bin')
}

function googleVertexGcloudCommandCandidates() {
  const commandNames = process.platform === 'win32'
    ? ['gcloud.cmd', 'gcloud.bat', 'gcloud.exe']
    : ['gcloud']
  return uniqueStrings(
    ...googleCloudSdkRootCandidates().flatMap((root) => {
      const binDir = googleCloudSdkBinForRoot(root)
      return commandNames.map((name) => path.join(binDir, name))
    }),
  ).filter((candidate) => existsSync(candidate))
}

function prependPathEntry(value: string | undefined, entry: string) {
  const current = value || ''
  const delimiter = process.platform === 'win32' ? ';' : ':'
  const parts = current.split(delimiter).filter(Boolean)
  if (parts.some((part) => path.resolve(part).toLowerCase() === path.resolve(entry).toLowerCase())) return current
  return [entry, ...parts].join(delimiter)
}

function spawnGcloud(command: string, args: string[], timeoutMs: number) {
  const env = { ...process.env }
  if (path.isAbsolute(command)) {
    const binDir = path.dirname(command)
    env.PATH = prependPathEntry(env.PATH, binDir)
    env.Path = prependPathEntry(env.Path, binDir)
  }
  const spec = shelllessSpawnSpecForCommand(command, args, { wrapWindowsPathLookup: true })
  const result = spawnSync(
    spec.command,
    spec.args,
    {
    encoding: 'utf-8',
    timeout: timeoutMs,
    shell: spec.shell,
    env,
    ...(process.platform === 'win32' ? { windowsHide: true } : {}),
    },
  )
  const errorText = result.error ? String(result.error) : ''
  return {
    stdout: String(result.stdout || '').trim(),
    stderr: [String(result.stderr || '').trim(), errorText].filter(Boolean).join('\n'),
    code: typeof result.status === 'number' ? result.status : result.error ? 1 : 0,
  }
}

function isMissingGcloudCommand(result: { stderr: string; code: number }) {
  const stderr = result.stderr.toLowerCase()
  return Boolean(
    stderr.includes('enoent') ||
    stderr.includes('not recognized as an internal or external command') ||
    stderr.includes('command not found') ||
    stderr.includes('no such file or directory'),
  )
}

function runGcloud(args: string[], timeoutMs = 8000): { stdout: string; stderr: string; code: number } {
  const commands = uniqueStrings(googleVertexGcloudCommandCache, 'gcloud', ...googleVertexGcloudCommandCandidates())
  let missingResult: { stdout: string; stderr: string; code: number } | null = null
  for (const command of commands) {
    const result = spawnGcloud(command, args, timeoutMs)
    if (!isMissingGcloudCommand(result)) {
      googleVertexGcloudCommandCache = command
      return result
    }
    missingResult ||= result
    if (googleVertexGcloudCommandCache === command) googleVertexGcloudCommandCache = null
  }
  return missingResult || { stdout: '', stderr: 'gcloud was not found.', code: 1 }
}

function cleanGcloudConfigValue(value: string) {
  const line = value.split(/\r?\n/).map((entry) => entry.trim()).find(Boolean) || ''
  if (!line || line === '(unset)' || /^unset$/i.test(line)) return ''
  return line
}

function resolveGoogleVertexProjectId(env: Record<string, string> = {}) {
  const fromEnv = resolveEnvValue(env, GOOGLE_VERTEX_PROJECT_ID_KEYS)
  if (fromEnv) return fromEnv
  const result = runGcloud(['config', 'get-value', 'project', '--quiet'], 5000)
  return result.code === 0 ? cleanGcloudConfigValue(result.stdout) : ''
}

function resolveGoogleVertexProjectIdFast(env: Record<string, string> = {}) {
  return (
    resolveEnvValue(env, GOOGLE_VERTEX_PROJECT_ID_KEYS) ||
    localAuthStore.providers.google?.oauth?.projectId?.trim() ||
    resolveGoogleProjectId() ||
    ''
  )
}

function resolveGoogleVertexLocation(env: Record<string, string> = {}) {
  const fromEnv = resolveEnvValue(env, GOOGLE_VERTEX_LOCATION_KEYS)
  if (fromEnv) return fromEnv
  const result = runGcloud(['config', 'get-value', 'ai/region', '--quiet'], 5000)
  return (result.code === 0 && cleanGcloudConfigValue(result.stdout)) || GOOGLE_VERTEX_DEFAULT_LOCATION
}

function resolveGoogleVertexLocationFast(env: Record<string, string> = {}) {
  return resolveEnvValue(env, GOOGLE_VERTEX_LOCATION_KEYS) || GOOGLE_VERTEX_DEFAULT_LOCATION
}

function resolveGoogleVertexAccessTokenForProcessEnv(env: Record<string, string> = {}) {
  const fromEnv = resolveEnvValue(env, GOOGLE_VERTEX_ACCESS_TOKEN_KEYS)
  if (fromEnv) return fromEnv

  const localGoogleOAuth = localAuthStore.providers.google?.oauth
  const localAccessToken = localGoogleOAuth?.accessToken?.trim()
  if (localAccessToken && (!localGoogleOAuth?.expiresAt || localGoogleOAuth.expiresAt > Date.now() + 60_000)) {
    return localAccessToken
  }

  if (googleVertexAccessTokenCache && googleVertexAccessTokenCache.expiresAt > Date.now()) {
    return googleVertexAccessTokenCache.value
  }

  const token = runGcloud(['auth', 'print-access-token', '--quiet'], 10000)
  const accessToken = token.code === 0 ? token.stdout.trim() : ''
  if (!accessToken) return ''
  googleVertexAccessTokenCache = {
    value: accessToken,
    expiresAt: Date.now() + GOOGLE_VERTEX_ACCESS_TOKEN_CACHE_MS,
  }
  return accessToken
}

function getGoogleVertexProcessEnv(baseEnv: Record<string, string | undefined> = process.env): Record<string, string> {
  const env = Object.fromEntries(
    Object.entries(baseEnv).filter((entry): entry is [string, string] => typeof entry[1] === 'string'),
  )
  const projectId = resolveGoogleVertexProjectId(env)
  if (!projectId) return {}
  const location = resolveGoogleVertexLocation(env)
  const next: Record<string, string> = {}
  if (!env.GOOGLE_CLOUD_PROJECT?.trim()) next.GOOGLE_CLOUD_PROJECT = projectId
  if (!env.GCLOUD_PROJECT?.trim()) next.GCLOUD_PROJECT = projectId
  if (!env.GOOGLE_CLOUD_LOCATION?.trim()) next.GOOGLE_CLOUD_LOCATION = location
  const accessToken = resolveGoogleVertexAccessTokenForProcessEnv(env)
  if (accessToken) {
    if (!env.GOOGLE_VERTEX_ACCESS_TOKEN?.trim()) next.GOOGLE_VERTEX_ACCESS_TOKEN = accessToken
    if (!env.GCLOUD_ACCESS_TOKEN?.trim()) next.GCLOUD_ACCESS_TOKEN = accessToken
  }
  return next
}

function googleVertexGcloudStatus(options: { probeGcloud?: boolean } = {}): GoogleVertexGcloudStatus {
  const now = Date.now()
  const forceProbe = options.probeGcloud === true
  if (!forceProbe && googleVertexGcloudStatusCache && googleVertexGcloudStatusCache.expiresAt > now) {
    return { ...googleVertexGcloudStatusCache.value, source: 'cache' }
  }

  if (options.probeGcloud === false) {
    const projectId = resolveGoogleVertexProjectIdFast()
    const location = resolveGoogleVertexLocationFast()
    const tokenFromEnv = resolveEnvValue({}, GOOGLE_VERTEX_ACCESS_TOKEN_KEYS)
    const localGoogleOAuth = localAuthStore.providers.google?.oauth
    const localOAuthUsable = isOAuthCredentialUsable(localGoogleOAuth)
    const authenticated = Boolean(tokenFromEnv || localOAuthUsable)
    const configured = Boolean(projectId && authenticated)
    const missing: string[] = []
    if (!authenticated) missing.push('Connect Google OAuth, set GOOGLE_VERTEX_ACCESS_TOKEN, or refresh gcloud status.')
    if (!projectId) missing.push('Set a Google Cloud project.')
    if (configured) missing.length = 0
    return {
      supported: true,
      installed: googleVertexGcloudStatusCache?.value.installed ?? false,
      authenticated,
      configured,
      ...(projectId ? { projectId } : {}),
      location,
      ...(localGoogleOAuth?.email ? { account: localGoogleOAuth.email } : {}),
      missing,
      installUrl: GOOGLE_CLOUD_CLI_INSTALL_URL,
      commands: [
        'gcloud auth login',
        'gcloud config set project YOUR_PROJECT_ID',
        `gcloud services enable aiplatform.googleapis.com --project ${projectId || 'YOUR_PROJECT_ID'}`,
      ],
      source: 'fast',
    }
  }

  const projectId = resolveGoogleVertexProjectId()
  const location = resolveGoogleVertexLocation()
  const tokenFromEnv = resolveEnvValue({}, GOOGLE_VERTEX_ACCESS_TOKEN_KEYS)
  const version = runGcloud(['--version'], 5000)
  const installed = version.code === 0
  const account = installed
    ? cleanGcloudConfigValue(runGcloud(['auth', 'list', '--filter=status:ACTIVE', '--format=value(account)', '--quiet'], 7000).stdout)
    : ''
  const tokenProbe = installed && !tokenFromEnv
    ? runGcloud(['auth', 'print-access-token', '--quiet'], 10000)
    : { stdout: '', stderr: '', code: tokenFromEnv ? 0 : 1 }
  const authenticated = Boolean(tokenFromEnv || (tokenProbe.code === 0 && tokenProbe.stdout.trim()))
  const configured = Boolean(projectId && authenticated)
  const missing: string[] = []
  if (!installed && !tokenFromEnv) {
    missing.push(`Install Google Cloud CLI: ${GOOGLE_CLOUD_CLI_INSTALL_URL}`)
  }
  if (installed && !authenticated) {
    missing.push('Run gcloud auth login, then retry.')
  }
  if (!projectId) {
    missing.push('Set a Google Cloud project with gcloud config set project YOUR_PROJECT_ID.')
  }
  if (configured) {
    missing.length = 0
  }

  const value: GoogleVertexGcloudStatus = {
    supported: true,
    installed,
    authenticated,
    configured,
    ...(projectId ? { projectId } : {}),
    location,
    ...(account ? { account } : {}),
    missing,
    installUrl: GOOGLE_CLOUD_CLI_INSTALL_URL,
    commands: [
      'gcloud auth login',
      'gcloud config set project YOUR_PROJECT_ID',
      `gcloud services enable aiplatform.googleapis.com --project ${projectId || 'YOUR_PROJECT_ID'}`,
    ],
    source: 'probe',
  }
  googleVertexGcloudStatusCache = { value, expiresAt: now + 15000 }
  return value
}

function googleVertexLocalOAuthProjectId(env: Record<string, string> = {}, options: { probeGcloud?: boolean } = {}) {
  return (
    (options.probeGcloud === false ? resolveGoogleVertexProjectIdFast(env) : resolveGoogleVertexProjectId(env)) ||
    localAuthStore.providers.google?.oauth?.projectId?.trim() ||
    resolveGoogleProjectId() ||
    ''
  )
}

function isGoogleVertexLocalOAuthConfigured(env: Record<string, string> = {}, options: { probeGcloud?: boolean } = {}) {
  return Boolean(isOAuthCredentialUsable(localAuthStore.providers.google?.oauth) && googleVertexLocalOAuthProjectId(env, options))
}

function isGoogleVertexConfigured(options: { probeGcloud?: boolean } = {}) {
  return googleVertexGcloudStatus(options).configured || isGoogleVertexLocalOAuthConfigured({}, options)
}

async function resolveGoogleVertexGcloudAuth(env: Record<string, string>): Promise<ProviderRequestAuth | null> {
  const envToken = resolveEnvValue(env, GOOGLE_VERTEX_ACCESS_TOKEN_KEYS)
  const projectId = resolveGoogleVertexProjectId(env)
  const location = resolveGoogleVertexLocation(env)
  if (envToken && projectId) {
    return { type: 'oauth', accessToken: envToken, projectId, location, source: 'env-token' }
  }

  const version = runGcloud(['--version'], 5000)
  if (version.code !== 0) return null
  const token = runGcloud(['auth', 'print-access-token', '--quiet'], 10000)
  const accessToken = token.stdout.trim()
  if (token.code !== 0 || !accessToken || !projectId) return null
  return { type: 'oauth', accessToken, projectId, location, source: 'gcloud' }
}

async function resolveGoogleVertexRequestAuth(env: Record<string, string>): Promise<ProviderRequestAuth | null> {
  const gcloudAuth = await resolveGoogleVertexGcloudAuth(env)
  if (gcloudAuth) return gcloudAuth

  const oauth = await resolveGoogleOAuthForRequest().catch(() => null)
  const projectId = googleVertexLocalOAuthProjectId(env)
  const location = resolveGoogleVertexLocation(env)
  if (oauth?.accessToken && projectId) {
    return { type: 'oauth', accessToken: oauth.accessToken, projectId, location, source: 'local-google-oauth' }
  }

  return null
}

type ProviderRequestAuth =
  | { type: 'apiKey'; value: string; source: string }
  | { type: 'oauth'; accessToken: string; projectId?: string; location?: string; source: string }

type GoogleOAuthClientConfig = {
  clientId: string
  clientSecret?: string
}

type OAuthSessionStatus = 'pending' | 'complete' | 'error'

type OAuthSession = {
  id: string
  provider: 'google' | 'openai-codex'
  state?: string
  verifier?: string
  challenge?: string
  projectId?: string
  redirectUri?: string
  authorizationUrl: string
  status: OAuthSessionStatus
  createdAt: string
  completedAt?: string
  error?: string
  manualInputRequired?: boolean
  manualInputSubmittedAt?: string
  manualPrompt?: string
  result?: {
    email?: string
    accountId?: string
    projectId?: string
    expiresAt?: number
  }
}

type OpenAICodexAuthorizationFlow = {
  verifier: string
  redirectUri: string
  state: string
  url: string
}

type OpenAICodexTokenExchangeResult =
  | {
      type: 'success'
      access: string
      refresh: string
      expires: number
    }
  | {
      type: 'failed'
      status?: number
      message: string
    }

type OpenAICodexOAuthTesting = {
  createAuthorizationFlow: (originator?: string) => Promise<OpenAICodexAuthorizationFlow>
  exchangeAuthorizationCode: (
    code: string,
    verifier: string,
    redirectUri?: string,
  ) => Promise<OpenAICodexTokenExchangeResult>
}

type OpenAICodexOAuthModule = {
  loginOpenAICodex: (options: {
    originator?: string
    onAuth: (auth: { url: string; instructions?: string }) => void
    onProgress?: (message: string) => void
    onPrompt: (prompt: { message: string }) => Promise<string>
  }) => Promise<{
    access: string
    refresh: string
    expires: number
    accountId?: string
    idToken?: string
  }>
}

type OpenAICodexRefreshModule = {
  refreshOpenAICodexToken: (refreshToken: string) => Promise<{
    access: string
    refresh: string
    expires: number
    accountId?: string
    idToken?: string
  }>
}

type OpenAICodexRuntimeModule = OpenAICodexOAuthModule & OpenAICodexRefreshModule & {
  testing?: OpenAICodexOAuthTesting
}

function openAICodexOAuthModulePath() {
  return openClawDistModulePath('openai-chatgpt-oauth-flow.runtime.js')
}

async function importOpenAICodexOAuthModule() {
  const modulePath = openAICodexOAuthModulePath()
  const oauthModule = await import(pathToFileURL(modulePath).href) as Record<string, unknown>
  const loginOpenAICodex = oauthModule.loginOpenAICodex ?? oauthModule.t
  const refreshOpenAICodexToken = oauthModule.refreshOpenAICodexToken ?? oauthModule.r
  const testing = oauthModule.testing ?? oauthModule.i

  if (typeof loginOpenAICodex !== 'function') {
    throw new Error(`OpenAI Codex OAuth runtime at ${modulePath} does not export loginOpenAICodex.`)
  }
  if (typeof refreshOpenAICodexToken !== 'function') {
    throw new Error(`OpenAI Codex OAuth runtime at ${modulePath} does not export refreshOpenAICodexToken.`)
  }

  return {
    ...oauthModule,
    loginOpenAICodex,
    refreshOpenAICodexToken,
    ...(testing ? { testing } : {}),
  } as OpenAICodexRuntimeModule
}

function openAICodexOAuthTesting(oauthModule: OpenAICodexRuntimeModule): OpenAICodexOAuthTesting {
  if (
    !oauthModule.testing ||
    typeof oauthModule.testing.createAuthorizationFlow !== 'function' ||
    typeof oauthModule.testing.exchangeAuthorizationCode !== 'function'
  ) {
    throw new Error('OpenAI Codex OAuth runtime does not expose the callback flow helpers.')
  }
  return oauthModule.testing
}

function openClawDistModulePath(fileName: string) {
  for (const distDir of openClawDistDirCandidates()) {
    const candidate = path.join(distDir, fileName)
    if (existsSync(candidate)) return candidate
  }
  return path.join(openClawDistDirCandidates()[0] || path.join(WORKSPACE_ROOT, 'vendor', 'openclaw', 'dist'), fileName)
}

function openClawDistModulePathByPrefix(prefix: string) {
  for (const distDir of openClawDistDirCandidates()) {
    if (!existsSync(distDir)) continue
    const candidates = readdirSync(distDir)
      .filter((entry) => entry.startsWith(prefix) && entry.endsWith('.js'))
      .sort((a, b) => a.length - b.length || a.localeCompare(b))
    const match = candidates[0]
    if (match) return path.join(distDir, match)
  }
  throw new Error(`Could not find OpenClaw dist module matching ${prefix}*.js`)
}

function openClawDistDirCandidates() {
  const electronResourcesPath = getElectronResourcesPath()
  const binDir = openclawBin && openclawBin !== 'openclaw' ? path.dirname(path.resolve(openclawBin)) : ''
  return uniqueStrings(
    binDir ? path.join(binDir, 'dist') : '',
    binDir,
    path.resolve(process.cwd(), 'vendor', 'openclaw', 'dist'),
    path.resolve(process.cwd(), 'resources', 'openclaw', 'dist'),
    electronResourcesPath ? path.join(electronResourcesPath, 'openclaw', 'dist') : '',
    path.join(WORKSPACE_ROOT, 'vendor', 'openclaw', 'dist'),
  ).filter(Boolean)
}

const oauthSessions = new Map<string, OAuthSession>()
let googleOAuthCallbackServer: Server | null = null
let googleOAuthCallbackServerStarting: Promise<void> | null = null
let openAICodexOAuthCallbackServer: Server | null = null
let openAICodexOAuthCallbackServerStarting: Promise<void> | null = null

function resolveFirstEnv(keys: string[]) {
  for (const key of keys) {
    const value = process.env[key]?.trim()
    if (value) return value
  }
  return ''
}

function googleOAuthClientConfigFileCandidates() {
  const candidates = [
    path.join(OPENCLAW_STATE_ROOT, 'google-oauth-client.json'),
    path.join(WORKSPACE_ROOT, 'google-oauth-client.json'),
    path.join(WORKSPACE_ROOT, 'client_secret.json'),
  ]

  try {
    const downloadedClientFiles = readdirSync(WORKSPACE_ROOT, { withFileTypes: true })
      .filter(
        (entry) =>
          entry.isFile() &&
          /^client_secret_.+\.apps\.googleusercontent\.com\.json$/i.test(entry.name),
      )
      .map((entry) => path.join(WORKSPACE_ROOT, entry.name))
      .sort()

    candidates.push(...downloadedClientFiles)
  } catch {
    // Optional convenience scan.
  }

  return candidates
}

function readGoogleOAuthClientConfigFile(): GoogleOAuthClientConfig | null {
  const candidates = googleOAuthClientConfigFileCandidates()

  for (const filePath of candidates) {
    try {
      const parsed = JSON.parse(readFileSync(filePath, 'utf-8')) as {
        installed?: { client_id?: string; client_secret?: string }
        web?: { client_id?: string; client_secret?: string }
        client_id?: string
        client_secret?: string
      }
      const source = parsed.installed || parsed.web || parsed
      const clientId = source.client_id?.trim()
      if (!clientId) continue
      return {
        clientId,
        ...(source.client_secret?.trim() ? { clientSecret: source.client_secret.trim() } : {}),
      }
    } catch {
      // Optional convenience file.
    }
  }

  return null
}

function resolveGoogleOAuthClientConfig(): GoogleOAuthClientConfig {
  const clientId = resolveFirstEnv(GOOGLE_OAUTH_CLIENT_ID_KEYS)
  if (clientId) {
    const clientSecret = resolveFirstEnv(GOOGLE_OAUTH_CLIENT_SECRET_KEYS)
    return {
      clientId,
      ...(clientSecret ? { clientSecret } : {}),
    }
  }

  const fileConfig = readGoogleOAuthClientConfigFile()
  if (fileConfig) return fileConfig

  throw new Error(
    `Google OAuth needs a desktop OAuth client. Set ${GOOGLE_OAUTH_CLIENT_ID_KEYS[0]} or place client_secret.json in ${WORKSPACE_ROOT}.`,
  )
}

function googleOAuthClientConfigStatus() {
  try {
    resolveGoogleOAuthClientConfig()
    return { available: true, missing: [] as string[] }
  } catch (error) {
    return {
      available: false,
      missing: [String(error)],
    }
  }
}

function resolveGoogleProjectId(input?: string) {
  const fromInput = input?.trim()
  if (fromInput) return fromInput
  return resolveFirstEnv(GOOGLE_PROJECT_ID_KEYS)
}

function generatePkcePair() {
  const verifier = randomBytes(32).toString('base64url')
  const challenge = createHash('sha256').update(verifier).digest('base64url')
  return { verifier, challenge }
}

function buildGoogleOAuthAuthorizationUrl(challenge: string, state: string) {
  const { clientId } = resolveGoogleOAuthClientConfig()
  return `https://accounts.google.com/o/oauth2/v2/auth?${new URLSearchParams({
    client_id: clientId,
    response_type: 'code',
    redirect_uri: GOOGLE_OAUTH_REDIRECT_URI,
    scope: GOOGLE_OAUTH_SCOPES.join(' '),
    code_challenge: challenge,
    code_challenge_method: 'S256',
    state,
    access_type: 'offline',
    prompt: 'consent select_account',
  }).toString()}`
}

async function fetchGoogleUserInfo(accessToken: string): Promise<{ email?: string }> {
  const response = await fetch('https://www.googleapis.com/oauth2/v1/userinfo?alt=json', {
    headers: { Authorization: `Bearer ${accessToken}` },
  })
  if (!response.ok) return {}
  const data = await response.json().catch(() => ({})) as { email?: string }
  return { ...(data.email ? { email: data.email } : {}) }
}

async function exchangeGoogleOAuthCodeForTokens(code: string, verifier: string, projectId?: string): Promise<LocalOAuthCredential> {
  const { clientId, clientSecret } = resolveGoogleOAuthClientConfig()
  const body = new URLSearchParams({
    client_id: clientId,
    code,
    grant_type: 'authorization_code',
    redirect_uri: GOOGLE_OAUTH_REDIRECT_URI,
    code_verifier: verifier,
  })
  if (clientSecret) body.set('client_secret', clientSecret)

  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',
      Accept: 'application/json',
    },
    body,
  })
  const data = await response.json().catch(() => ({})) as {
    access_token?: string
    refresh_token?: string
    expires_in?: number
    token_type?: string
    scope?: string
    error?: string
    error_description?: string
  }
  if (!response.ok || !data.access_token) {
    throw new Error(data.error_description || data.error || `Google token exchange failed (${response.status})`)
  }

  const user = await fetchGoogleUserInfo(data.access_token).catch((): { email?: string } => ({}))
  const expiresAt = Date.now() + Math.max(60, Number(data.expires_in || 3600)) * 1000 - 300000
  return {
    accessToken: data.access_token,
    ...(data.refresh_token ? { refreshToken: data.refresh_token } : {}),
    expiresAt,
    tokenType: data.token_type || 'Bearer',
    scope: data.scope?.split(/\s+/).filter(Boolean) || GOOGLE_OAUTH_SCOPES,
    ...(user.email ? { email: user.email } : {}),
    ...(projectId ? { projectId } : {}),
  }
}

async function refreshGoogleOAuthCredential(oauth: LocalOAuthCredential): Promise<LocalOAuthCredential> {
  const refreshToken = oauth.refreshToken?.trim()
  if (!refreshToken) throw new Error('Google OAuth refresh token is missing. Reconnect Google.')

  const { clientId, clientSecret } = resolveGoogleOAuthClientConfig()
  const body = new URLSearchParams({
    client_id: clientId,
    refresh_token: refreshToken,
    grant_type: 'refresh_token',
  })
  if (clientSecret) body.set('client_secret', clientSecret)

  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',
      Accept: 'application/json',
    },
    body,
  })
  const data = await response.json().catch(() => ({})) as {
    access_token?: string
    expires_in?: number
    token_type?: string
    scope?: string
    error?: string
    error_description?: string
  }
  if (!response.ok || !data.access_token) {
    throw new Error(data.error_description || data.error || `Google token refresh failed (${response.status})`)
  }

  return {
    ...oauth,
    accessToken: data.access_token,
    expiresAt: Date.now() + Math.max(60, Number(data.expires_in || 3600)) * 1000 - 300000,
    tokenType: data.token_type || oauth.tokenType || 'Bearer',
    scope: data.scope?.split(/\s+/).filter(Boolean) || oauth.scope || GOOGLE_OAUTH_SCOPES,
  }
}

function isOAuthCredentialUsable(oauth: LocalOAuthCredential | undefined): oauth is LocalOAuthCredential {
  return Boolean(oauth?.accessToken?.trim() || oauth?.refreshToken?.trim())
}

async function resolveGoogleOAuthForRequest(): Promise<{ accessToken: string; projectId?: string } | null> {
  const stored = localAuthStore.providers.google?.oauth || localOAuthFromMainAuthProfile('google') || undefined
  if (!isOAuthCredentialUsable(stored)) return null

  const expiresAt = stored.expiresAt || 0
  if (stored.accessToken?.trim() && expiresAt > Date.now() + 60000) {
    return {
      accessToken: stored.accessToken.trim(),
      ...(stored.projectId ? { projectId: stored.projectId } : {}),
    }
  }

  const refreshed = await refreshGoogleOAuthCredential(stored)
  await persistProviderOAuth('google', refreshed)
  const next = localAuthStore.providers.google?.oauth || refreshed
  return {
    accessToken: next.accessToken?.trim() || refreshed.accessToken?.trim() || '',
    ...(next.projectId ? { projectId: next.projectId } : {}),
  }
}

async function refreshOpenAICodexOAuthCredential(oauth: LocalOAuthCredential): Promise<LocalOAuthCredential> {
  const refreshToken = oauth.refreshToken?.trim()
  if (!refreshToken) throw new Error('OpenAI Codex OAuth refresh token is missing. Reconnect OpenAI Codex.')

  const oauthModule = await importOpenAICodexOAuthModule()
  const refreshed = await oauthModule.refreshOpenAICodexToken(refreshToken)
  return {
    ...oauth,
    accessToken: refreshed.access,
    refreshToken: refreshed.refresh || oauth.refreshToken,
    expiresAt: refreshed.expires,
    tokenType: 'Bearer',
    scope: oauth.scope || OPENAI_CODEX_OAUTH_SCOPES,
    ...(refreshed.accountId ? { accountId: refreshed.accountId } : {}),
    ...(refreshed.idToken ? { idToken: refreshed.idToken } : {}),
  }
}

async function resolveOpenAICodexOAuthForRequest(): Promise<{ accessToken: string } | null> {
  const stored = localAuthStore.providers['openai-codex']?.oauth || localOAuthFromMainAuthProfile('openai-codex') || undefined
  if (!isOAuthCredentialUsable(stored)) return null

  const accessToken = stored.accessToken?.trim()
  const expiresAt = stored.expiresAt || 0
  if (accessToken && (!expiresAt || expiresAt > Date.now() + 60000)) {
    return { accessToken }
  }

  const refreshed = await refreshOpenAICodexOAuthCredential(stored)
  await persistProviderOAuth('openai-codex', refreshed)
  const next = localAuthStore.providers['openai-codex']?.oauth || refreshed
  const nextAccessToken = next.accessToken?.trim() || refreshed.accessToken?.trim()
  return nextAccessToken ? { accessToken: nextAccessToken } : null
}

async function resolveProviderRequestAuth(
  provider: string,
  env: Record<string, string>,
  envKeys: string[],
): Promise<ProviderRequestAuth | null> {
  if (provider === 'google-vertex') {
    return resolveGoogleVertexRequestAuth(env)
  }

  const localMode = localAuthStore.providers[provider]?.mode
  if (provider === 'google' && localMode === 'oauth') {
    const oauth = await resolveGoogleOAuthForRequest().catch(() => null)
    if (oauth?.accessToken) {
      return { type: 'oauth', accessToken: oauth.accessToken, ...(oauth.projectId ? { projectId: oauth.projectId } : {}), source: 'local-oauth' }
    }
  }

  if (provider === 'openai-codex') {
    const oauth = await resolveOpenAICodexOAuthForRequest().catch(() => null)
    if (oauth?.accessToken) return { type: 'oauth', accessToken: oauth.accessToken, source: 'local-oauth' }
    return null
  }

  const apiKey = resolveEnvValue(env, envKeys)
  if (apiKey) return { type: 'apiKey', value: apiKey, source: 'api-key' }

  if (provider === 'google') {
    const oauth = await resolveGoogleOAuthForRequest().catch(() => null)
    if (oauth?.accessToken) {
      return { type: 'oauth', accessToken: oauth.accessToken, ...(oauth.projectId ? { projectId: oauth.projectId } : {}), source: 'local-oauth' }
    }
  }

  return null
}

async function resolveOpenAiSubscriptionRequestAuth(env: Record<string, string>) {
  const codexOAuth = await resolveOpenAICodexOAuthForRequest().catch(() => null)
  if (codexOAuth?.accessToken) {
    return {
      provider: 'openai-codex',
      providerConfig: STREAMING_PROVIDER_CONFIG['openai-codex'],
      requestAuth: { type: 'oauth', accessToken: codexOAuth.accessToken, source: 'local-openai-codex-oauth' } as ProviderRequestAuth,
    }
  }

  const openAiProviderConfig = STREAMING_PROVIDER_CONFIG.openai
  const openAiApiAuth = await resolveProviderRequestAuth('openai', env, openAiProviderConfig.envKeys)
  return {
    provider: openAiApiAuth ? 'openai' : 'openai-codex',
    providerConfig: openAiApiAuth ? openAiProviderConfig : STREAMING_PROVIDER_CONFIG['openai-codex'],
    requestAuth: openAiApiAuth,
  }
}

async function openExternalAuthUrl(url: string) {
  if (process.platform === 'win32') return spawnDetached('rundll32.exe', ['url.dll,FileProtocolHandler', url])
  if (process.platform === 'darwin') return spawnDetached('open', [url])
  return spawnDetached('xdg-open', [url])
}

async function ensureGoogleOAuthCallbackServer() {
  if (googleOAuthCallbackServer?.listening) return
  if (googleOAuthCallbackServerStarting) return googleOAuthCallbackServerStarting

  googleOAuthCallbackServerStarting = new Promise((resolve, reject) => {
    const server = createServer(async (req, res) => {
      try {
        const requestUrl = new URL(req.url || '/', GOOGLE_OAUTH_REDIRECT_URI)
        if (requestUrl.pathname !== '/oauth2callback') {
          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' })
          res.end('Not found')
          return
        }

        const state = requestUrl.searchParams.get('state') || ''
        const code = requestUrl.searchParams.get('code') || ''
        const error = requestUrl.searchParams.get('error') || ''
        const session = Array.from(oauthSessions.values()).find((entry) => entry.state === state)
        if (!session) {
          res.writeHead(400, { 'Content-Type': 'text/html; charset=utf-8' })
          res.end('<h1>OAuth session not found</h1><p>Return to DystopAI and start the connection again.</p>')
          return
        }

        if (error) throw new Error(error)
        if (!code) throw new Error('Google did not return an authorization code.')

        if (!session.verifier) throw new Error('Google OAuth verifier missing. Restart the connection.')
        const credential = await exchangeGoogleOAuthCodeForTokens(code, session.verifier, session.projectId)
        await persistProviderOAuth('google', credential)
        session.status = 'complete'
        session.completedAt = new Date().toISOString()
        session.result = {
          ...(credential.email ? { email: credential.email } : {}),
          ...(credential.projectId ? { projectId: credential.projectId } : {}),
          ...(credential.expiresAt ? { expiresAt: credential.expiresAt } : {}),
        }

        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' })
        res.end('<h1>Google connected</h1><p>You can close this window and return to DystopAI.</p>')
      } catch (err) {
        const message = String(err)
        const state = new URL(req.url || '/', GOOGLE_OAUTH_REDIRECT_URI).searchParams.get('state') || ''
        const session = Array.from(oauthSessions.values()).find((entry) => entry.state === state)
        if (session) {
          session.status = 'error'
          session.error = message
          session.completedAt = new Date().toISOString()
        }
        res.writeHead(500, { 'Content-Type': 'text/html; charset=utf-8' })
        res.end(`<h1>Google connection failed</h1><p>${message.replace(/[<>&]/g, (char) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' })[char] || char)}</p>`)
      }
    })

    server.once('error', (error) => {
      googleOAuthCallbackServerStarting = null
      reject(error)
    })
    server.listen(8085, '127.0.0.1', () => {
      googleOAuthCallbackServer = server
      googleOAuthCallbackServerStarting = null
      resolve()
    })
  })

  return googleOAuthCallbackServerStarting
}

async function startGoogleOAuthSession(projectId?: string) {
  const id = randomUUID()
  const state = randomBytes(24).toString('base64url')
  const { verifier, challenge } = generatePkcePair()
  const authorizationUrl = buildGoogleOAuthAuthorizationUrl(challenge, state)
  const session: OAuthSession = {
    id,
    provider: 'google',
    state,
    verifier,
    challenge,
    authorizationUrl,
    status: 'pending',
    createdAt: new Date().toISOString(),
    ...(resolveGoogleProjectId(projectId) ? { projectId: resolveGoogleProjectId(projectId) } : {}),
  }
  oauthSessions.set(id, session)
  await ensureGoogleOAuthCallbackServer()
  const launched = await openExternalAuthUrl(authorizationUrl).catch((error) => ({ ok: false, detail: String(error) }))
  return { session, launched }
}

function escapeHtml(value: string) {
  return value.replace(/[<>&]/g, (char) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' })[char] || char)
}

function parseOpenAICodexAuthorizationInput(input: string): { code: string; state?: string } {
  const trimmed = input.trim()
  if (!trimmed) throw new Error('Authorization code is empty.')

  const fromSearchParams = (params: URLSearchParams) => {
    const code = params.get('code')?.trim()
    const state = params.get('state')?.trim()
    return code ? { code, ...(state ? { state } : {}) } : null
  }

  try {
    const parsed = fromSearchParams(new URL(trimmed).searchParams)
    if (parsed) return parsed
  } catch {
    // Plain codes and query-string fragments are handled below.
  }

  if (trimmed.includes('code=') || trimmed.includes('state=')) {
    const parsed = fromSearchParams(new URLSearchParams(trimmed.replace(/^\?/, '')))
    if (parsed) return parsed
  }

  return { code: trimmed }
}

function resolveOpenAICodexAccountIdFromAccessToken(accessToken: string) {
  const parts = accessToken.split('.')
  if (parts.length !== 3) return undefined
  try {
    const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf-8')) as Record<string, unknown>
    const auth = payload['https://api.openai.com/auth'] as Record<string, unknown> | undefined
    const accountId = auth?.chatgpt_account_id
    return typeof accountId === 'string' && accountId.trim() ? accountId.trim() : undefined
  } catch {
    return undefined
  }
}

async function completeOpenAICodexOAuthSession(session: OAuthSession, code: string, state?: string) {
  if (session.status !== 'pending') throw new Error(`OAuth session is already ${session.status}.`)
  if (!session.verifier) throw new Error('OpenAI Codex OAuth verifier missing. Restart the connection.')
  if (state && session.state && state !== session.state) throw new Error('State mismatch')

  const oauthModule = await importOpenAICodexOAuthModule()
  const testing = openAICodexOAuthTesting(oauthModule)
  const result = await testing.exchangeAuthorizationCode(code, session.verifier, session.redirectUri || OPENAI_CODEX_OAUTH_REDIRECT_URI)
  if (result.type !== 'success') throw new Error(result.message || 'OpenAI Codex token exchange failed.')

  const accountId = resolveOpenAICodexAccountIdFromAccessToken(result.access)
  const credential: LocalOAuthCredential = {
    accessToken: result.access,
    refreshToken: result.refresh,
    expiresAt: result.expires,
    tokenType: 'Bearer',
    scope: OPENAI_CODEX_OAUTH_SCOPES,
    ...(accountId ? { accountId } : {}),
  }
  await persistProviderOAuth('openai-codex', credential)
  session.status = 'complete'
  session.manualInputRequired = false
  session.completedAt = new Date().toISOString()
  session.result = {
    ...(credential.accountId ? { accountId: credential.accountId } : {}),
    ...(credential.expiresAt ? { expiresAt: credential.expiresAt } : {}),
  }
  return credential
}

async function ensureOpenAICodexOAuthCallbackServer() {
  if (openAICodexOAuthCallbackServer?.listening) return
  if (openAICodexOAuthCallbackServerStarting) return openAICodexOAuthCallbackServerStarting

  openAICodexOAuthCallbackServerStarting = new Promise((resolve, reject) => {
    const server = createServer(async (req, res) => {
      try {
        const requestUrl = new URL(req.url || '/', OPENAI_CODEX_OAUTH_REDIRECT_URI)
        if (requestUrl.pathname !== '/auth/callback') {
          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' })
          res.end('Not found')
          return
        }

        const state = requestUrl.searchParams.get('state') || ''
        const code = requestUrl.searchParams.get('code') || ''
        const error = requestUrl.searchParams.get('error') || ''
        const session = Array.from(oauthSessions.values()).find(
          (entry) => entry.provider === 'openai-codex' && entry.state === state,
        )
        if (!session) {
          res.writeHead(400, { 'Content-Type': 'text/html; charset=utf-8' })
          res.end('<h1>OAuth session not found</h1><p>Return to DystopAI and start the connection again.</p>')
          return
        }

        if (error) throw new Error(error)
        if (!code) throw new Error('OpenAI did not return an authorization code.')

        await completeOpenAICodexOAuthSession(session, code, state)
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' })
        res.end('<h1>OpenAI Codex connected</h1><p>You can close this window and return to DystopAI.</p>')
      } catch (err) {
        const message = String(err)
        const state = new URL(req.url || '/', OPENAI_CODEX_OAUTH_REDIRECT_URI).searchParams.get('state') || ''
        const session = Array.from(oauthSessions.values()).find(
          (entry) => entry.provider === 'openai-codex' && entry.state === state,
        )
        if (session) {
          session.status = 'error'
          session.error = message
          session.completedAt = new Date().toISOString()
        }
        res.writeHead(500, { 'Content-Type': 'text/html; charset=utf-8' })
        res.end(`<h1>OpenAI Codex connection failed</h1><p>${escapeHtml(message)}</p>`)
      }
    })

    server.once('error', (error) => {
      openAICodexOAuthCallbackServerStarting = null
      reject(error)
    })
    server.listen(1455, () => {
      openAICodexOAuthCallbackServer = server
      openAICodexOAuthCallbackServerStarting = null
      resolve()
    })
  })

  return openAICodexOAuthCallbackServerStarting
}

async function startOpenAICodexOAuthSession() {
  const id = randomUUID()
  const oauthModule = await importOpenAICodexOAuthModule()
  const flow = await openAICodexOAuthTesting(oauthModule).createAuthorizationFlow('dystopai')
  const session: OAuthSession = {
    id,
    provider: 'openai-codex',
    state: flow.state,
    verifier: flow.verifier,
    redirectUri: flow.redirectUri,
    authorizationUrl: flow.url,
    status: 'pending',
    manualInputRequired: true,
    manualPrompt: 'Complete sign-in in the browser. If OpenAI shows a code or localhost redirect URL, paste it here.',
    createdAt: new Date().toISOString(),
  }
  oauthSessions.set(id, session)
  await ensureOpenAICodexOAuthCallbackServer()
  const launched = await openExternalAuthUrl(flow.url).catch((error) => ({ ok: false, detail: String(error) }))
  return { session, launched }
}

function writeSseEvent(res: { write: (chunk: string) => unknown }, event: string, data: Record<string, unknown>) {
  res.write(`event: ${event}\n`)
  res.write(`data: ${JSON.stringify(data)}\n\n`)
}

function splitTextForSse(text: string, chunkSize = SSE_DELTA_CHUNK_CHARS) {
  const chunks: string[] = []
  for (let index = 0; index < text.length;) {
    let end = Math.min(index + chunkSize, text.length)
    const lastCode = text.charCodeAt(end - 1)
    if (end < text.length && lastCode >= 0xd800 && lastCode <= 0xdbff) end -= 1
    chunks.push(text.slice(index, end))
    index = end
  }
  return chunks.length ? chunks : ['']
}

function compactSseText(value: string, liveTextStreamed: boolean, field = '') {
  if (liveTextStreamed && field !== 'reply') return ''
  return value.length > SSE_FINAL_TEXT_LIMIT ? `${value.slice(0, SSE_FINAL_TEXT_LIMIT).trimEnd()}\n\n[Response truncated in final SSE metadata; streamed text was already delivered.]` : value
}

function compactFinalSsePayload(payload: Record<string, unknown>, liveTextStreamed: boolean): Record<string, unknown> {
  const next: Record<string, unknown> = { ...payload }
  const truncatedFields: string[] = []
  const sanitizedFields: string[] = []

  for (const field of ['reply', 'stdout', 'stderr', 'error', 'detail']) {
    const value = next[field]
    if (typeof value !== 'string') continue
    const visible = field === 'reply' || field === 'error' || field === 'detail'
      ? sanitizeUserVisibleRuntimeText(value) || (field === 'reply' ? 'No response returned.' : '')
      : value
    if (visible !== value) sanitizedFields.push(field)
    const compacted = compactSseText(visible, liveTextStreamed, field)
    if (compacted !== value) truncatedFields.push(field)
    next[field] = compacted
  }

  if (sanitizedFields.length) {
    next.runtimeLogsFiltered = true
    next.runtimeLogsFilteredFields = sanitizedFields
  }

  if (truncatedFields.length) {
    next.sseCompacted = true
    next.sseCompactedFields = truncatedFields
  }

  return next
}

function compactHttpJsonPayload(payload: Record<string, unknown>): Record<string, unknown> {
  const next: Record<string, unknown> = { ...payload }
  const compactedFields: string[] = []
  const sanitizedFields: string[] = []

  for (const field of ['reply', 'stdout', 'stderr', 'error', 'detail']) {
    const value = next[field]
    if (typeof value !== 'string') continue
    const visible = field === 'reply' || field === 'error' || field === 'detail'
      ? sanitizeUserVisibleRuntimeText(value) || (field === 'reply' ? 'No response returned.' : '')
      : value
    if (visible !== value) sanitizedFields.push(field)
    if (visible.length > SSE_FINAL_TEXT_LIMIT) {
      next[field] = `${visible.slice(0, SSE_FINAL_TEXT_LIMIT).trimEnd()}\n\n[Response truncated for HTTP payload.]`
      compactedFields.push(field)
    } else {
      next[field] = visible
    }
  }

  if (sanitizedFields.length) {
    next.runtimeLogsFiltered = true
    next.runtimeLogsFilteredFields = sanitizedFields
  }

  if (compactedFields.length) {
    next.compacted = true
    next.compactedFields = compactedFields
  }

  return next
}

function initializeSseResponse(res: {
  writeHead: (status: number, headers: Record<string, string>) => unknown
  write: (chunk: string) => unknown
  flushHeaders?: () => void
}) {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream; charset=utf-8',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  })
  res.write(': connected\n\n')
  res.flushHeaders?.()
}

const CLAWTALK_CONSOLE_EVENT_LIMIT = 200

type ClawTalkConsoleMirrorContext = {
  clawTalkRunId: string
  agentId: string
  sessionKey: string
  prompt: string
  terminalEmitted?: boolean
  updatedAt?: number
}

const clawTalkConsoleEvents: Array<Record<string, unknown>> = []
const clawTalkConsoleClients = new Map<string, { write: (chunk: string) => unknown; closed: boolean }>()
const clawTalkConsoleMirrorsBySessionKey = new Map<string, ClawTalkConsoleMirrorContext>()
const CLAWTALK_CONSOLE_MIRROR_TTL_MS = 10 * 60 * 1000

function compactClawTalkConsoleValue(value: string, maxChars = SSE_FINAL_TEXT_LIMIT) {
  const visible = redactHiddenReasoningAndSecrets(sanitizeUserVisibleRuntimeText(value))
  return visible.length > maxChars ? `${visible.slice(0, maxChars).trimEnd()}\n\n[ClawTalk console event truncated.]` : visible
}

function normalizeClawTalkConsoleFrame(event: string, context: ClawTalkConsoleMirrorContext, data: Record<string, unknown>) {
  const normalized: Record<string, unknown> = {
    ...data,
    id: randomUUID(),
    source: 'clawtalk',
    event,
    clawTalkRunId: context.clawTalkRunId,
    agentId: context.agentId,
    sessionKey: context.sessionKey,
    prompt: context.prompt,
    timestamp: new Date().toISOString(),
    transport: typeof data.transport === 'string' && data.transport.trim() ? data.transport : 'clawtalk-control-center',
  }
  for (const field of ['text', 'reply', 'message', 'error', 'detail']) {
    const value = normalized[field]
    if (typeof value === 'string') normalized[field] = compactClawTalkConsoleValue(value)
  }
  return normalized
}

function cleanupClawTalkConsoleMirrors() {
  const cutoff = Date.now() - CLAWTALK_CONSOLE_MIRROR_TTL_MS
  for (const [key, context] of clawTalkConsoleMirrorsBySessionKey) {
    if ((context.updatedAt || 0) < cutoff) clawTalkConsoleMirrorsBySessionKey.delete(key)
  }
}

function rememberClawTalkConsoleMirror(context: ClawTalkConsoleMirrorContext) {
  context.updatedAt = Date.now()
  cleanupClawTalkConsoleMirrors()
  clawTalkConsoleMirrorsBySessionKey.set(context.sessionKey, context)
}

function resolveClawTalkConsoleMirrorContext(input: { agentId: string; sessionKey: string; prompt?: string }) {
  cleanupClawTalkConsoleMirrors()
  const existing = clawTalkConsoleMirrorsBySessionKey.get(input.sessionKey)
  if (existing) {
    existing.updatedAt = Date.now()
    if (input.prompt?.trim()) existing.prompt = input.prompt.trim()
    return existing
  }

  const context: ClawTalkConsoleMirrorContext = {
    clawTalkRunId: randomUUID(),
    agentId: input.agentId,
    sessionKey: input.sessionKey,
    prompt: input.prompt?.trim() || 'ClawTalk message',
    updatedAt: Date.now(),
  }
  clawTalkConsoleMirrorsBySessionKey.set(input.sessionKey, context)
  return context
}

function emitClawTalkConsoleFrame(event: string, context: ClawTalkConsoleMirrorContext, data: Record<string, unknown>) {
  const finalOverride = event === 'final' &&
    context.terminalEmitted &&
    data.consoleBridgeFinal === true &&
    data.ok !== false &&
    typeof (data.reply || data.text) === 'string' &&
    String(data.reply || data.text).trim().length > 0
  if (event === 'final' && context.terminalEmitted && !finalOverride) return false
  context.updatedAt = Date.now()
  const payload = normalizeClawTalkConsoleFrame(event, context, data)
  if (event === 'final') context.terminalEmitted = true
  clawTalkConsoleEvents.unshift(payload)
  if (clawTalkConsoleEvents.length > CLAWTALK_CONSOLE_EVENT_LIMIT) {
    clawTalkConsoleEvents.length = CLAWTALK_CONSOLE_EVENT_LIMIT
  }
  for (const [id, client] of clawTalkConsoleClients) {
    if (client.closed) {
      clawTalkConsoleClients.delete(id)
      continue
    }
    try {
      writeSseEvent(client, event, payload)
    } catch {
      client.closed = true
      clawTalkConsoleClients.delete(id)
    }
  }
  return true
}

function parseSseFrames(buffer: string): { frames: Array<{ event?: string; data: string }>; rest: string } {
  const normalized = buffer.replace(/\r\n/g, '\n')
  const frames: Array<{ event?: string; data: string }> = []
  let cursor = 0
  while (true) {
    const boundary = normalized.indexOf('\n\n', cursor)
    if (boundary === -1) break
    const rawFrame = normalized.slice(cursor, boundary)
    cursor = boundary + 2
    const dataLines: string[] = []
    let event: string | undefined
    for (const line of rawFrame.split('\n')) {
      if (line.startsWith('event:')) event = line.slice(6).trim()
      if (line.startsWith('data:')) dataLines.push(line.slice(5).trimStart())
    }
    if (dataLines.length) frames.push({ event, data: dataLines.join('\n') })
  }
  return { frames, rest: normalized.slice(cursor) }
}

async function readUpstreamSse(
  response: globalThis.Response,
  onFrame: (frame: { event?: string; data: string }) => void | false,
) {
  if (!response.body) throw new Error('Streaming response did not include a body.')
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let buffer = ''
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buffer += decoder.decode(value, { stream: true })
    if (buffer.length > UPSTREAM_SSE_BUFFER_LIMIT_CHARS) {
      await reader.cancel().catch(() => undefined)
      throw new Error(`Streaming response frame exceeded ${UPSTREAM_SSE_BUFFER_LIMIT_CHARS} chars without an SSE boundary.`)
    }
    const parsed = parseSseFrames(buffer)
    buffer = parsed.rest
    for (const frame of parsed.frames) {
      if (onFrame(frame) === false) {
        await reader.cancel().catch(() => undefined)
        return
      }
    }
  }
  buffer += decoder.decode()
  const parsed = parseSseFrames(`${buffer}\n\n`)
  for (const frame of parsed.frames) {
    if (onFrame(frame) === false) return
  }
}

async function assertUpstreamOk(response: globalThis.Response, provider: string) {
  if (response.ok) return
  const detail = await response.text().catch(() => '')
  throw new Error(`${provider} streaming request failed (${response.status}): ${trimTask(detail || response.statusText, 600)}`)
}

function effortForThinking(thinking: Exclude<ThinkingLevel, 'off'>): 'low' | 'medium' | 'high' {
  if (thinking === 'high') return 'high'
  if (thinking === 'medium') return 'medium'
  return 'low'
}

function deepSeekThinkingPatch(thinking: ThinkingLevel) {
  if (thinking === 'high') return { thinking: { type: 'enabled' }, reasoning_effort: 'high' }
  if (thinking === 'medium') return { thinking: { type: 'enabled' }, reasoning_effort: 'medium' }
  if (thinking === 'minimal' || thinking === 'low') return { thinking: { type: 'enabled' }, reasoning_effort: 'low' }
  return { thinking: { type: 'disabled' } }
}

function isOpenAiReasoningModel(model: string) {
  const normalized = model.toLowerCase()
  return /^(gpt-5|o[1-9]|gpt-oss)/.test(normalized)
}

function parsedOpenAiGpt5Minor(model: string): number | null {
  const match = model.toLowerCase().match(/^gpt-5(?:\.(\d+))?/)
  if (!match) return null
  return match[1] ? Number(match[1]) : 0
}

function openAiSupportsReasoningNone(model: string) {
  const minor = parsedOpenAiGpt5Minor(model)
  return minor !== null && minor >= 1
}

function openAiSupportsMinimalReasoning(model: string) {
  const minor = parsedOpenAiGpt5Minor(model)
  return minor !== null && minor >= 2
}

function openAiReasoningPatch(model: string, thinking: ThinkingLevel) {
  if (!isOpenAiReasoningModel(model)) return {}
  if (thinking === 'off') {
    return openAiSupportsReasoningNone(model) ? { reasoning_effort: 'none' } : {}
  }
  if (thinking === 'minimal') {
    return { reasoning_effort: openAiSupportsMinimalReasoning(model) ? 'minimal' : 'low' }
  }
  return { reasoning_effort: thinking }
}

function openAiResponsesReasoningPatch(model: string, thinking: ThinkingLevel) {
  if (!isOpenAiReasoningModel(model)) return {}
  if (thinking === 'off') {
    return openAiSupportsReasoningNone(model) ? { reasoning: { effort: 'none' } } : {}
  }
  if (thinking === 'minimal') {
    return { reasoning: { effort: openAiSupportsMinimalReasoning(model) ? 'minimal' : 'low' } }
  }
  return { reasoning: { effort: thinking } }
}

function openAiCompatibleThinkingPatch(provider: string, model: string, thinking: ThinkingLevel) {
  if (provider === 'deepseek') return deepSeekThinkingPatch(thinking)
  if (provider === 'openai') return openAiReasoningPatch(model, thinking)
  return {}
}

function toOpenAiCompatibleMessages(provider: string, messages: ProviderConversationMessage[]) {
  return messages.map((message) => {
    const payload: Record<string, string> = {
      role: message.role,
      content: message.content,
    }
    if (provider === 'deepseek' && message.role === 'assistant' && message.reasoningContent) {
      payload.reasoning_content = message.reasoningContent
    }
    return payload
  })
}

function toOpenAiResponsesInput(messages: ProviderConversationMessage[]) {
  return messages.map((message) => ({
    role: message.role,
    content: message.content,
  }))
}

function textFromOpenAiResponsesResponse(response: unknown) {
  if (!isLooseRecord(response) || !Array.isArray(response.output)) return ''
  const parts: string[] = []
  for (const item of response.output) {
    if (!isLooseRecord(item) || !Array.isArray(item.content)) continue
    for (const content of item.content) {
      if (!isLooseRecord(content)) continue
      const type = typeof content.type === 'string' ? content.type : ''
      const text = typeof content.text === 'string' ? content.text : ''
      if (text && (type === 'output_text' || type === 'text')) parts.push(text)
    }
  }
  return parts.join('')
}

function openAiResponsesStreamErrorMessage(payload: Record<string, unknown>, fallback: string) {
  const errorMessage = (error: unknown) => {
    if (typeof error === 'string' && error.trim()) return error.trim()
    if (!isLooseRecord(error)) return ''
    const message = typeof error.message === 'string' ? error.message.trim() : ''
    if (message) return message
    const code = typeof error.code === 'string' ? error.code.trim() : ''
    const type = typeof error.type === 'string' ? error.type.trim() : ''
    return [type, code].filter(Boolean).join(': ')
  }

  const error = payload.error
  const topLevelError = errorMessage(error)
  if (topLevelError) return topLevelError

  const response = payload.response
  const responseError = isLooseRecord(response) ? errorMessage(response.error) : ''
  if (responseError) return responseError

  const message = typeof payload.message === 'string' ? payload.message.trim() : ''
  return message || fallback
}

function toAnthropicMessages(messages: ProviderConversationMessage[]) {
  return messages.map((message) => ({
    role: message.role,
    content: message.content,
  }))
}

function toGeminiContents(messages: ProviderConversationMessage[]) {
  return messages.map((message) => ({
    role: message.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: message.content }],
  }))
}

function anthropicSupportsAdaptiveThinking(model: string) {
  const normalized = model.toLowerCase()
  return (
    /claude-opus-4-(6|7|8)\b/.test(normalized) ||
    /claude-sonnet-4-6\b/.test(normalized) ||
    /claude-mythos/.test(normalized)
  )
}

function anthropicSupportsEffort(model: string) {
  const normalized = model.toLowerCase()
  return (
    anthropicSupportsAdaptiveThinking(model) ||
    /claude-opus-4-5\b/.test(normalized)
  )
}

function anthropicSupportsManualThinking(model: string) {
  const normalized = model.toLowerCase()
  if (/claude-opus-4-(7|8)\b/.test(normalized) || /claude-mythos/.test(normalized)) return false
  return /claude-(sonnet-3-7|sonnet-4|opus-4|haiku-4-5)\b/.test(normalized)
}

function anthropicThinkingBudget(thinking: Exclude<ThinkingLevel, 'off'>) {
  if (thinking === 'high') return 4096
  if (thinking === 'medium') return 2048
  return 1024
}

function anthropicMaxTokens(thinking: ThinkingLevel) {
  if (thinking === 'high') return 8192
  if (thinking === 'medium') return 6144
  return 4096
}

function anthropicReasoningPatch(model: string, thinking: ThinkingLevel) {
  if (thinking === 'off') return {}

  const effort = effortForThinking(thinking)
  const patch: Record<string, unknown> = {}
  if (anthropicSupportsEffort(model)) {
    patch.output_config = { effort }
  }
  if (anthropicSupportsAdaptiveThinking(model)) {
    patch.thinking = { type: 'adaptive' }
  } else if (anthropicSupportsManualThinking(model)) {
    patch.thinking = { type: 'enabled', budget_tokens: anthropicThinkingBudget(thinking) }
  }
  return patch
}

function geminiThinkingBudget(model: string, thinking: ThinkingLevel) {
  const normalized = model.toLowerCase()
  const isPro = /gemini-2\.5-pro/.test(normalized)
  if (thinking === 'off' || thinking === 'minimal') return isPro ? 128 : 0
  if (thinking === 'high') return 8192
  if (thinking === 'medium') return 4096
  return 1024
}

function geminiThinkingConfig(model: string, thinking: ThinkingLevel) {
  const normalized = model.toLowerCase()
  if (/gemini-2\.5/.test(normalized)) {
    return { thinkingBudget: geminiThinkingBudget(model, thinking) }
  }
  if (/gemini-3(?:\.\d+)?-flash/.test(normalized)) {
    return { thinkingLevel: thinking === 'off' ? 'minimal' : thinking }
  }
  if (/gemini-(3|4|5)/.test(normalized)) {
    return { thinkingLevel: thinking === 'off' ? 'minimal' : thinking }
  }
  return undefined
}

async function streamOpenAiCompatibleCompletion(params: {
  provider: string
  model: string
  endpoint: string
  apiKey: string
  messages: ProviderConversationMessage[]
  thinking: ThinkingLevel
  signal: AbortSignal
  emit: StreamEmitter
}) {
  const body: Record<string, unknown> = {
    model: params.model,
    messages: toOpenAiCompatibleMessages(params.provider, params.messages),
    stream: true,
  }
  Object.assign(body, openAiCompatibleThinkingPatch(params.provider, params.model, params.thinking))
  const upstream = await fetch(params.endpoint, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${params.apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
    signal: params.signal,
  })
  await assertUpstreamOk(upstream, params.provider)
  let reply = ''
  let reasoningContent = ''
  await readUpstreamSse(upstream, (frame) => {
    if (frame.data === '[DONE]') return
    try {
      const payload = JSON.parse(frame.data) as {
        choices?: Array<{ delta?: { content?: string | null; reasoning_content?: string | null } }>
      }
      const reasoning = payload.choices?.[0]?.delta?.reasoning_content || ''
      if (reasoning) reasoningContent += reasoning
      const text = payload.choices?.[0]?.delta?.content || ''
      if (!text) return
      reply += text
      params.emit('delta', { text: redactHiddenReasoningAndSecrets(text) })
    } catch {
      // Ignore malformed upstream frames; provider streams can include keepalive noise.
    }
  })
  return { content: reply, reasoningContent: reasoningContent || undefined }
}

async function streamOpenAiResponsesCompletion(params: {
  provider: string
  model: string
  endpoint: string
  apiKey: string
  messages: ProviderConversationMessage[]
  thinking: ThinkingLevel
  signal: AbortSignal
  emit: StreamEmitter
}) {
  const body: Record<string, unknown> = {
    model: params.model,
    input: toOpenAiResponsesInput(params.messages),
    stream: true,
    store: false,
  }
  Object.assign(body, openAiResponsesReasoningPatch(params.model, params.thinking))
  const upstream = await fetch(params.endpoint, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${params.apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
    signal: params.signal,
  })
  await assertUpstreamOk(upstream, params.provider)

  let reply = ''
  let finalText = ''
  let reasoningContent = ''
  let completedResponse: unknown
  await readUpstreamSse(upstream, (frame) => {
    if (frame.data === '[DONE]') return
    let payload: unknown
    try {
      payload = JSON.parse(frame.data) as unknown
    } catch {
      return
    }
    if (!isLooseRecord(payload)) return

    const type = typeof payload.type === 'string' ? payload.type : frame.event || ''
    if (type === 'response.output_text.delta') {
      const text = typeof payload.delta === 'string' ? payload.delta : ''
      if (!text) return
      reply += text
      params.emit('delta', { text: redactHiddenReasoningAndSecrets(text) })
      return
    }
    if (type === 'response.output_text.done') {
      const text = typeof payload.text === 'string' ? payload.text : ''
      if (text) finalText = text
      return
    }
    if (type === 'response.refusal.delta') {
      const text = typeof payload.delta === 'string' ? payload.delta : ''
      if (!text) return
      reply += text
      params.emit('delta', { text: redactHiddenReasoningAndSecrets(text) })
      return
    }
    if (type === 'response.refusal.done') {
      const text = typeof payload.refusal === 'string' ? payload.refusal : ''
      if (text) finalText = text
      return
    }
    if (type === 'response.reasoning_text.delta' || type === 'response.reasoning_summary_text.delta') {
      const text = typeof payload.delta === 'string' ? payload.delta : ''
      if (text) reasoningContent += text
      return
    }
    if (type === 'response.completed') {
      completedResponse = payload.response
      return
    }
    if (type === 'response.failed' || type === 'error') {
      throw new Error(openAiResponsesStreamErrorMessage(payload, 'OpenAI Responses streaming failed.'))
    }
  })

  const finalReply = reply || finalText || textFromOpenAiResponsesResponse(completedResponse)
  return { content: finalReply, reasoningContent: reasoningContent || undefined }
}

type OpenAICodexModel = {
  id: string
  name: string
  api: 'openai-chatgpt-responses'
  provider: 'openai'
  baseUrl: string
  reasoning: boolean
  input: string[]
  cost: {
    input: number
    output: number
    cacheRead: number
    cacheWrite: number
  }
  contextWindow: number
  maxTokens: number
  headers?: Record<string, string>
  thinkingLevelMap?: Record<string, string | null>
}

type PiAiAssistantMessage = {
  content?: Array<{ type?: string; text?: string; thinking?: string }>
  errorMessage?: string
}

type PiAiAssistantMessageEvent = {
  type: string
  delta?: string
  content?: string
  message?: PiAiAssistantMessage
  error?: PiAiAssistantMessage
}

function fallbackOpenAICodexModel(model: string): OpenAICodexModel {
  return {
    id: model,
    name: model,
    api: 'openai-chatgpt-responses',
    provider: 'openai',
    baseUrl: 'https://chatgpt.com/backend-api',
    reasoning: true,
    input: ['text'],
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: 272000,
    maxTokens: 128000,
  }
}

async function resolveOpenAICodexModel(model: string): Promise<OpenAICodexModel> {
  return fallbackOpenAICodexModel(model)
}

function toOpenAICodexContext(
  provider: string,
  model: string,
  messages: ProviderConversationMessage[],
) {
  const now = Date.now()
  return {
    systemPrompt: [
      'You are a DystopAI direct streaming agent.',
      'Answer the user directly and concisely.',
      'This direct streaming path has no filesystem, terminal, browser, or app-control tools.',
      'If the request requires tools or workspace edits, state the specific missing tool action without telling the user to send a slash command.',
    ].join('\n'),
    messages: messages.map((message, index) => {
      const timestamp = now - (messages.length - index)
      if (message.role === 'user') {
        return {
          role: 'user',
          content: message.content,
          timestamp,
        }
      }
      return {
        role: 'assistant',
        content: [{ type: 'text', text: message.content }],
        api: 'openai-chatgpt-responses',
        provider,
        model,
        usage: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
          totalTokens: 0,
          cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
        },
        stopReason: 'stop',
        timestamp,
      }
    }),
  }
}

function openAICodexReasoningEffort(thinking: ThinkingLevel): 'none' | 'minimal' | 'low' | 'medium' | 'high' {
  if (thinking === 'off') return 'none'
  return thinking
}

function textFromPiAiAssistantMessage(message?: PiAiAssistantMessage) {
  return (message?.content || [])
    .map((block) => (block.type === 'text' ? block.text || '' : ''))
    .filter(Boolean)
    .join('')
}

function reasoningFromPiAiAssistantMessage(message?: PiAiAssistantMessage) {
  return (message?.content || [])
    .map((block) => (block.type === 'thinking' ? block.thinking || '' : ''))
    .filter(Boolean)
    .join('\n\n')
}

async function streamOpenAICodexResponsesCompletion(params: {
  model: string
  accessToken: string
  messages: ProviderConversationMessage[]
  thinking: ThinkingLevel
  sessionId: string
  signal: AbortSignal
  emit: StreamEmitter
}) {
  const providerPath = openClawDistModulePathByPrefix('openai-chatgpt-responses-')
  const providerModule = await import(pathToFileURL(providerPath).href) as {
    streamOpenAICodexResponses: (
      model: OpenAICodexModel,
      context: ReturnType<typeof toOpenAICodexContext>,
      options: Record<string, unknown>,
    ) => AsyncIterable<PiAiAssistantMessageEvent>
  }
  const codexModel = await resolveOpenAICodexModel(params.model)
  const context = toOpenAICodexContext('openai', params.model, params.messages)
  const stream = providerModule.streamOpenAICodexResponses(codexModel, context, {
    apiKey: params.accessToken,
    signal: params.signal,
    sessionId: params.sessionId,
    transport: 'sse',
    reasoningEffort: openAICodexReasoningEffort(params.thinking),
    reasoningSummary: 'auto',
    textVerbosity: 'low',
  })

  let reply = ''
  let finalMessage: PiAiAssistantMessage | undefined
  for await (const event of stream) {
    if (params.signal.aborted) throw new Error('Request was aborted')
    if (event.type === 'text_delta') {
      const text = event.delta || ''
      if (!text) continue
      reply += text
      params.emit('delta', { text: redactHiddenReasoningAndSecrets(text) })
    } else if (event.type === 'done') {
      finalMessage = event.message
    } else if (event.type === 'error') {
      throw new Error(event.error?.errorMessage || 'OpenAI Codex streaming failed.')
    }
  }

  const finalReply = reply || textFromPiAiAssistantMessage(finalMessage)
  return {
    content: finalReply,
    reasoningContent: reasoningFromPiAiAssistantMessage(finalMessage) || undefined,
  }
}

async function streamAnthropicMessage(params: {
  model: string
  apiKey: string
  messages: ProviderConversationMessage[]
  thinking: ThinkingLevel
  signal: AbortSignal
  emit: StreamEmitter
}) {
  const body = {
    model: params.model,
    max_tokens: anthropicMaxTokens(params.thinking),
    messages: toAnthropicMessages(params.messages),
    stream: true,
    ...anthropicReasoningPatch(params.model, params.thinking),
  }
  const upstream = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'x-api-key': params.apiKey,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
    signal: params.signal,
  })
  await assertUpstreamOk(upstream, 'anthropic')
  let reply = ''
  await readUpstreamSse(upstream, (frame) => {
    try {
      const payload = JSON.parse(frame.data) as {
        type?: string
        delta?: { type?: string; text?: string; thinking?: string }
      }
      if (payload.type !== 'content_block_delta' || payload.delta?.type !== 'text_delta') return
      const text = payload.delta.text || ''
      if (!text) return
      reply += text
      params.emit('delta', { text: redactHiddenReasoningAndSecrets(text) })
    } catch {
      // Ignore ping and unknown event frames.
    }
  })
  return { content: reply }
}

async function streamGeminiContent(params: {
  model: string
  auth: ProviderRequestAuth
  messages: ProviderConversationMessage[]
  thinking: ThinkingLevel
  signal: AbortSignal
  emit: StreamEmitter
}) {
  const modelPath = params.model.startsWith('models/') ? params.model : `models/${params.model}`
  const thinkingConfig = geminiThinkingConfig(params.model, params.thinking)
  const body: Record<string, unknown> = {
    contents: toGeminiContents(params.messages),
  }
  if (thinkingConfig) {
    body.generationConfig = {
      thinkingConfig,
    }
  }
  const query = new URLSearchParams({ alt: 'sse' })
  const headers: Record<string, string> = { 'Content-Type': 'application/json' }
  if (params.auth.type === 'apiKey') {
    query.set('key', params.auth.value)
  } else {
    headers.Authorization = `Bearer ${params.auth.accessToken}`
    if (params.auth.projectId) headers['x-goog-user-project'] = params.auth.projectId
  }
  const upstream = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/${modelPath}:streamGenerateContent?${query.toString()}`,
    {
      method: 'POST',
      headers,
      body: JSON.stringify(body),
      signal: params.signal,
    },
  )
  await assertUpstreamOk(upstream, 'google')
  let reply = ''
  await readUpstreamSse(upstream, (frame) => {
    try {
      const payload = JSON.parse(frame.data) as {
        candidates?: Array<{ content?: { parts?: Array<{ text?: string }> }; finishReason?: string }>
      }
      const finishReason = payload.candidates?.[0]?.finishReason
      const text = (payload.candidates?.[0]?.content?.parts || [])
        .map((part) => part.text || '')
        .filter(Boolean)
        .join('')
      if (text) {
        reply += text
        params.emit('delta', { text: redactHiddenReasoningAndSecrets(text) })
      }
      if (finishReason) return false
    } catch {
      // Ignore malformed upstream frames.
    }
  })
  return { content: reply }
}

function googleVertexBaseUrl(location: string) {
  return location === 'global'
    ? 'https://aiplatform.googleapis.com/v1'
    : `https://${location}-aiplatform.googleapis.com/v1`
}

function googleVertexModelName(model: string) {
  return model
    .replace(/^publishers\/google\/models\//i, '')
    .replace(/^models\//i, '')
    .trim()
}

type GoogleVertexOauthAuth = Extract<ProviderRequestAuth, { type: 'oauth' }>

type GoogleVertexModelAvailability = {
  ok: boolean
  status: number
  location: string
  detail?: string
}

const googleVertexModelAvailabilityCache = new Map<string, { value: GoogleVertexModelAvailability; expiresAt: number }>()

function normalizeGoogleVertexLocation(location?: string) {
  return location?.trim() || GOOGLE_VERTEX_DEFAULT_LOCATION
}

function googleVertexCandidateLocations(location?: string) {
  const preferred = normalizeGoogleVertexLocation(location)
  return Array.from(new Set([preferred, GOOGLE_VERTEX_GLOBAL_LOCATION].filter(Boolean)))
}

function googleVertexModelMethodEndpoint(
  projectId: string,
  location: string,
  modelName: string,
  method: 'countTokens' | 'generateContent' | 'streamGenerateContent',
) {
  const encodedModel = encodeURIComponent(modelName).replace(/%40/g, '@')
  return [
    googleVertexBaseUrl(location),
    `projects/${encodeURIComponent(projectId)}`,
    `locations/${encodeURIComponent(location)}`,
    'publishers/google',
    `models/${encodedModel}:${method}`,
  ].join('/')
}

function googleVertexAvailabilityCacheKey(projectId: string, location: string, modelName: string) {
  return [projectId, location, modelName].join('\u0000')
}

async function checkGoogleVertexModelAvailability(params: {
  auth: GoogleVertexOauthAuth
  modelName: string
  location: string
  signal?: AbortSignal
}): Promise<GoogleVertexModelAvailability> {
  const projectId = params.auth.projectId?.trim()
  if (!projectId) {
    return {
      ok: false,
      status: 0,
      location: params.location,
      detail: 'Google Vertex requires a configured Google Cloud project.',
    }
  }

  const cacheKey = googleVertexAvailabilityCacheKey(projectId, params.location, params.modelName)
  const cached = googleVertexModelAvailabilityCache.get(cacheKey)
  if (cached && cached.expiresAt > Date.now()) return cached.value

  const response = await fetch(googleVertexModelMethodEndpoint(projectId, params.location, params.modelName, 'countTokens'), {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${params.auth.accessToken}`,
      'Content-Type': 'application/json',
      'x-goog-user-project': projectId,
    },
    body: JSON.stringify({
      contents: [{ role: 'user', parts: [{ text: 'ping' }] }],
    }),
    signal: params.signal,
  })
  const detail = response.ok ? '' : await response.text().catch(() => '')
  const value: GoogleVertexModelAvailability = {
    ok: response.ok,
    status: response.status,
    location: params.location,
    ...(detail ? { detail: trimTask(detail, 400) } : {}),
  }
  googleVertexModelAvailabilityCache.set(cacheKey, {
    value,
    expiresAt: Date.now() + GOOGLE_VERTEX_MODEL_AVAILABILITY_CACHE_MS,
  })
  return value
}

function googleVertexUnavailableMessage(modelName: string, checks: GoogleVertexModelAvailability[]) {
  const locations = checks.map((check) => check.location).join(', ') || GOOGLE_VERTEX_DEFAULT_LOCATION
  const quota = checks.find((check) => check.status === 429)
  if (quota) {
    return `Google Vertex quota blocked the model check for ${modelName} in ${quota.location}. ${quota.detail || 'Try again after quota is available.'}`
  }
  const auth = checks.find((check) => check.status === 401 || check.status === 403)
  if (auth) {
    return `Google Vertex cannot access ${modelName} with the current gcloud credentials or project. ${auth.detail || 'Check IAM, billing, and Vertex AI API access.'}`
  }
  const lastDetail = [...checks].reverse().find((check) => check.detail)?.detail
  return `Google Vertex model ${modelName} is not available in ${locations} for the configured project. Pick another google-vertex model or use a Vertex location where Google has enabled that model.${lastDetail ? ` Last check: ${lastDetail}` : ''}`
}

async function resolveGoogleVertexModelRoute(params: {
  auth: GoogleVertexOauthAuth
  modelName: string
  preferredLocation?: string
  signal?: AbortSignal
}) {
  const projectId = params.auth.projectId?.trim()
  if (!projectId) throw new Error('Google Vertex streaming requires a Google Cloud project. Run gcloud config set project YOUR_PROJECT_ID.')

  const checks: GoogleVertexModelAvailability[] = []
  for (const location of googleVertexCandidateLocations(params.preferredLocation || params.auth.location)) {
    const availability = await checkGoogleVertexModelAvailability({
      auth: params.auth,
      modelName: params.modelName,
      location,
      signal: params.signal,
    })
    checks.push(availability)
    if (availability.ok) {
      return {
        location,
        endpoint: googleVertexModelMethodEndpoint(projectId, location, params.modelName, 'streamGenerateContent'),
      }
    }
  }

  throw new Error(googleVertexUnavailableMessage(params.modelName, checks))
}

async function filterGoogleVertexCatalogModels<T extends { id: string; provider?: string; name?: string }>(models: T[]): Promise<T[]> {
  const vertexModelNames = Array.from(
    new Set(
      models
        .filter((model) => (model.provider || splitModelId(model.id).provider) === 'google-vertex')
        .map((model) => model.name || splitModelId(model.id).model)
        .map((model) => googleVertexModelName(model))
        .filter(Boolean),
    ),
  )
  if (!vertexModelNames.length) return models

  const auth = await resolveGoogleVertexRequestAuth({}).catch(() => null)
  if (!auth || auth.type !== 'oauth') return models

  const available = new Map<string, boolean>()
  await Promise.all(
    vertexModelNames.map(async (modelName) => {
      const route = await resolveGoogleVertexModelRoute({ auth, modelName }).catch(() => null)
      available.set(modelName, Boolean(route))
    }),
  )
  if (!Array.from(available.values()).some(Boolean)) return models

  return models.filter((model) => {
    const provider = model.provider || splitModelId(model.id).provider
    if (provider !== 'google-vertex') return true
    const modelName = googleVertexModelName(model.name || splitModelId(model.id).model)
    return Boolean(available.get(modelName))
  })
}

async function streamGoogleVertexContent(params: {
  model: string
  auth: ProviderRequestAuth
  messages: ProviderConversationMessage[]
  thinking: ThinkingLevel
  signal: AbortSignal
  emit: StreamEmitter
}) {
  if (params.auth.type !== 'oauth') throw new Error('Google Vertex streaming requires gcloud or a Google access token.')
  const projectId = params.auth.projectId?.trim()
  if (!projectId) throw new Error('Google Vertex streaming requires a Google Cloud project. Run gcloud config set project YOUR_PROJECT_ID.')
  const location = normalizeGoogleVertexLocation(params.auth.location)
  const modelName = googleVertexModelName(params.model)
  const route = await resolveGoogleVertexModelRoute({
    auth: params.auth,
    modelName,
    preferredLocation: location,
    signal: params.signal,
  })
  if (route.location !== location) {
    params.emit('status', {
      message: `Using Google Vertex ${route.location} endpoint for ${modelName}; it was not available in ${location}.`,
    })
  }
  const thinkingConfig = geminiThinkingConfig(params.model, params.thinking)
  const body: Record<string, unknown> = {
    contents: toGeminiContents(params.messages),
  }
  if (thinkingConfig) {
    body.generationConfig = {
      thinkingConfig,
    }
  }

  const upstream = await fetch(`${route.endpoint}?${new URLSearchParams({ alt: 'sse' }).toString()}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${params.auth.accessToken}`,
      'Content-Type': 'application/json',
      'x-goog-user-project': projectId,
    },
    body: JSON.stringify(body),
    signal: params.signal,
  })
  await assertUpstreamOk(upstream, 'google-vertex')
  let reply = ''
  await readUpstreamSse(upstream, (frame) => {
    try {
      const payload = JSON.parse(frame.data) as {
        candidates?: Array<{ content?: { parts?: Array<{ text?: string }> }; finishReason?: string }>
      }
      const finishReason = payload.candidates?.[0]?.finishReason
      const text = (payload.candidates?.[0]?.content?.parts || [])
        .map((part) => part.text || '')
        .filter(Boolean)
        .join('')
      if (text) {
        reply += text
        params.emit('delta', { text: redactHiddenReasoningAndSecrets(text) })
      }
      if (finishReason) return false
    } catch {
      // Ignore malformed upstream frames.
    }
  })
  return { content: reply }
}

type BufferedRuntimeReason = {
  code: string
  message: string
}

type AgentRuntimeShortcut = {
  command: 'work' | 'runtime' | 'openclaw'
  message: string
}

type LocalJsonPostResponse = {
  ok: boolean
  status: number
  text: string
}

function parseAgentRuntimeShortcut(message: string): AgentRuntimeShortcut | null {
  const match = /^\s*\/(work|runtime|openclaw)(?=$|\s|:)(?:\s+|:\s*)?([\s\S]*)$/i.exec(message || '')
  if (!match) return null
  const command = match[1].toLowerCase() as AgentRuntimeShortcut['command']
  const instruction = (match[2] || '').trim()
  return {
    command,
    message: instruction || 'OpenClaw runtime requested. Ask the operator what work should be done.',
  }
}

function agentRuntimeShortcutReason(shortcut?: AgentRuntimeShortcut | null): BufferedRuntimeReason {
  return {
    code: shortcut ? `slash-${shortcut.command}` : 'forced-openclaw-runtime',
    message: shortcut
      ? `/${shortcut.command} sends this turn straight to the OpenClaw runtime.`
      : 'Agent accepted the turn.',
  }
}

function postLocalJsonNoHeaderTimeout(routePath: string, body: Record<string, unknown>, signal?: AbortSignal): Promise<LocalJsonPostResponse> {
  const payload = JSON.stringify(body)
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new Error('Request aborted'))
      return
    }

    let settled = false
    let onAbort = () => undefined
    const finish = (callback: () => void) => {
      if (settled) return
      settled = true
      signal?.removeEventListener('abort', onAbort)
      callback()
    }
    const request = httpRequest({
      host: '127.0.0.1',
      port: PORT,
      path: routePath,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
        Connection: 'close',
      },
      timeout: 0,
    }, (response) => {
      response.setEncoding('utf8')
      let text = ''
      response.on('data', (chunk) => {
        text = appendBoundedLocalJsonResponse(text, chunk)
      })
      response.on('error', (error) => finish(() => reject(error)))
      response.on('end', () => {
        const status = response.statusCode || 0
        finish(() => resolve({
          ok: status >= 200 && status < 300,
          status,
          text,
        }))
      })
    })

    onAbort = () => {
      request.destroy(new Error('Request aborted'))
    }

    signal?.addEventListener('abort', onAbort, { once: true })
    request.setTimeout(0)
    request.on('error', (error) => finish(() => reject(error)))
    request.write(payload)
    request.end()
  })
}

const ROUTER_TYPO_REPLACEMENTS: Array<[RegExp, string]> = [
  [/\bteh\b/g, 'the'],
  [/\bthsi\b/g, 'this'],
  [/\btaht\b/g, 'that'],
  [/\baks(?:ing)?\b/g, 'asking'],
  [/\banswre\b/g, 'answer'],
  [/\bshwo(?:ing)?\b/g, 'showing'],
  [/\bwwhat\b/g, 'what'],
  [/\bedoin?g\b/g, 'doing'],
  [/\bthrougha?\b/g, 'through'],
  [/\bauidt\b/g, 'audit'],
  [/\baudti\b/g, 'audit'],
  [/\bcomercial(?:ly)?\b/g, 'commercially'],
  [/\bcommerical(?:ly)?\b/g, 'commercially'],
  [/\bater\b/g, 'after'],
  [/\binefr?nece\b/g, 'inference'],
  [/\bregcngition\b/g, 'recognition'],
  [/\brecogni[sz]ing\b/g, 'recognizing'],
  [/\bapproprile?y\b/g, 'appropriately'],
]

function normalizeRouterText(value: string) {
  let text = (value || '')
    .toLowerCase()
    .replace(/['"]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  for (const [pattern, replacement] of ROUTER_TYPO_REPLACEMENTS) {
    text = text.replace(pattern, replacement)
  }
  return text
}

function isDefinitionOnlyWorkspaceQuestion(text: string) {
  return (
    /\b(?:what\s+(?:do\s+you\s+mean\s+by|does|is)|explain|define|meaning\s+of)\b/.test(text) &&
    !/\b(?:read|open|show|inspect|audit|review|check|verify|scan|look\s+(?:at|into)|fix|change|update|edit|patch|build|run)\b/.test(text)
  )
}

function hasOpenClawToolSurfaceMention(text: string) {
  return /\b(?:tools?|tool\s+path|runtime|gateway|openclaw|clawtalk|filesystem|file\s*system|terminal|shell|browser|app[-\s]?control|workspace\s+access)\b/i.test(text)
}

function hasDirectExecutionRequest(text: string) {
  return /\b(?:(?:can|could|would|will)\s+(?:you|we)|(?:i\s+)?need\s+you\s+to|want\s+you\s+to|please)\b[\s\S]{0,140}\b(?:do|handle|take\s+care\s+of|check|verify|fix|make|update|run|test|build|look\s+(?:at|into)|go\s+through|inspect|read|open|use|execute|download|digest)\b/i.test(text)
}

function hasContextualExecutionRequest(text: string) {
  return /\b(?:do|handle|take\s+care\s+of|check|verify|fix|make|update|run|test|build|inspect|read|open|execute)\s+(?:it|this|that|these|those|the\s+(?:change|fix|update|test|build|work|thing|task))\b/i.test(text)
}

function inferWorkspaceRuntimeIntent(message: string, intentMessage?: string): BufferedRuntimeReason | null {
  const rawIntent = intentMessage?.trim() || message || ''
  const intentText = normalizeRouterText(rawIntent)
  const composedText = normalizeRouterText(message || '')
  if (!intentText) return null
  if (isDefinitionOnlyWorkspaceQuestion(intentText)) return null

  const text = `${intentText}\n${composedText}`
  const explicitWorkspaceTarget =
    /\b(?:workspace|repo(?:sitory)?|project\s+(?:files?|folder|directory)|directory|folder|files?|source\s+code|codebase|package\.json|tsconfig|vite|server|client|component|html|css|javascript|typescript)\b/i
  const productTarget =
    /\b(?:this|the|our|my)\s+(?:app|application|project|repo(?:sitory)?|codebase|build|release|product|desktop\s+app|electron\s+app)\b/i
  const namedProductTarget =
    /\b(?:dystopai|openclaw|control\s+center|electron|desktop\s+app|release[/\\]win-unpacked|\.openclaw)\b/i
  const explicitToolAction =
    /\b(?:implement|scaffold|patch|edit(?:ed|ing)?|save|rename|delete|install|npm|terminal|shell|command|run\s+tests?|run\s+build|build|compile|lint|fix|update|modify|change|read|inspect|list|search|find|look\s+(?:at|into)|go\s+through|download|digest|analy[sz]e|summari[sz]e|audit|review|check|verify|validate|scan)\b/i
  const commercialAuditAction =
    /\b(?:sell|commercial(?:ly)?|commercialize|license|licen[cs]ing|distribute|distribution|ship|release|publish|app\s*store|installer|eula|privacy|terms|compliance|copyright|trademark|legal|sbom|third[-\s]?party\s+notices?)\b/i
  const followUpWorkspaceAction =
    /\b(?:after\s+(?:those|that|this)|those\s+(?:are|r)?\s*done|that\s+(?:is|s)?\s*done|blockers?|fix(?:es)?|changes?|cleanup|clean\s+build|ready\s+to\s+(?:sell|ship|release)|can\s+i\s+(?:sell|ship|release))\b/i
  const workspaceLookupQuestion =
    /\b(?:show\s+me|where(?:\s+is|'?s)?|which|what(?:\s+is|'?s)\s+(?:in|inside)|tell\s+me\s+(?:where|which|what\s+(?:is|'?s)\s+(?:in|inside)))\b/i
  const explicitCreationTarget =
    /\b(?:create|make|generate|write|save|export|render|produce)\b/i.test(intentText) &&
    /\b(?:file|folder|directory|component|page|website|web\s*app|app|game|script|code|html|css|javascript|typescript|project|pdf|docx?|document|word\s+doc(?:ument)?|xlsx?|spreadsheet|csv|pptx?|presentation|slide\s+deck|zip|archive)\b/i.test(intentText)

  if (hasOpenClawToolSurfaceMention(text) && (explicitToolAction.test(intentText) || hasDirectExecutionRequest(intentText))) {
    return {
      code: 'tool-access',
      message: 'Agent is using OpenClaw tools for this request.',
    }
  }

  if (hasContextualExecutionRequest(intentText)) {
    return {
      code: 'contextual-workspace',
      message: 'Agent is using the current workspace context.',
    }
  }

  const hasWorkspaceTarget =
    explicitWorkspaceTarget.test(text) ||
    productTarget.test(intentText) ||
    namedProductTarget.test(text)

  if (commercialAuditAction.test(intentText) && (hasWorkspaceTarget || followUpWorkspaceAction.test(intentText))) {
    return {
      code: 'commercial-audit',
      message: 'Agent is checking project files for commercial readiness.',
    }
  }

  if (followUpWorkspaceAction.test(intentText) && /\b(?:audit|review|check|verify|confirm|ready|done|sell|ship|release|commercial(?:ly)?)\b/i.test(intentText)) {
    return {
      code: 'contextual-workspace',
      message: 'Agent is checking the current workspace context.',
    }
  }

  if ((explicitToolAction.test(intentText) && hasWorkspaceTarget) || (workspaceLookupQuestion.test(intentText) && hasWorkspaceTarget) || explicitCreationTarget) {
    return {
      code: 'workspace-tools',
      message: 'Agent is using workspace tools for this request.',
    }
  }

  return null
}

function bufferedAgentRuntimeReason(message: string, attachments?: unknown[], intentMessage?: string): BufferedRuntimeReason | null {
  const text = message || ''
  const intentText = intentMessage?.trim() || text
  const runtimeShortcut = parseAgentRuntimeShortcut(text)
  if (runtimeShortcut) return agentRuntimeShortcutReason(runtimeShortcut)
  if (attachments?.length) {
    return {
      code: 'attachments',
      message: 'Agent is reading the attached file context.',
    }
  }
  if (isBrowserIntentMessage(intentText)) {
    return {
      code: 'browser',
      message: 'Agent is using browser tools for this request.',
    }
  }
  if (isClawTalkIntentMessage(intentText) || isClawTalkSetupIntentMessage(intentText)) {
    return {
      code: 'clawtalk',
      message: 'Agent is using or configuring ClawTalk for this request.',
    }
  }
  if (parseDelegationIntent(intentText)) {
    return {
      code: 'delegation',
      message: 'Agent is coordinating this with another agent.',
    }
  }
  if (isTeamRuntimePrompt(text)) {
    return {
      code: 'team-runtime',
      message: 'Agent is handling team coordination context.',
    }
  }

  return inferWorkspaceRuntimeIntent(text, intentMessage)
}

function isLikelyOpenClawRuntimeToolRequest(message: string) {
  const text = normalizeRouterText(message || '')
  if (isDefinitionOnlyWorkspaceQuestion(text)) return false
  const workspaceTarget =
    /\b(workspace|repo(?:sitory)?|project\s+(?:files?|folder|directory)|directory|folder|files?|source\s+code|codebase|package\.json|tsconfig|vite|server|client|component|html|css|javascript|typescript|this\s+(?:app|application|project|repo|codebase|build|release)|our\s+(?:app|application|project|repo|codebase|build|release)|dystopai|openclaw|control\s+center|\.openclaw)\b/i
  const toolAction =
    /\b(use\s+(?:tools?|openclaw|terminal|shell|browser)|run|execute|test|build|compile|lint|install|start|restart|read|inspect|list|search|find|review|audit|check|verify|validate|scan|analy[sz]e|summari[sz]e|edit|patch|modify|update|fix|sell|commercial(?:ly)?|license|licen[cs]ing|distribute|ship|release)\b/i
  const localQuestion =
    /\b(?:what(?:'s| is)?|where(?:'s| is)?|which|show me|tell me)\b/i
  const contextualFollowUp =
    /\b(?:after\s+(?:those|that|this)|those\s+(?:are|r)?\s*done|blockers?|fix(?:es)?|ready\s+to\s+(?:sell|ship|release)|can\s+i\s+(?:sell|ship|release))\b/i
  if (hasOpenClawToolSurfaceMention(text) && (toolAction.test(text) || hasDirectExecutionRequest(text))) return true
  if (hasContextualExecutionRequest(text)) return true
  if (contextualFollowUp.test(text)) return true
  return workspaceTarget.test(text) && (toolAction.test(text) || localQuestion.test(text))
}

function googleGeminiEmbeddedRuntimeReason(modelId: string, message: string, intentMessage?: string): BufferedRuntimeReason | null {
  if (!isGoogleGeminiModelId(modelId)) return null
  const text = intentMessage?.trim() || message || ''
  if (!text.trim()) return null
  if (!isLikelyCodeArtifactRequest(text) && !isLikelyOpenClawRuntimeToolRequest(text)) return null
  return {
    code: 'google-gemini-tools',
    message: 'Agent is using tools for this Google Gemini request.',
  }
}

function openAiCodexEmbeddedRuntimeReason(modelId: string, message: string, intentMessage?: string): BufferedRuntimeReason | null {
  if (!isOpenAiCodexSubscriptionModel(modelId)) return null
  const text = intentMessage?.trim() || message || ''
  if (!text.trim()) return null
  if (!isLikelyCodeArtifactRequest(text) && !isLikelyOpenClawRuntimeToolRequest(text)) return null
  return {
    code: 'openai-codex-tools',
    message: 'Agent is using tools for this GPT/Codex request.',
  }
}

async function resolveAgentPrimaryModelId(agentId: string) {
  const { config, target } = await getAgentById(agentId)
  if (!target) throw new Error(`Agent not found: ${agentId}`)
  const defaults = config.agents?.defaults?.model || {}
  const local = await ensureAgentLocalConfig({
    agentId: target.id,
    entry: target,
    defaultsModel: defaults,
    defaultsSandbox: (config.agents?.defaults as { sandbox?: AgentSandboxConfig } | undefined)?.sandbox,
  })
  return normalizeModelWithFallback(local.model, defaults).primary
}

type HostActionRequest =
  | {
      kind: 'launch-chrome'
      url?: string
    }

function detectHostActionRequest(message: string): HostActionRequest | null {
  const raw = (message || '').trim()
  if (!raw) return null
  const normalized = raw.toLowerCase()
  const hasCompoundIntent =
    /\b(and then|then|also|after that|next)\b/i.test(normalized) ||
    (/\band\b/i.test(normalized) && /\b(add|buy|search|find|order|fill|checkout|recipe|ingredients|cart)\b/i.test(normalized))
  if (hasCompoundIntent) return null

  const urlMatch = raw.match(/\bhttps?:\/\/[^\s<>")']+/i)
  const mentionsChrome = /\b(google\s+)?chrome\b/i.test(normalized)
  const explicitLaunchIntent = /\b(open|launch|start|run|use)\b/i.test(normalized)
  const goToIntent = /\bgo\s*to\b|\bgoto\b/i.test(normalized)
  const wantsChrome = mentionsChrome && (explicitLaunchIntent || goToIntent || Boolean(urlMatch))
  if (!wantsChrome) return null
  return {
    kind: 'launch-chrome',
    url: urlMatch?.[0],
  }
}

function spawnDetached(command: string, args: string[]): Promise<{ ok: boolean; detail: string }> {
  return new Promise((resolve) => {
    let settled = false
    try {
      const child = spawn(command, args, {
        detached: true,
        stdio: 'ignore',
        shell: false,
      })
      child.once('error', (error) => {
        if (settled) return
        settled = true
        resolve({ ok: false, detail: String(error) })
      })
      child.unref()
      setTimeout(() => {
        if (settled) return
        settled = true
        resolve({ ok: true, detail: `spawned pid ${child.pid ?? 'n/a'}` })
      }, 40)
    } catch (error) {
      resolve({ ok: false, detail: String(error) })
    }
  })
}

interface PickerCommandOptions {
  timeoutMs?: number
  windowsHide?: boolean
  abortSignal?: AbortSignal
  label?: string
}

function quoteWindowsBatchArg(value: string) {
  return `"${value.replace(/%/g, '%%').replace(/"/g, '""')}"`
}

async function writeWindowsPickerLauncher(
  launcherPath: string,
  title: string,
  scriptPath: string,
  outputPath: string,
  startPath: string,
) {
  const launcher = [
    '@echo off',
    [
      'start',
      quoteWindowsBatchArg(title),
      'powershell.exe',
      '-NoLogo',
      '-NoProfile',
      '-STA',
      '-ExecutionPolicy',
      'Bypass',
      '-WindowStyle',
      'Normal',
      '-File',
      quoteWindowsBatchArg(scriptPath),
      '-OutPath',
      quoteWindowsBatchArg(outputPath),
      '-StartPath',
      quoteWindowsBatchArg(startPath),
    ].join(' '),
    '',
  ].join('\r\n')
  await fs.writeFile(launcherPath, launcher, 'utf-8')
}

type FolderPickerSessionStatus = 'pending' | 'selected' | 'cancelled' | 'error'
interface FolderPickerSession {
  id: string
  status: FolderPickerSessionStatus
  path?: string | null
  detail?: string
  startedAt: number
  updatedAt: number
  expiresAt: number
}
interface ImagePickerSession extends FolderPickerSession {
  agentId?: string
  sourcePath?: string | null
  avatar?: string | null
  previewUrl?: string | null
}

const FOLDER_PICKER_SESSION_TTL_MS = 5 * 60 * 1000
const folderPickerSessions = new Map<string, FolderPickerSession>()
const imagePickerSessions = new Map<string, ImagePickerSession>()

function pruneFolderPickerSessions() {
  const now = Date.now()
  for (const [id, session] of folderPickerSessions) {
    if (session.expiresAt <= now) folderPickerSessions.delete(id)
  }
  for (const [id, session] of imagePickerSessions) {
    if (session.expiresAt <= now) imagePickerSessions.delete(id)
  }
}

function serializeFolderPickerSession(session: FolderPickerSession) {
  return {
    sessionId: session.id,
    status: session.status,
    path: session.path ?? null,
    cancelled: session.status === 'cancelled',
    detail: session.detail,
  }
}

function serializeImagePickerSession(session: ImagePickerSession) {
  return {
    ...serializeFolderPickerSession(session),
    agentId: session.agentId,
    sourcePath: session.sourcePath ?? null,
    avatar: session.avatar ?? null,
    previewUrl: session.previewUrl ?? null,
  }
}

function startFolderPickerSession(startPath: string) {
  pruneFolderPickerSessions()
  const now = Date.now()
  const session: FolderPickerSession = {
    id: randomUUID(),
    status: 'pending',
    path: null,
    detail: 'Folder picker is open.',
    startedAt: now,
    updatedAt: now,
    expiresAt: now + FOLDER_PICKER_SESSION_TTL_MS,
  }
  folderPickerSessions.set(session.id, session)
  if (process.platform === 'win32') {
    void launchWindowsFolderPickerSession(session, startPath)
    return session
  }
  void pickFolderWithOsDialog(startPath)
    .then((picked) => {
      if (picked.ok && picked.path) {
        session.status = 'selected'
        session.path = path.resolve(picked.path)
        session.detail = 'Folder selected.'
      } else if (picked.cancelled) {
        session.status = 'cancelled'
        session.path = null
        session.detail = 'No folder selected.'
      } else {
        session.status = 'error'
        session.path = null
        session.detail = picked.detail || 'No supported native folder picker is available in this environment.'
      }
    })
    .catch((error) => {
      session.status = 'error'
      session.path = null
      session.detail = String(error)
    })
    .finally(() => {
      session.updatedAt = Date.now()
      session.expiresAt = Date.now() + FOLDER_PICKER_SESSION_TTL_MS
    })
  return session
}

function startImagePickerSession(agentId: string | undefined, startPath: string) {
  pruneFolderPickerSessions()
  const now = Date.now()
  const session: ImagePickerSession = {
    id: randomUUID(),
    status: 'pending',
    path: null,
    sourcePath: null,
    avatar: null,
    previewUrl: null,
    agentId,
    detail: 'Image picker is open.',
    startedAt: now,
    updatedAt: now,
    expiresAt: now + FOLDER_PICKER_SESSION_TTL_MS,
  }
  imagePickerSessions.set(session.id, session)
  if (process.platform === 'win32') {
    void launchWindowsImagePickerSession(session, startPath)
    return session
  }
  void pickImageWithOsDialog(startPath)
    .then((picked) => finishImagePickerSession(session, picked))
    .catch((error) => {
      session.status = 'error'
      session.path = null
      session.detail = String(error)
    })
    .finally(() => {
      session.updatedAt = Date.now()
      session.expiresAt = Date.now() + FOLDER_PICKER_SESSION_TTL_MS
    })
  return session
}

async function launchWindowsFolderPickerSession(session: FolderPickerSession, startPath: string) {
  const pickerDir = path.join(OPENCLAW_STATE_ROOT, 'tmp', 'folder-picker')
  const scriptPath = path.join(pickerDir, `${session.id}.ps1`)
  const launcherPath = path.join(pickerDir, `${session.id}.cmd`)
  const outputPath = path.join(pickerDir, `${session.id}.json`)
  let finished = false
  let pollTimer: ReturnType<typeof setInterval> | null = null
  let timeoutTimer: ReturnType<typeof setTimeout> | null = null

  const finish = async (status: FolderPickerSessionStatus, detail?: string, selectedPath?: string | null) => {
    if (finished) return
    finished = true
    if (pollTimer) clearInterval(pollTimer)
    if (timeoutTimer) clearTimeout(timeoutTimer)
    session.status = status
    session.path = selectedPath ? path.resolve(selectedPath) : null
    session.detail = detail
    session.updatedAt = Date.now()
    session.expiresAt = Date.now() + FOLDER_PICKER_SESSION_TTL_MS
    setTimeout(() => {
      void fs.unlink(scriptPath).catch(() => {})
      void fs.unlink(launcherPath).catch(() => {})
      void fs.unlink(outputPath).catch(() => {})
    }, FOLDER_PICKER_SESSION_TTL_MS)
  }

  const parseOutput = (raw: string): { status?: string; path?: string | null; detail?: string } => {
    const text = raw.replace(/^\uFEFF/, '')
    try {
      return JSON.parse(text) as { status?: string; path?: string | null; detail?: string }
    } catch {
      const parsed: { status?: string; path?: string | null; detail?: string } = {}
      for (const line of text.split(/\r?\n/)) {
        const separator = line.indexOf('=')
        if (separator <= 0) continue
        const key = line.slice(0, separator).trim()
        const value = line.slice(separator + 1).trim()
        if (key === 'status') parsed.status = value
        else if (key === 'path') parsed.path = value
        else if (key === 'detail') parsed.detail = value
      }
      return parsed
    }
  }

  const readOutput = async () => {
    try {
      const raw = await fs.readFile(outputPath, 'utf-8')
      const parsed = parseOutput(raw)
      if (parsed.status === 'selected' && parsed.path?.trim()) {
        await finish('selected', 'Folder selected.', parsed.path.trim())
      } else if (parsed.status === 'cancelled') {
        await finish('cancelled', parsed.detail || 'No folder selected.')
      } else {
        await finish('error', parsed.detail || 'Folder picker failed.')
      }
    } catch {
      // The helper has not written its result yet.
    }
  }

  try {
    await fs.mkdir(pickerDir, { recursive: true })
    const pickerStart = await resolvePickerStartPath(startPath)
    const script = [
      'param(',
      '  [Parameter(Mandatory=$true)][string]$OutPath,',
      '  [Parameter(Mandatory=$true)][string]$StartPath',
      ')',
      '$ErrorActionPreference = "Stop"',
      'function Write-PickerResult($value) {',
      '  $json = $value | ConvertTo-Json -Compress',
      '  $json | Set-Content -LiteralPath $OutPath -Encoding UTF8',
      '}',
      'try {',
      '  Add-Type -AssemblyName System.Windows.Forms',
      '  Add-Type -AssemblyName System.Drawing',
      '  [System.Windows.Forms.Application]::EnableVisualStyles()',
      '  $initialDirectory = $StartPath',
      '  if (-not [string]::IsNullOrWhiteSpace($initialDirectory) -and (Test-Path -LiteralPath $initialDirectory -PathType Leaf)) {',
      '    $initialDirectory = Split-Path -LiteralPath $initialDirectory -Parent',
      '  }',
      '  if ([string]::IsNullOrWhiteSpace($initialDirectory) -or -not (Test-Path -LiteralPath $initialDirectory -PathType Container)) {',
      '    $initialDirectory = [System.Environment]::GetFolderPath("DesktopDirectory")',
      '  }',
      '  $owner = New-Object System.Windows.Forms.Form',
      '  $owner.Text = "Select Agent Workspace"',
      '  $owner.StartPosition = "CenterScreen"',
      '  $owner.Size = New-Object System.Drawing.Size(320, 80)',
      '  $owner.TopMost = $true',
      '  $owner.ShowInTaskbar = $true',
      '  $owner.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedToolWindow',
      '  $owner.Show()',
      '  $owner.BringToFront()',
      '  $owner.Activate()',
      '  [System.Windows.Forms.Application]::DoEvents()',
      '  $dialog = New-Object System.Windows.Forms.FolderBrowserDialog',
      '  $dialog.Description = "Select Agent Workspace"',
      '  $dialog.SelectedPath = $initialDirectory',
      '  $dialog.ShowNewFolderButton = $true',
      '  $result = $dialog.ShowDialog($owner)',
      '  $owner.Dispose()',
      '  if ($result -eq [System.Windows.Forms.DialogResult]::OK -and -not [string]::IsNullOrWhiteSpace($dialog.SelectedPath)) {',
      '    Write-PickerResult @{ status = "selected"; path = $dialog.SelectedPath }',
      '    exit 0',
      '  }',
      '  Write-PickerResult @{ status = "cancelled"; detail = "No folder selected." }',
      '  exit 0',
      '} catch {',
      '  Write-PickerResult @{ status = "error"; detail = $_.Exception.Message }',
      '  exit 1',
      '}',
      '',
    ].join('\n')
    await fs.writeFile(scriptPath, script, 'utf-8')
    await writeWindowsPickerLauncher(launcherPath, 'Select Agent Workspace', scriptPath, outputPath, pickerStart)
    const launcher = spawn('cmd.exe', ['/d', '/s', '/c', launcherPath], {
      detached: true,
      stdio: 'ignore',
      windowsHide: false,
    })
    launcher.unref()
    launcher.once('error', (error) => {
      void finish('error', String(error))
    })
    pollTimer = setInterval(() => {
      void readOutput()
    }, 500)
    timeoutTimer = setTimeout(() => {
      void finish('error', `Folder picker timed out after ${Math.round(FOLDER_PICKER_TIMEOUT_MS / 1000)} seconds. Paste a directory path manually and press Set, or try Browse again.`)
    }, FOLDER_PICKER_TIMEOUT_MS)
  } catch (error) {
    await finish('error', String(error))
  }
}

function isSupportedAvatarImagePath(filePath: string) {
  return AVATAR_IMAGE_EXTENSIONS.has(path.extname(filePath).toLowerCase())
}

function avatarUploadFileName(rawName: string | undefined, contentType: string | undefined) {
  const cleanName = path.basename((rawName || 'avatar').trim() || 'avatar')
    .replace(/[\r\n]/g, ' ')
    .slice(0, 180)
  const extFromName = path.extname(cleanName).toLowerCase()
  const ext = AVATAR_IMAGE_EXTENSIONS.has(extFromName)
    ? extFromName
    : AVATAR_IMAGE_MIME_EXTENSIONS[(contentType || '').split(';')[0].trim().toLowerCase()] || ''
  if (!ext) throw new Error('Choose a PNG, JPG, WEBP, GIF, BMP, ICO, or SVG image.')
  const stem = path.basename(cleanName, extFromName || ext).trim() || 'avatar'
  return `${stem}${ext}`
}

function managedAvatarFileName(agentId: string, sourcePath: string) {
  const ext = path.extname(sourcePath).toLowerCase() || '.png'
  const stem = path.basename(sourcePath, path.extname(sourcePath))
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 42) || 'avatar'
  return `${agentId}-${stem}-${Date.now().toString(36)}-${randomBytes(4).toString('hex')}${ext}`
}

async function persistAgentAvatarBytes(agentId: string, bytes: Buffer, sourceName: string) {
  if (!isValidAgentId(agentId)) throw new Error('Invalid agent id.')
  if (!Buffer.isBuffer(bytes) || bytes.length === 0) throw new Error('Choose an image file to upload.')
  if (bytes.length > AVATAR_UPLOAD_LIMIT_BYTES) throw new Error('Choose an image smaller than 15 MB.')
  if (!isSupportedAvatarImagePath(sourceName)) {
    throw new Error('Choose a PNG, JPG, WEBP, GIF, BMP, ICO, or SVG image.')
  }

  const { config, target } = await getAgentById(agentId)
  if (!target) throw new Error(`Agent not found: ${agentId}`)
  const local = await ensureAgentLocalConfig({
    agentId: target.id,
    entry: target,
    defaultsModel: config.agents?.defaults?.model || {},
    defaultsSandbox: (config.agents?.defaults as { sandbox?: AgentSandboxConfig } | undefined)?.sandbox,
  })
  const workspace = normalizeExecutionWorkspacePath(local.routing.workspace || defaultAgentWorkspace(target.id))
  const avatarDir = path.join(workspace, '.openclaw', 'avatars')
  await fs.mkdir(avatarDir, { recursive: true })
  const avatarPath = path.join(avatarDir, managedAvatarFileName(target.id, sourceName))
  await fs.writeFile(avatarPath, bytes)
  const avatar = path.relative(workspace, avatarPath)

  local.identity.avatar = avatar
  local.agent.updatedAt = new Date().toISOString()
  applyExecutionWorkspaceToLocalConfig(local, workspace)
  await writeTextFileWithLockRetry(agentLocalConfigPath(target.id), `${JSON.stringify(local, null, 2)}\n`)
  await rememberAgentLocalConfigCache(agentLocalConfigPath(target.id), local)
  applyLocalConfigToGlobal(target.id, local, config)
  await writeOpenclawConfig(config)

  return {
    agentId: target.id,
    avatar,
    avatarPath,
    previewUrl: `/api/party/avatar/${encodeURIComponent(target.id)}?v=${Date.now()}`,
  }
}

async function persistAgentAvatarFromPath(agentId: string, sourcePath: string) {
  if (!isValidAgentId(agentId)) throw new Error('Invalid agent id.')
  const selectedPath = path.resolve(sourcePath)
  if (!isSupportedAvatarImagePath(selectedPath)) {
    throw new Error('Choose a PNG, JPG, WEBP, GIF, BMP, ICO, or SVG image.')
  }
  const stat = await fs.stat(selectedPath)
  if (!stat.isFile()) throw new Error('Selected avatar is not a file.')
  if (stat.size > 15 * 1024 * 1024) throw new Error('Choose an image smaller than 15 MB.')

  const { config, target } = await getAgentById(agentId)
  if (!target) throw new Error(`Agent not found: ${agentId}`)
  const local = await ensureAgentLocalConfig({
    agentId: target.id,
    entry: target,
    defaultsModel: config.agents?.defaults?.model || {},
    defaultsSandbox: (config.agents?.defaults as { sandbox?: AgentSandboxConfig } | undefined)?.sandbox,
  })
  const workspace = normalizeExecutionWorkspacePath(local.routing.workspace || defaultAgentWorkspace(target.id))
  const avatarDir = path.join(workspace, '.openclaw', 'avatars')
  await fs.mkdir(avatarDir, { recursive: true })
  const avatarPath = path.join(avatarDir, managedAvatarFileName(target.id, selectedPath))
  await fs.copyFile(selectedPath, avatarPath)
  const avatar = path.relative(workspace, avatarPath)

  local.identity.avatar = avatar
  local.agent.updatedAt = new Date().toISOString()
  applyExecutionWorkspaceToLocalConfig(local, workspace)
  await writeTextFileWithLockRetry(agentLocalConfigPath(target.id), `${JSON.stringify(local, null, 2)}\n`)
  await rememberAgentLocalConfigCache(agentLocalConfigPath(target.id), local)
  applyLocalConfigToGlobal(target.id, local, config)
  await writeOpenclawConfig(config)

  return {
    agentId: target.id,
    sourcePath: selectedPath,
    avatar,
    avatarPath,
    previewUrl: `/api/party/avatar/${encodeURIComponent(target.id)}?v=${Date.now()}`,
  }
}

async function finishImagePickerSession(
  session: ImagePickerSession,
  picked: { ok: boolean; path?: string; cancelled?: boolean; detail?: string },
) {
  if (picked.ok && picked.path) {
    const selectedPath = path.resolve(picked.path)
    session.sourcePath = selectedPath
    if (session.agentId) {
      const persisted = await persistAgentAvatarFromPath(session.agentId, selectedPath)
      session.path = persisted.avatarPath
      session.avatar = persisted.avatar
      session.previewUrl = persisted.previewUrl
      session.detail = 'Profile picture selected.'
    } else {
      session.path = selectedPath
      session.detail = 'Image selected.'
    }
    session.status = 'selected'
  } else if (picked.cancelled) {
    session.status = 'cancelled'
    session.path = null
    session.detail = 'No image selected.'
  } else {
    session.status = 'error'
    session.path = null
    session.detail = picked.detail || 'No supported native image picker is available in this environment.'
  }
  session.updatedAt = Date.now()
  session.expiresAt = Date.now() + FOLDER_PICKER_SESSION_TTL_MS
}

async function launchWindowsImagePickerSession(session: ImagePickerSession, startPath: string) {
  const pickerDir = path.join(OPENCLAW_STATE_ROOT, 'tmp', 'image-picker')
  const scriptPath = path.join(pickerDir, `${session.id}.ps1`)
  const launcherPath = path.join(pickerDir, `${session.id}.cmd`)
  const outputPath = path.join(pickerDir, `${session.id}.json`)
  let finished = false
  let pollTimer: ReturnType<typeof setInterval> | null = null
  let timeoutTimer: ReturnType<typeof setTimeout> | null = null

  const finish = async (status: FolderPickerSessionStatus, detail?: string, selectedPath?: string | null) => {
    if (finished) return
    finished = true
    if (pollTimer) clearInterval(pollTimer)
    if (timeoutTimer) clearTimeout(timeoutTimer)
    try {
      if (status === 'selected' && selectedPath) {
        await finishImagePickerSession(session, { ok: true, path: selectedPath })
      } else {
        await finishImagePickerSession(session, { ok: false, cancelled: status === 'cancelled', detail })
      }
    } catch (error) {
      session.status = 'error'
      session.path = null
      session.detail = error instanceof Error && error.message ? error.message : String(error)
      session.updatedAt = Date.now()
      session.expiresAt = Date.now() + FOLDER_PICKER_SESSION_TTL_MS
    }
    setTimeout(() => {
      void fs.unlink(scriptPath).catch(() => {})
      void fs.unlink(launcherPath).catch(() => {})
      void fs.unlink(outputPath).catch(() => {})
    }, FOLDER_PICKER_SESSION_TTL_MS)
  }

  const readOutput = async () => {
    try {
      const raw = await fs.readFile(outputPath, 'utf-8')
      const parsed = JSON.parse(raw.replace(/^\uFEFF/, '')) as { status?: string; path?: string | null; detail?: string }
      if (parsed.status === 'selected' && parsed.path?.trim()) {
        await finish('selected', 'Image selected.', parsed.path.trim())
      } else if (parsed.status === 'cancelled') {
        await finish('cancelled', parsed.detail || 'No image selected.')
      } else {
        await finish('error', parsed.detail || 'Image picker failed.')
      }
    } catch {
      // The helper has not written its result yet.
    }
  }

  try {
    await fs.mkdir(pickerDir, { recursive: true })
    const pickerStart = await resolvePickerStartPath(startPath)
    const script = [
      'param(',
      '  [Parameter(Mandatory=$true)][string]$OutPath,',
      '  [Parameter(Mandatory=$true)][string]$StartPath',
      ')',
      '$ErrorActionPreference = "Stop"',
      'function Write-PickerResult($value) {',
      '  $json = $value | ConvertTo-Json -Compress',
      '  $json | Set-Content -LiteralPath $OutPath -Encoding UTF8',
      '}',
      'try {',
      '  Add-Type -AssemblyName System.Windows.Forms',
      '  Add-Type -AssemblyName System.Drawing',
      '  [System.Windows.Forms.Application]::EnableVisualStyles()',
      '  $initialDirectory = $StartPath',
      '  if (-not [string]::IsNullOrWhiteSpace($initialDirectory) -and (Test-Path -LiteralPath $initialDirectory -PathType Leaf)) {',
      '    $initialDirectory = Split-Path -LiteralPath $initialDirectory -Parent',
      '  }',
      '  if ([string]::IsNullOrWhiteSpace($initialDirectory) -or -not (Test-Path -LiteralPath $initialDirectory -PathType Container)) {',
      '    $initialDirectory = [System.Environment]::GetFolderPath("Pictures")',
      '  }',
      '  if ([string]::IsNullOrWhiteSpace($initialDirectory) -or -not (Test-Path -LiteralPath $initialDirectory -PathType Container)) {',
      '    $initialDirectory = [System.Environment]::GetFolderPath("DesktopDirectory")',
      '  }',
      '  $owner = New-Object System.Windows.Forms.Form',
      '  $owner.Text = "DystopAI Profile Picture"',
      '  $owner.StartPosition = "CenterScreen"',
      '  $owner.Size = New-Object System.Drawing.Size(320, 80)',
      '  $owner.TopMost = $true',
      '  $owner.ShowInTaskbar = $true',
      '  $owner.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedToolWindow',
      '  $owner.Show()',
      '  $owner.BringToFront()',
      '  $owner.Activate()',
      '  [System.Windows.Forms.Application]::DoEvents()',
      '  $dialog = New-Object System.Windows.Forms.OpenFileDialog',
      '  $dialog.Title = "Choose agent profile picture"',
      '  $dialog.InitialDirectory = $initialDirectory',
      '  $dialog.CheckFileExists = $true',
      '  $dialog.Multiselect = $false',
      '  $dialog.Filter = "Image files (*.png;*.jpg;*.jpeg;*.webp;*.gif;*.bmp;*.ico;*.svg)|*.png;*.jpg;*.jpeg;*.webp;*.gif;*.bmp;*.ico;*.svg|All files (*.*)|*.*"',
      '  $result = $dialog.ShowDialog($owner)',
      '  $owner.Dispose()',
      '  if ($result -eq [System.Windows.Forms.DialogResult]::OK -and -not [string]::IsNullOrWhiteSpace($dialog.FileName)) {',
      '    Write-PickerResult @{ status = "selected"; path = $dialog.FileName }',
      '    exit 0',
      '  }',
      '  Write-PickerResult @{ status = "cancelled"; detail = "No image selected." }',
      '  exit 0',
      '} catch {',
      '  Write-PickerResult @{ status = "error"; detail = $_.Exception.Message }',
      '  exit 1',
      '}',
      '',
    ].join('\n')
    await fs.writeFile(scriptPath, script, 'utf-8')
    await writeWindowsPickerLauncher(launcherPath, 'DystopAI Profile Picture', scriptPath, outputPath, pickerStart)
    const launcher = spawn('cmd.exe', ['/d', '/s', '/c', launcherPath], {
      detached: true,
      stdio: 'ignore',
      windowsHide: false,
    })
    launcher.unref()
    launcher.once('error', (error) => {
      void finish('error', String(error))
    })
    pollTimer = setInterval(() => {
      void readOutput()
    }, 500)
    timeoutTimer = setTimeout(() => {
      void finish('error', `Image picker timed out after ${Math.round(FOLDER_PICKER_TIMEOUT_MS / 1000)} seconds. Try Browse again.`)
    }, FOLDER_PICKER_TIMEOUT_MS)
  } catch (error) {
    await finish('error', String(error))
  }
}

function runPickerCommand(command: string, args: string[], options: PickerCommandOptions = {}): Promise<{ ok: boolean; path?: string; detail?: string }> {
  return new Promise((resolve) => {
    const timeoutMs = options.timeoutMs ?? FOLDER_PICKER_TIMEOUT_MS
    const label = options.label || 'Folder picker'
    let settled = false
    let timeout: ReturnType<typeof setTimeout> | null = null
    const finish = (result: { ok: boolean; path?: string; detail?: string }) => {
      if (settled) return
      settled = true
      if (timeout) clearTimeout(timeout)
      options.abortSignal?.removeEventListener('abort', onAbort)
      resolve(result)
    }
    const child = spawn(command, args, { shell: false, windowsHide: options.windowsHide ?? true })
    let stdout = ''
    let stderr = ''
    const onAbort = () => {
      try {
        child.kill()
      } catch {
        // The process may already have exited.
      }
      finish({ ok: false, detail: `${label} request was cancelled before it completed.` })
    }
    if (options.abortSignal?.aborted) {
      onAbort()
      return
    }
    options.abortSignal?.addEventListener('abort', onAbort, { once: true })
    child.stdout.on('data', (chunk) => {
      stdout += chunk.toString()
    })
    child.stderr.on('data', (chunk) => {
      stderr += chunk.toString()
    })
    child.once('error', (error) => {
      finish({ ok: false, detail: String(error) })
    })
    child.once('close', (code) => {
      const selected = stdout.trim().split(/\r?\n/).find(Boolean)?.trim()
      if (code === 0 && selected) finish({ ok: true, path: selected })
      else finish({ ok: false, detail: stderr.trim() || stdout.trim() || `exit:${code ?? 1}` })
    })
    if (timeoutMs > 0) {
      timeout = setTimeout(() => {
        try {
          child.kill()
        } catch {
          // The process may already have exited.
        }
        finish({
          ok: false,
          detail: `${label} timed out after ${Math.round(timeoutMs / 1000)} seconds. Try Browse again.`,
        })
      }, timeoutMs)
    }
  })
}

async function resolvePickerStartPath(startPath?: string) {
  let current = normalizePickerStartPath(startPath)
  for (let depth = 0; depth < 32; depth += 1) {
    try {
      const stat = await fs.stat(current)
      if (stat.isDirectory()) return current
      if (stat.isFile()) current = path.dirname(current)
    } catch {
      const parent = path.dirname(current)
      if (parent === current) break
      current = parent
    }
  }
  return WORKSPACE_ROOT
}

function normalizePickerStartPath(startPath?: string, fallbackPath = WORKSPACE_ROOT) {
  const fallback = path.resolve(fallbackPath || WORKSPACE_ROOT)
  const raw = startPath?.trim() || ''
  if (!raw || raw.includes('\0')) return fallback
  if (/^(?:https?|data|blob):/i.test(raw)) return fallback
  if (/^[\\/](?:api|agents)[\\/]/i.test(raw)) return fallback
  if (/^file:/i.test(raw)) {
    try {
      return path.resolve(fileURLToPath(raw))
    } catch {
      return fallback
    }
  }
  return path.resolve(raw)
}

async function pickFolderWithElectron(startPath?: string): Promise<{ ok: boolean; path?: string; cancelled?: boolean; detail?: string }> {
  try {
    const defaultPath = await resolvePickerStartPath(startPath)
    const electron = optionalRequire('electron') as {
      dialog?: {
        showOpenDialog?: (options: {
          title?: string
          defaultPath?: string
          properties?: Array<'openDirectory' | 'createDirectory'>
        }) => Promise<{ canceled: boolean; filePaths: string[] }>
      }
    }
    const result = await electron.dialog?.showOpenDialog?.({
      title: 'Select Agent Workspace',
      defaultPath,
      properties: ['openDirectory', 'createDirectory'],
    })
    if (!result) return { ok: false, detail: 'Electron dialog is unavailable.' }
    if (result.canceled) return { ok: false, cancelled: true }
    const selected = result.filePaths[0]
    return selected ? { ok: true, path: selected } : { ok: false, cancelled: true }
  } catch (error) {
    return { ok: false, detail: String(error) }
  }
}

async function pickFolderWithOsDialog(startPath?: string, abortSignal?: AbortSignal): Promise<{ ok: boolean; path?: string; cancelled?: boolean; detail?: string }> {
  const pickerStart = await resolvePickerStartPath(startPath)
  const electronResult = await pickFolderWithElectron(pickerStart)
  if (electronResult.ok || electronResult.cancelled) return electronResult

  if (process.platform === 'win32') {
    const script = [
      '[Console]::OutputEncoding = [System.Text.Encoding]::UTF8',
      'Add-Type -AssemblyName System.Windows.Forms',
      'Add-Type -AssemblyName System.Drawing',
      '[System.Windows.Forms.Application]::EnableVisualStyles()',
      `$initialDirectory = ${JSON.stringify(pickerStart)}`,
      'if (-not [string]::IsNullOrWhiteSpace($initialDirectory) -and (Test-Path -LiteralPath $initialDirectory -PathType Leaf)) { $initialDirectory = Split-Path -LiteralPath $initialDirectory -Parent }',
      'if ([string]::IsNullOrWhiteSpace($initialDirectory) -or -not (Test-Path -LiteralPath $initialDirectory -PathType Container)) { $initialDirectory = [System.Environment]::GetFolderPath("DesktopDirectory") }',
      '$owner = New-Object System.Windows.Forms.Form',
      '$owner.Text = "Select Agent Workspace"',
      '$owner.StartPosition = "CenterScreen"',
      '$owner.Size = New-Object System.Drawing.Size(1, 1)',
      '$owner.TopMost = $true',
      '$owner.ShowInTaskbar = $false',
      '$owner.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedToolWindow',
      '$owner.Show()',
      '$owner.BringToFront()',
      '$owner.Activate()',
      '[System.Windows.Forms.Application]::DoEvents()',
      '$dialog = New-Object System.Windows.Forms.FolderBrowserDialog',
      '$dialog.Description = "Select Agent Workspace"',
      '$dialog.SelectedPath = $initialDirectory',
      '$dialog.ShowNewFolderButton = $true',
      '$result = $dialog.ShowDialog($owner)',
      '$owner.Dispose()',
      'if ($result -eq [System.Windows.Forms.DialogResult]::OK -and -not [string]::IsNullOrWhiteSpace($dialog.SelectedPath)) { Write-Output $dialog.SelectedPath; exit 0 }',
      'exit 1',
    ].filter(Boolean).join('; ')
    return runPickerCommand('powershell.exe', ['-NoProfile', '-STA', '-Command', script], {
      abortSignal,
      windowsHide: true,
    })
  }

  if (process.platform === 'darwin') {
    const script = `POSIX path of (choose folder with prompt "Select Agent Workspace" default location POSIX file ${JSON.stringify(pickerStart)})`
    return runPickerCommand('osascript', ['-e', script], { abortSignal })
  }

  const zenity = await runPickerCommand('zenity', [
    '--file-selection',
    '--directory',
    '--title=Select Agent Workspace',
    `--filename=${pickerStart.endsWith(path.sep) ? pickerStart : `${pickerStart}${path.sep}`}`,
  ], { abortSignal })
  if (zenity.ok || !/ENOENT|not found/i.test(zenity.detail || '')) return zenity

  return runPickerCommand('kdialog', [
    '--getexistingdirectory',
    pickerStart,
    '--title',
    'Select Agent Workspace',
  ], { abortSignal })
}

